import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, ThumbsUp, AlertCircle, Clock, CheckCircle } from 'lucide-react';
import { SortingLevel } from '../types';
import { generateSortingLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const SortingGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SortingLevel | null>(null);
  const [currentItemIndex, setCurrentItemIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [timeBonus, setTimeBonus] = useState(0);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [completed, setCompleted] = useState(false);

  const startTimeRef = useRef<number>(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const timerIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    loadLevel();
    return () => stopTimer();
  }, []);

  const startTimer = () => {
    stopTimer();
    startTimeRef.current = Date.now();
    setElapsedTime(0);
    timerIntervalRef.current = setInterval(() => {
      setElapsedTime(Math.floor((Date.now() - startTimeRef.current) / 1000));
    }, 1000);
  };

  const stopTimer = () => {
    if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
  };

  const loadLevel = async () => {
    setLevel(null); 
    setLoading(true);
    setCompleted(false);
    setCurrentItemIndex(0);
    setScore(0);
    setTimeBonus(0);
    setFeedback(null);

    const newLevel = await generateSortingLevel();
    setLevel(newLevel);
    setLoading(false);
    startTimer();
  };

  const handleSort = (selectedCategory: 'A' | 'B') => {
    if (!level) return;

    const currentItem = level.items[currentItemIndex];
    const isCorrect = currentItem.category === selectedCategory;

    if (isCorrect) {
      setScore(s => s + 10);
      setFeedback('correct');
    } else {
      setFeedback('wrong');
    }

    setTimeout(() => {
      setFeedback(null);
      if (currentItemIndex < level.items.length - 1) {
        setCurrentItemIndex(i => i + 1);
      } else {
        finishGame();
      }
    }, 600);
  };

  const finishGame = () => {
    stopTimer();
    const totalTime = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const calculatedBonus = Math.max(0, (60 - totalTime) * 2);
    setTimeBonus(calculatedBonus);
    setCompleted(true);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-orange-50">
        <Loader2 className="w-12 h-12 text-orange-500 animate-spin mb-4" />
        <p className="text-orange-700 text-lg">AI 正在準備題目中...</p>
      </div>
    );
  }

  if (!level) return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-orange-50">
      <button onClick={loadLevel} className="px-4 py-2 bg-orange-500 text-white rounded">重試</button>
    </div>
  );

  return (
    <div className="flex flex-col h-screen bg-orange-50 overflow-hidden">
      {/* Header - Compact for landscape */}
      <div className="flex-none p-2 sm:p-4 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-orange-800 shadow-sm hover:bg-orange-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex gap-4">
          <div className="flex items-center text-orange-800 font-bold bg-orange-100 px-3 py-1 rounded-full text-sm md:text-base">
            <Clock size={16} className="mr-2" />
            {elapsedTime}s
          </div>
          <div className="font-bold text-orange-800 text-sm md:text-base bg-orange-100 px-3 py-1 rounded-full">
            分數: {score}
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-2 sm:p-4 w-full max-w-4xl mx-auto overflow-y-auto">

        {!completed ? (
          <div className="flex flex-col sm:flex-row w-full gap-4 sm:gap-8 items-center h-full sm:max-h-[500px]">
            {/* Left: Card */}
            <div className="w-full sm:w-1/2 flex flex-col items-center justify-center h-full min-h-[200px]">
                <div className="w-full bg-orange-200 h-2 rounded-full mb-4 sm:mb-8 overflow-hidden">
                    <div 
                        className="bg-orange-500 h-full transition-all duration-300 ease-out"
                        style={{ width: `${(currentItemIndex / level.items.length) * 100}%` }}
                    ></div>
                </div>

                <div className="relative w-full h-full max-h-[300px] aspect-[3/2] sm:aspect-square flex items-center justify-center perspective">
                    <div className={`
                        w-full h-full bg-white rounded-2xl shadow-xl flex flex-col items-center justify-center border-4 p-4 text-center
                        transition-all duration-200 transform
                        ${feedback === 'correct' ? 'border-green-400 bg-green-50 scale-105' : ''}
                        ${feedback === 'wrong' ? 'border-red-400 bg-red-50 shake' : 'border-white'}
                    `}>
                        <h3 className="text-4xl sm:text-5xl font-bold text-gray-800 mb-2 sm:mb-4 tracking-wider">{level.items[currentItemIndex].name}</h3>
                        <p className="text-gray-500 text-sm sm:text-lg">這個屬於哪一類？</p>

                        {feedback === 'correct' && <ThumbsUp className="absolute text-green-500 w-24 h-24 sm:w-32 sm:h-32 opacity-80 animate-ping" />}
                        {feedback === 'wrong' && <AlertCircle className="absolute text-red-500 w-24 h-24 sm:w-32 sm:h-32 opacity-80" />}
                    </div>
                </div>
            </div>

            {/* Right: Buttons */}
            <div className="w-full sm:w-1/2 grid grid-cols-2 gap-4 h-32 sm:h-auto sm:flex-1">
              <button
                disabled={feedback !== null}
                onClick={() => handleSort('A')}
                className="h-full bg-blue-100 hover:bg-blue-200 active:bg-blue-300 text-blue-900 rounded-2xl shadow-md flex flex-col items-center justify-center transition-all active:scale-95 disabled:opacity-50 p-2"
              >
                <span className="text-xl sm:text-3xl font-bold">{level.categoryA}</span>
              </button>
              <button
                disabled={feedback !== null}
                onClick={() => handleSort('B')}
                className="h-full bg-green-100 hover:bg-green-200 active:bg-green-300 text-green-900 rounded-2xl shadow-md flex flex-col items-center justify-center transition-all active:scale-95 disabled:opacity-50 p-2"
              >
                <span className="text-xl sm:text-3xl font-bold">{level.categoryB}</span>
              </button>
            </div>
          </div>
        ) : (
          <div className="w-full max-w-3xl bg-white rounded-3xl shadow-xl p-4 sm:p-8 flex flex-col sm:flex-row gap-8 animate-fade-in-up overflow-y-auto max-h-full">
            <div className="flex-1">
                <h3 className="text-2xl font-bold text-orange-600 mb-4 text-center">分類回顧</h3>
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-blue-50 p-4 rounded-xl">
                        <h4 className="font-bold text-blue-800 mb-2 border-b border-blue-200 pb-1">{level.categoryA}</h4>
                        <ul className="text-blue-700 text-sm md:text-base space-y-1">
                            {level.items.filter(i => i.category === 'A').map(i => (
                                <li key={i.id} className="flex items-center"><CheckCircle size={14} className="mr-1"/> {i.name}</li>
                            ))}
                        </ul>
                    </div>
                    <div className="bg-green-50 p-4 rounded-xl">
                        <h4 className="font-bold text-green-800 mb-2 border-b border-green-200 pb-1">{level.categoryB}</h4>
                        <ul className="text-green-700 text-sm md:text-base space-y-1">
                            {level.items.filter(i => i.category === 'B').map(i => (
                                <li key={i.id} className="flex items-center"><CheckCircle size={14} className="mr-1"/> {i.name}</li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col justify-center items-center border-t sm:border-t-0 sm:border-l border-gray-100 pt-4 sm:pt-0 sm:pl-8">
                <div className="text-center mb-6">
                    <p className="text-gray-500 text-sm mb-1">總分</p>
                    <p className="text-6xl font-black text-orange-600">{score + timeBonus}</p>
                    <div className="flex gap-4 justify-center mt-2 text-sm">
                        <span className="text-gray-400">答題: {score}</span>
                        <span className="text-yellow-500 font-bold">時間: +{timeBonus}</span>
                    </div>
                </div>
                <button 
                onClick={loadLevel}
                className="w-full py-4 bg-orange-500 text-white rounded-xl font-bold text-xl shadow-lg hover:bg-orange-600 hover:shadow-xl transition-all active:scale-95"
                >
                挑戰下一關
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SortingGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Footprints, X } from 'lucide-react';
import { MemoryCard } from '../types';
import { generateEncouragement } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const EMOJIS = ['🐶', '🐱', '🐭', '🐹', '🐰', '🦊', '🐻', '🐼'];

const MemoryGame: React.FC<Props> = ({ onBack }) => {
  const [cards, setCards] = useState<MemoryCard[]>([]);
  const [flippedIndices, setFlippedIndices] = useState<number[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isWon, setIsWon] = useState(false);
  const [moves, setMoves] = useState(0);
  const [encouragement, setEncouragement] = useState("");
  const [isMismatchWaiting, setIsMismatchWaiting] = useState(false);

  const initializeGame = () => {
    // Create pairs
    const gameItems = [...EMOJIS, ...EMOJIS];
    // Shuffle
    for (let i = gameItems.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [gameItems[i], gameItems[j]] = [gameItems[j], gameItems[i]];
    }

    setCards(gameItems.map((emoji, index) => ({
      id: index,
      content: emoji,
      isFlipped: false,
      isMatched: false
    })));
    setFlippedIndices([]);
    setIsWon(false);
    setMoves(0);
    setEncouragement("");
    setIsMismatchWaiting(false);
    setIsProcessing(false);
  };

  useEffect(() => {
    initializeGame();
  }, []);

  const handleCardClick = (index: number) => {
    // Block clicks if processing, already flipped/matched, OR if waiting for manual reset
    if (isProcessing || isMismatchWaiting || cards[index].isFlipped || cards[index].isMatched) return;

    const newCards = [...cards];
    newCards[index].isFlipped = true;
    setCards(newCards);

    const newFlipped = [...flippedIndices, index];
    setFlippedIndices(newFlipped);

    if (newFlipped.length === 2) {
      setIsProcessing(true);
      setMoves(m => m + 1);

      const [firstIndex, secondIndex] = newFlipped;

      if (newCards[firstIndex].content === newCards[secondIndex].content) {
        // Match found - Auto proceed
        setTimeout(() => {
          newCards[firstIndex].isMatched = true;
          newCards[secondIndex].isMatched = true;
          setCards(newCards);
          setFlippedIndices([]);
          setIsProcessing(false);

          if (newCards.every(c => c.isMatched)) {
            handleWin();
          }
        }, 500);
      } else {
        // No match - Wait for manual reset
        setIsMismatchWaiting(true);
        setIsProcessing(false); 
      }
    }
  };

  const handleManualReset = () => {
    const newCards = [...cards];
    // Flip back the currently flipped cards that aren't matched
    flippedIndices.forEach(idx => {
        newCards[idx].isFlipped = false;
    });
    setCards(newCards);
    setFlippedIndices([]);
    setIsMismatchWaiting(false);
  };

  const handleWin = async () => {
    setIsWon(true);
    const msg = await generateEncouragement(100);
    setEncouragement(msg);
  };

  return (
    <div className="flex flex-col h-screen bg-indigo-50 overflow-hidden relative">
        {/* Header */}
      <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10">
        <button 
          onClick={onBack}
          className="p-2 bg-gray-100 rounded-full text-indigo-600 hover:bg-indigo-100"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center bg-indigo-100 px-4 py-1 rounded-full text-indigo-800 font-bold">
            <Footprints className="w-4 h-4 mr-2" />
            步數: {moves}
        </div>
        <button 
          onClick={initializeGame}
          className="p-2 bg-gray-100 rounded-full text-indigo-600 hover:bg-indigo-100"
        >
          <RefreshCw size={20} />
        </button>
      </div>

      {/* Game Area - Centered & Scrollable */}
      <div className="flex-1 flex items-center justify-center p-2 overflow-y-auto">
        <div className="relative">
            {/* Column Labels (A-D) */}
            <div className="flex mb-1 pl-8">
                {['A', 'B', 'C', 'D'].map(label => (
                    <div key={label} className="flex-1 text-center font-bold text-indigo-400 text-lg md:text-xl">
                        {label}
                    </div>
                ))}
            </div>

            <div className="flex">
                {/* Row Labels (1-4) */}
                <div className="flex flex-col w-8 justify-around pr-2">
                    {[1, 2, 3, 4].map(label => (
                        <div key={label} className="flex-1 flex items-center justify-center font-bold text-indigo-400 text-lg md:text-xl">
                            {label}
                        </div>
                    ))}
                </div>

                {/* Grid - Adjusted for landscape (limit height) */}
                <div className="grid grid-cols-4 gap-2 md:gap-3 
                    w-[80vw] max-w-[400px] aspect-square
                    sm:h-[65vh] sm:w-[65vh] sm:max-w-none sm:max-h-none
                ">
                    {cards.map((card, index) => (
                    <div
                        key={card.id}
                        onClick={() => handleCardClick(index)}
                        className={`relative cursor-pointer perspective-1000 w-full h-full`}
                    >
                        {/* Card Inner */}
                        <div className={`
                            w-full h-full absolute inset-0
                            transition-all duration-500 transform
                            flex items-center justify-center
                            border-2 rounded-lg md:rounded-xl shadow-md
                            text-3xl md:text-5xl select-none
                            ${card.isFlipped || card.isMatched 
                                ? 'bg-white border-indigo-400 rotate-y-180' 
                                : 'bg-indigo-300 border-indigo-300'}
                            ${isMismatchWaiting && card.isFlipped && !card.isMatched ? 'border-red-400 ring-2 ring-red-200' : ''}
                        `}>
                            {/* We use a fixed container for the emoji to prevent layout shifts */}
                            <div className="w-full h-full flex items-center justify-center backface-hidden">
                                {(card.isFlipped || card.isMatched) ? card.content : ''}
                            </div>
                        </div>
                    </div>
                    ))}
                </div>
            </div>
        </div>
      </div>

      {/* Manual Reset Button Overlay */}
      {isMismatchWaiting && (
          <div className="absolute inset-x-0 bottom-4 sm:bottom-8 flex justify-center z-20 pointer-events-none">
              <button 
                onClick={handleManualReset}
                className="bg-indigo-600 text-white text-xl font-bold px-8 py-3 rounded-full shadow-xl hover:bg-indigo-700 animate-bounce-short border-4 border-white flex items-center pointer-events-auto"
              >
                  <RefreshCw className="mr-2 w-6 h-6" />
                  蓋上卡片
              </button>
          </div>
      )}

      {isWon && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl p-6 md:p-8 max-w-sm w-full text-center shadow-2xl animate-bounce-short">
            <Trophy className="w-16 h-16 md:w-20 md:h-20 text-yellow-400 mx-auto mb-4" />
            <h3 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">恭喜完成！</h3>
            <p className="text-gray-500 mb-6">{encouragement || "很棒！大腦活化成功。"}</p>

            <div className="bg-indigo-50 rounded-xl p-4 mb-6 border-2 border-indigo-100">
                <p className="text-indigo-900 font-medium mb-1 text-sm">本次使用總步數</p>
                <div className="text-4xl md:text-6xl font-black text-indigo-600 flex items-center justify-center">
                    {moves}
                    <span className="text-xl md:text-2xl ml-2 font-normal text-indigo-400">步</span>
                </div>
            </div>

            <button
              onClick={initializeGame}
              className="w-full py-3 bg-indigo-600 text-white rounded-xl font-semibold hover:bg-indigo-700 transition-colors shadow-lg"
            >
              再挑戰一次
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default MemoryGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, RotateCcw, Check, XCircle, Trophy } from 'lucide-react';
import { SentenceLevel } from '../types';
import { generateSentenceLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const SentenceGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SentenceLevel | null>(null);
  const [userAnswer, setUserAnswer] = useState<{id: string, text: string}[]>([]);
  const [availableWords, setAvailableWords] = useState<{id: string, text: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Session & Scoring
  const [round, setRound] = useState(1);
  const [totalScore, setTotalScore] = useState(0);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startNewRound();
  }, []);

  const startNewRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);

    const data = await generateSentenceLevel();
    setLevel(data);
    setAvailableWords(data.scrambled);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    // Base 20 pts. Speed bonus: if < 5s, +10. if < 10s, +5.
    let bonus = 0;
    if (timeTaken < 5) bonus = 10;
    else if (timeTaken < 10) bonus = 5;
    return 20 + bonus;
  };

  const handleSelectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setUserAnswer([...userAnswer, word]);
    setAvailableWords(availableWords.filter(w => w.id !== word.id));
  };

  const handleDeselectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setAvailableWords([...availableWords, word]);
    setUserAnswer(userAnswer.filter(w => w.id !== word.id));
  };

  const checkAnswer = () => {
    if (!level) return;
    const currentString = userAnswer.map(w => w.text).join('');
    if (currentString === level.original) {
        // Correct
        const roundScore = calculateScore();
        setTotalScore(s => s + roundScore);
        setIsCorrect(true);
        // Wait a bit then next round
        setTimeout(() => {
             if (round < TOTAL_ROUNDS) {
                setRound(r => r + 1);
                startNewRound();
             } else {
                setIsSessionFinished(true);
             }
        }, 1500);

    } else {
        // Wrong (No penalty)
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const resetCurrent = () => {
    if (!level) return;
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);
    setAvailableWords(level.scrambled);
  }

  const handleRestart = () => {
      setRound(1);
      setTotalScore(0);
      setIsSessionFinished(false);
      startNewRound();
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50 p-4 animate-fade-in overflow-y-auto">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200 my-4">
              <Trophy className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">練習完成！</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{totalScore}</div>
              <p className="text-gray-600 mb-8">
                  你的造句能力很棒！<br/>邏輯非常清晰。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
}

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50">
        <Loader2 className="w-12 h-12 text-pink-500 animate-spin mb-4" />
        <p className="text-pink-700">準備句子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-pink-50 overflow-hidden">
      <div className="flex-none p-4 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-pink-800 shadow-sm hover:bg-pink-100">
          <ArrowLeft size={24} />
        </button>
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-pink-800 hidden md:block">造句拼拼樂</h2>
             <div className="px-3 py-1 bg-pink-100 rounded-full text-pink-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-pink-100 px-3 py-1 rounded-full text-pink-800 font-bold">
                <Trophy size={16} className="mr-2"/> {totalScore}
             </div>
        </div>
        <button onClick={startNewRound} className="px-3 py-1 bg-white rounded-full text-pink-600 text-sm font-medium hover:bg-pink-100 shadow-sm">
            跳過
        </button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 max-w-4xl mx-auto w-full gap-8 relative overflow-y-auto">

        {/* Error Toast */}
        {showError && (
            <div className="absolute top-0 animate-bounce-short z-50 bg-red-100 border-2 border-red-400 text-red-700 px-6 py-3 rounded-full flex items-center shadow-lg">
                <XCircle className="w-6 h-6 mr-2" />
                <span className="font-bold">順序不對喔，再試試看！</span>
            </div>
        )}

        {/* Answer Area */}
        <div className="w-full flex flex-col items-center">
             <p className="text-gray-500 mb-2">點擊下方字卡，組成通順的句子：</p>
             <div className={`w-full min-h-[80px] bg-white rounded-2xl shadow-inner p-4 flex flex-wrap gap-2 items-center justify-center border-4 transition-colors duration-300 ${isCorrect ? 'border-green-400 bg-green-50' : showError ? 'border-red-300 bg-red-50' : 'border-pink-200'}`}>
                {userAnswer.length === 0 && !isCorrect && <span className="text-gray-300">答案區</span>}
                {userAnswer.map(word => (
                    <button 
                        key={word.id} 
                        onClick={() => handleDeselectWord(word)}
                        className="bg-pink-500 text-white text-2xl font-bold px-4 py-3 rounded-xl shadow-md hover:bg-pink-600 transition-all animate-fade-in"
                    >
                        {word.text}
                    </button>
                ))}
                {isCorrect && <Check className="text-green-500 w-8 h-8 ml-2 animate-bounce"/>}
             </div>
        </div>

        {/* Available Words Area */}
        <div className="w-full flex flex-wrap gap-3 justify-center min-h-[100px] content-start">
            {availableWords.map(word => (
                <button 
                    key={word.id} 
                    onClick={() => handleSelectWord(word)}
                    className="bg-white text-pink-700 text-2xl font-bold px-4 py-3 rounded-xl shadow border-2 border-pink-100 hover:border-pink-300 hover:scale-105 transition-all"
                >
                    {word.text}
                </button>
            ))}
        </div>

        {/* Controls */}
        <div className="flex gap-4 pb-4">
            <button 
                onClick={resetCurrent}
                disabled={isCorrect}
                className="flex items-center px-6 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300 transition disabled:opacity-50"
            >
                <RotateCcw size={20} className="mr-2"/> 重置
            </button>

            <button 
                onClick={checkAnswer}
                disabled={userAnswer.length === 0 || isCorrect}
                className="px-8 py-3 bg-pink-500 text-white rounded-xl font-bold shadow-lg hover:bg-pink-600 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
                {isCorrect ? "答對了！" : "確認"}
            </button>
        </div>

      </div>
    </div>
  );
};

