import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, RotateCcw, Check, XCircle, Trophy } from 'lucide-react';
import { SentenceLevel } from '../types';
import { generateSentenceLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const SentenceGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SentenceLevel | null>(null);
  const [userAnswer, setUserAnswer] = useState<{id: string, text: string}[]>([]);
  const [availableWords, setAvailableWords] = useState<{id: string, text: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Session & Scoring
  const [round, setRound] = useState(1);
  const [totalScore, setTotalScore] = useState(0);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startNewRound();
  }, []);

  const startNewRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);

    const data = await generateSentenceLevel();
    setLevel(data);
    setAvailableWords(data.scrambled);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    // Base 20 pts. Speed bonus: if < 5s, +10. if < 10s, +5.
    let bonus = 0;
    if (timeTaken < 5) bonus = 10;
    else if (timeTaken < 10) bonus = 5;
    return 20 + bonus;
  };

  const handleSelectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setUserAnswer([...userAnswer, word]);
    setAvailableWords(availableWords.filter(w => w.id !== word.id));
  };

  const handleDeselectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setAvailableWords([...availableWords, word]);
    setUserAnswer(userAnswer.filter(w => w.id !== word.id));
  };

  const checkAnswer = () => {
    if (!level) return;
    const currentString = userAnswer.map(w => w.text).join('');
    if (currentString === level.original) {
        // Correct
        const roundScore = calculateScore();
        setTotalScore(s => s + roundScore);
        setIsCorrect(true);
        // Wait a bit then next round
        setTimeout(() => {
             if (round < TOTAL_ROUNDS) {
                setRound(r => r + 1);
                startNewRound();
             } else {
                setIsSessionFinished(true);
             }
        }, 1500);

    } else {
        // Wrong (No penalty)
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const resetCurrent = () => {
    if (!level) return;
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);
    setAvailableWords(level.scrambled);
  }

  const handleRestart = () => {
      setRound(1);
      setTotalScore(0);
      setIsSessionFinished(false);
      startNewRound();
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50 p-4 animate-fade-in overflow-y-auto">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200 my-4">
              <Trophy className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">練習完成！</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{totalScore}</div>
              <p className="text-gray-600 mb-8">
                  你的造句能力很棒！<br/>邏輯非常清晰。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
}

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50">
        <Loader2 className="w-12 h-12 text-pink-500 animate-spin mb-4" />
        <p className="text-pink-700">準備句子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-pink-50 overflow-hidden">
      <div className="flex-none p-4 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-pink-800 shadow-sm hover:bg-pink-100">
          <ArrowLeft size={24} />
        </button>
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-pink-800 hidden md:block">造句拼拼樂</h2>
             <div className="px-3 py-1 bg-pink-100 rounded-full text-pink-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-pink-100 px-3 py-1 rounded-full text-pink-800 font-bold">
                <Trophy size={16} className="mr-2"/> {totalScore}
             </div>
        </div>
        <button onClick={startNewRound} className="px-3 py-1 bg-white rounded-full text-pink-600 text-sm font-medium hover:bg-pink-100 shadow-sm">
            跳過
        </button>
      </div>

      {/* Main Layout: Split view on Landscape (sm), Stacked on Portrait */}
      <div className="flex-1 flex flex-col sm:flex-row items-stretch justify-center p-4 max-w-6xl mx-auto w-full gap-4 sm:gap-8 relative overflow-hidden">

        {/* Error Toast */}
        {showError && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 animate-bounce-short z-50 bg-red-100 border-2 border-red-400 text-red-700 px-6 py-3 rounded-full flex items-center shadow-lg whitespace-nowrap">
                <XCircle className="w-6 h-6 mr-2" />
                <span className="font-bold">順序不對喔，再試試看！</span>
            </div>
        )}

        {/* LEFT: Answer Area (Canvas) */}
        <div className="flex-none sm:flex-1 flex flex-col items-center justify-center sm:bg-white/30 sm:rounded-3xl sm:p-4 overflow-hidden">
             <p className="text-gray-500 mb-2 sm:mb-4 text-sm sm:text-base">點擊字卡，組成通順的句子：</p>
             <div className={`
                w-full min-h-[80px] sm:min-h-[140px]
                bg-white rounded-2xl shadow-inner p-2 sm:p-4 
                flex flex-nowrap items-center gap-1 sm:gap-2 overflow-x-auto
                border-4 transition-colors duration-300 
                ${isCorrect ? 'border-green-400 bg-green-50' : showError ? 'border-red-300 bg-red-50' : 'border-pink-200'}
             `}>
                {userAnswer.length === 0 && !isCorrect && (
                   <span className="text-gray-300 text-lg w-full text-center">答案區</span>
                )}
                {userAnswer.map(word => (
                    <button 
                        key={word.id} 
                        onClick={() => handleDeselectWord(word)}
                        className="flex-shrink-0 bg-pink-500 text-white text-base sm:text-xl font-bold px-3 py-2 sm:px-5 sm:py-3 rounded-xl shadow-md hover:bg-pink-600 transition-all animate-fade-in"
                    >
                        {word.text}
                    </button>
                ))}
                {isCorrect && <Check className="text-green-500 w-6 h-6 sm:w-10 sm:h-10 ml-2 animate-bounce flex-shrink-0"/>}
             </div>
        </div>

        {/* RIGHT: Source Words & Controls */}
        <div className="flex-1 flex flex-col sm:h-full min-h-0">
            {/* Scrollable Word List */}
            <div className="flex-1 overflow-y-auto content-start p-1">
                <div className="flex flex-wrap gap-2 sm:gap-3 justify-center">
                    {availableWords.map(word => (
                        <button 
                            key={word.id} 
                            onClick={() => handleSelectWord(word)}
                            className="bg-white text-pink-700 text-lg sm:text-xl font-bold px-4 py-3 rounded-xl shadow border-2 border-pink-100 hover:border-pink-300 hover:scale-105 transition-all"
                        >
                            {word.text}
                        </button>
                    ))}
                </div>
            </div>

            {/* Fixed Controls Area at Bottom of Right Column */}
            <div className="flex-none pt-4 flex gap-3 sm:gap-4 border-t border-pink-100 mt-2">
                <button 
                    onClick={resetCurrent}
                    disabled={isCorrect}
                    className="flex-1 flex justify-center items-center px-4 py-3 sm:py-4 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300 transition disabled:opacity-50"
                >
                    <RotateCcw size={20} className="mr-2"/> <span className="hidden sm:inline">重置</span>
                </button>

                <button 
                    onClick={checkAnswer}
                    disabled={userAnswer.length === 0 || isCorrect}
                    className="flex-[2] py-3 sm:py-4 bg-pink-500 text-white rounded-xl font-bold shadow-lg hover:bg-pink-600 transition disabled:opacity-50 disabled:cursor-not-allowed text-lg"
                >
                    {isCorrect ? "答對了！" : "確認"}
                </button>
            </div>
        </div>

      </div>
    </div>
  );
};

export default SentenceGame;

