// --- SORTING GAME: Use Static Data ---
export const generateSortingLevel = async (): Promise<SortingLevel> => {
  // Simulate a very short delay for smoother UI feel (optional)
  await new Promise(resolve => setTimeout(resolve, 100));

  const randomIndex = Math.floor(Math.random() * STATIC_SORTING_LEVELS.length);
  const levelData = STATIC_SORTING_LEVELS[randomIndex];

  // Deep copy to avoid modifying the static data when shuffling
  const items = [...levelData.items.map(item => ({...item}))];

  // Shuffle items
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }

  return {
    categoryA: levelData.categoryA,
    categoryB: levelData.categoryB,
    items: items
  };
};

// --- SENTENCE GAME: Use Static Data ---
export const generateSentenceLevel = async (): Promise<SentenceLevel> => {
  await new Promise(resolve => setTimeout(resolve, 100));

  const randomIndex = Math.floor(Math.random() * STATIC_SENTENCES.length);
  const sentence = STATIC_SENTENCES[randomIndex];

  // Split into characters
  const chars = sentence.split('').map((char: string, index: number) => ({
    id: `${index}-${char}`,
    text: char
  }));

  // Shuffle
  const shuffled = [...chars];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return {
    original: sentence,
    scrambled: shuffled
  };
};

// --- FIND GAME: Use Static Data ---
// Now accepts round number to determine difficulty
export const generateFindLevel = async (round: number = 1): Promise<FindLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Difficulty Logic:
    // Round 1-2: Easy (Difficulty 1)
    // Round 3: Medium (Difficulty 2)
    // Round 4-5+: Hard (Difficulty 3)

    let targetDifficulty = 1;
    if (round >= 3 && round < 4) targetDifficulty = 2;
    if (round >= 4) targetDifficulty = 3;

    // Filter pairs by difficulty
    const eligiblePairs = STATIC_FIND_PAIRS.filter(p => p.difficulty === targetDifficulty);

    // Fallback if no pairs found (should not happen), use all pairs
    const pool = eligiblePairs.length > 0 ? eligiblePairs : STATIC_FIND_PAIRS;

    // Pick a random pair from the filtered pool
    const randomIndex = Math.floor(Math.random() * pool.length);
    const pair = pool[randomIndex];

    // Grid size: 4 columns * 4 rows = 16 items
    const gridSize = 16; 
    const targetPosition = Math.floor(Math.random() * gridSize);

    return { 
        target: pair.target, 
        distractor: pair.distractor, 
        gridSize, 
        targetPosition 
    };
}

// --- ENCOURAGEMENT: Use Static Data ---
