                        >
                            {word.text}
                        </button>
                    ))}
                </div>
            </div>

            {/* Controls */}
            <div className="flex-none flex gap-2 sm:gap-4 border-t border-pink-200 pt-2">
                <button 
                    onClick={resetCurrent}
