        <div className="flex items-center gap-4">
             <div className="px-3 py-1 bg-slate-200 rounded-full text-slate-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-slate-200 px-3 py-1 rounded-full text-slate-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 max-w-lg mx-auto w-full gap-4 md:gap-8">

        {/* Target Area */}
        <div className="bg-white p-4 md:p-8 rounded-[2rem] shadow-xl border-4 border-white ring-4 ring-slate-200 flex flex-col items-center shrink-0">
             <div className="text-7xl md:text-8xl filter drop-shadow-lg mb-2 md:mb-4 animate-bounce-short">
