import { SortingLevel, SentenceLevel, FindLevel, MarketLevel, StepsLevel, ShadowLevel } from "../types";
import { 
    STATIC_SENTENCES, 
    STATIC_SORTING_LEVELS, 
    STATIC_FIND_PAIRS, 
    STATIC_ENCOURAGEMENTS,
    STATIC_MARKET_LEVELS,
    STATIC_STEPS_LEVELS,
    STATIC_SHADOW_LEVELS
} from "./staticData";

// --- SORTING GAME: Use Static Data ---
export const generateSortingLevel = async (): Promise<SortingLevel> => {
  // Simulate a very short delay for smoother UI feel (optional)
  await new Promise(resolve => setTimeout(resolve, 100));

  const randomIndex = Math.floor(Math.random() * STATIC_SORTING_LEVELS.length);
  const levelData = STATIC_SORTING_LEVELS[randomIndex];

  // Deep copy to avoid modifying the static data when shuffling
  const items = [...levelData.items.map(item => ({...item}))];

  // Shuffle items
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }

  return {
    categoryA: levelData.categoryA,
    categoryB: levelData.categoryB,
    items: items
  };
};

// --- SENTENCE GAME: Use Static Data ---
export const generateSentenceLevel = async (): Promise<SentenceLevel> => {
  await new Promise(resolve => setTimeout(resolve, 100));

  const randomIndex = Math.floor(Math.random() * STATIC_SENTENCES.length);
  const sentence = STATIC_SENTENCES[randomIndex];

  // Split into characters
  const chars = sentence.split('').map((char: string, index: number) => ({
    id: `${index}-${char}`,
    text: char
  }));

  // Shuffle
  const shuffled = [...chars];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return {
    original: sentence,
    scrambled: shuffled
  };
};

// --- FIND GAME: Use Static Data ---
// Now accepts round number to determine difficulty
export const generateFindLevel = async (round: number = 1): Promise<FindLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Difficulty Logic:
    // Round 1-2: Easy (Difficulty 1)
    // Round 3: Medium (Difficulty 2)
    // Round 4-5+: Hard (Difficulty 3)

    let targetDifficulty = 1;
    if (round >= 3 && round < 4) targetDifficulty = 2;
    if (round >= 4) targetDifficulty = 3;

    // Filter pairs by difficulty
    const eligiblePairs = STATIC_FIND_PAIRS.filter(p => p.difficulty === targetDifficulty);

    // Fallback if no pairs found (should not happen), use all pairs
    const pool = eligiblePairs.length > 0 ? eligiblePairs : STATIC_FIND_PAIRS;

    // Pick a random pair from the filtered pool
    const randomIndex = Math.floor(Math.random() * pool.length);
    const pair = pool[randomIndex];

    // Grid size: 4 columns * 4 rows = 16 items
    const gridSize = 16; 
    const targetPosition = Math.floor(Math.random() * gridSize);

    return { 
        target: pair.target, 
        distractor: pair.distractor, 
        gridSize, 
        targetPosition 
    };
}

// --- ENCOURAGEMENT: Use Static Data ---
export const generateEncouragement = async (score: number): Promise<string> => {
    // Pick a random message
    const randomIndex = Math.floor(Math.random() * STATIC_ENCOURAGEMENTS.length);
    return STATIC_ENCOURAGEMENTS[randomIndex];
};

// --- NEW GAMES GENERATORS ---

export const generateMarketLevel = async (): Promise<MarketLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_MARKET_LEVELS.length);
    return STATIC_MARKET_LEVELS[randomIndex];
}

export const generateStepsLevel = async (excludeTitles: string[] = []): Promise<StepsLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Filter out used titles
    const availableLevels = STATIC_STEPS_LEVELS.filter(l => !excludeTitles.includes(l.title));

    // If we somehow run out (e.g. played > 50 rounds), fallback to the full list to prevent crashing
    const pool = availableLevels.length > 0 ? availableLevels : STATIC_STEPS_LEVELS;

    const randomIndex = Math.floor(Math.random() * pool.length);
    const level = pool[randomIndex];

    // Scramble the steps
    const steps = [...level.steps];
    for (let i = steps.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [steps[i], steps[j]] = [steps[j], steps[i]];
    }

    return {
        title: level.title,
        steps: steps
    };
}

export const generateShadowLevel = async (): Promise<ShadowLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_SHADOW_LEVELS.length);
    const level = STATIC_SHADOW_LEVELS[randomIndex];

    // Create a shuffled version of options
    const options = [...level.options];
    for (let i = options.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [options[i], options[j]] = [options[j], options[i]];
    }

    // Find the new correct index
    const correctIndex = options.indexOf(level.target);

    return {
        target: level.target,
        options: options,
        correctIndex: correctIndex
    };
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, ListChecks, RotateCcw, Check } from 'lucide-react';
import { StepsLevel, StepItem } from '../types';
import { generateStepsLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const StepsGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StepsLevel | null>(null);
  const [availableSteps, setAvailableSteps] = useState<StepItem[]>([]);
  const [userOrder, setUserOrder] = useState<StepItem[]>([]);
  const [loading, setLoading] = useState(true);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Track used titles to prevent repetition in a session
  const [usedTitles, setUsedTitles] = useState<string[]>([]);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserOrder([]);

    // Pass current history of used titles to filter them out
    const data = await generateStepsLevel(usedTitles);
    setLevel(data);
    setAvailableSteps(data.steps); 

    // Add new title to history
    setUsedTitles(prev => [...prev, data.title]);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 10) bonus = 10;
      else if (timeTaken < 20) bonus = 5;
      return 20 + bonus;
  }

  const handleSelectStep = (step: StepItem) => {
    if (isCorrect) return;
    setUserOrder([...userOrder, step]);
    setAvailableSteps(availableSteps.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleDeselectStep = (step: StepItem) => {
    if (isCorrect) return;
    setAvailableSteps([...availableSteps, step]);
    setUserOrder(userOrder.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleReset = () => {
     if (!level || isCorrect) return;
     setAvailableSteps([...availableSteps, ...userOrder]);
     setUserOrder([]);
  };

  const checkAnswer = () => {
    if (!level) return;

    let correct = true;
    for (let i = 0; i < userOrder.length; i++) {
        if (userOrder[i].order !== i + 1) {
            correct = false;
            break;
        }
    }

    if (correct && userOrder.length === level.steps.length) {
        setIsCorrect(true);
        const roundScore = calculateScore();
        setScore(s => s + roundScore);
        setTimeout(() => {
            if (round < TOTAL_ROUNDS) {
                setRound(r => r + 1);
                startRound();
            } else {
                setIsFinished(true);
            }
        }, 1500);
    } else {
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    setUsedTitles([]); // Reset history on restart
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-purple-200">
