import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, ListChecks, RotateCcw, Check } from 'lucide-react';
import { StepsLevel, StepItem } from '../types';
import { generateStepsLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const StepsGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StepsLevel | null>(null);
  const [availableSteps, setAvailableSteps] = useState<StepItem[]>([]);
  const [userOrder, setUserOrder] = useState<StepItem[]>([]);
  const [loading, setLoading] = useState(true);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Track used titles to prevent repetition in a session
  const [usedTitles, setUsedTitles] = useState<string[]>([]);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserOrder([]);

    // Pass current history of used titles to filter them out
    const data = await generateStepsLevel(usedTitles);
    setLevel(data);
    setAvailableSteps(data.steps); 

    // Add new title to history
    setUsedTitles(prev => [...prev, data.title]);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 10) bonus = 10;
      else if (timeTaken < 20) bonus = 5;
      return 20 + bonus;
  }

  const handleSelectStep = (step: StepItem) => {
    if (isCorrect) return;
    setUserOrder([...userOrder, step]);
    setAvailableSteps(availableSteps.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleDeselectStep = (step: StepItem) => {
    if (isCorrect) return;
    setAvailableSteps([...availableSteps, step]);
    setUserOrder(userOrder.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleReset = () => {
     if (!level || isCorrect) return;
     setAvailableSteps([...availableSteps, ...userOrder]);
     setUserOrder([]);
  };

  const checkAnswer = () => {
    if (!level) return;

    let correct = true;
    for (let i = 0; i < userOrder.length; i++) {
        if (userOrder[i].order !== i + 1) {
            correct = false;
            break;
        }
    }

    if (correct && userOrder.length === level.steps.length) {
        setIsCorrect(true);
        const roundScore = calculateScore();
        setScore(s => s + roundScore);
        setTimeout(() => {
            if (round < TOTAL_ROUNDS) {
                setRound(r => r + 1);
                startRound();
            } else {
                setIsFinished(true);
            }
        }, 1500);
    } else {
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    setUsedTitles([]); // Reset history on restart
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-purple-200">
              <ListChecks className="w-20 h-20 text-purple-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-purple-900 mb-2">步驟大師！</h2>
              <div className="text-6xl font-black text-purple-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的邏輯非常清晰！<br/>做事井然有序。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-purple-500 text-white rounded-xl font-bold hover:bg-purple-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50">
        <Loader2 className="w-12 h-12 text-purple-600 animate-spin mb-4" />
        <p className="text-purple-800">準備步驟中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[100dvh] bg-purple-50 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-purple-800 shadow-sm hover:bg-purple-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
             <div className="px-3 py-1 bg-purple-100 rounded-full text-purple-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-purple-100 px-3 py-1 rounded-full text-purple-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col p-2 sm:p-4 max-w-2xl mx-auto w-full gap-2 sm:gap-4 relative overflow-hidden">

        {/* Title */}
        <div className="flex-none text-center mb-1">
            <h2 className="text-xl sm:text-2xl font-bold text-purple-900">請排出正確順序：{level.title}</h2>
        </div>

        {/* Timeline / Drop Area - Reduced min-height for landscape compatibility */}
        <div className="flex-none bg-white/60 rounded-2xl p-2 sm:p-4 min-h-[100px] sm:min-h-[140px] flex gap-2 items-center overflow-x-auto border-2 border-purple-200 shadow-inner">
             {userOrder.length === 0 && (
                <div className="w-full text-center text-purple-300 font-bold text-base sm:text-lg">
                    點擊下方選項，放入這裡
                </div>
             )}
             {userOrder.map((step, idx) => (
                 <div key={step.id} className="flex items-center shrink-0 animate-fade-in-right">
                    <button 
                        onClick={() => handleDeselectStep(step)}
                        className="bg-purple-600 text-white px-3 py-2 sm:px-4 sm:py-3 rounded-xl font-bold shadow-md hover:bg-purple-700 active:scale-95 transition-all flex flex-col items-center min-w-[80px] sm:min-w-[100px]"
                    >
