import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, ArrowDown, ListChecks, RotateCcw, Check } from 'lucide-react';
import { StepsLevel, StepItem } from '../types';
import { generateStepsLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const StepsGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StepsLevel | null>(null);
  const [availableSteps, setAvailableSteps] = useState<StepItem[]>([]);
  const [userOrder, setUserOrder] = useState<StepItem[]>([]);
  const [loading, setLoading] = useState(true);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Track used titles to prevent repetition in a session
  const [usedTitles, setUsedTitles] = useState<string[]>([]);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserOrder([]);

    // Pass current history of used titles to filter them out
    const data = await generateStepsLevel(usedTitles);
    setLevel(data);
    setAvailableSteps(data.steps); 

    // Add new title to history
    setUsedTitles(prev => [...prev, data.title]);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 10) bonus = 10;
      else if (timeTaken < 20) bonus = 5;
      return 20 + bonus;
  }

  const handleSelectStep = (step: StepItem) => {
    if (isCorrect) return;
    setUserOrder([...userOrder, step]);
    setAvailableSteps(availableSteps.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleDeselectStep = (step: StepItem) => {
    if (isCorrect) return;
    setAvailableSteps([...availableSteps, step]);
    setUserOrder(userOrder.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleReset = () => {
     if (!level || isCorrect) return;
     setAvailableSteps([...availableSteps, ...userOrder]);
     setUserOrder([]);
  };

  const checkAnswer = () => {
    if (!level) return;

    let correct = true;
    for (let i = 0; i < userOrder.length; i++) {
        if (userOrder[i].order !== i + 1) {
            correct = false;
            break;
        }
    }

    if (correct && userOrder.length === level.steps.length) {
        setIsCorrect(true);
        const roundScore = calculateScore();
        setScore(s => s + roundScore);
        setTimeout(() => {
            if (round < TOTAL_ROUNDS) {
                setRound(r => r + 1);
                startRound();
            } else {
                setIsFinished(true);
            }
        }, 1500);
    } else {
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    setUsedTitles([]); // Reset history on restart
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-purple-200">
              <ListChecks className="w-20 h-20 text-purple-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-purple-900 mb-2">步驟大師！</h2>
              <div className="text-6xl font-black text-purple-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的邏輯非常清晰！<br/>做事井然有序。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-purple-500 text-white rounded-xl font-bold hover:bg-purple-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50">
        <Loader2 className="w-12 h-12 text-purple-600 animate-spin mb-4" />
        <p className="text-purple-800">準備步驟中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[100dvh] bg-purple-50 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-purple-800 shadow-sm hover:bg-purple-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
             <div className="px-3 py-1 bg-purple-100 rounded-full text-purple-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-purple-100 px-3 py-1 rounded-full text-purple-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col sm:flex-row p-2 sm:p-4 max-w-5xl mx-auto w-full gap-3 sm:gap-6 relative overflow-hidden">

        {/* Left Side (Landscape) / Top Side (Portrait) : Timeline + Controls */}
        <div className="flex-none sm:flex-1 flex flex-col gap-2 min-h-0 sm:h-full">
            <div className="flex-none text-center sm:text-left">
                <h2 className="text-lg sm:text-2xl font-bold text-purple-900 truncate">請排出順序：{level.title}</h2>
            </div>

            {/* Timeline: Horizontal on Portrait, Vertical on Landscape */}
            <div className={`
                flex-none sm:flex-1
                bg-white/60 rounded-2xl p-2 border-2 border-purple-200 shadow-inner 
                overflow-x-auto sm:overflow-x-hidden sm:overflow-y-auto
                flex flex-row sm:flex-col items-center sm:items-stretch gap-2
                min-h-[100px] sm:min-h-0
            `}>
                {userOrder.length === 0 && (
                    <div className="w-full h-full flex items-center justify-center text-purple-300 font-bold text-base sm:text-lg min-h-[80px]">
                        點擊選項放入
                    </div>
                )}
                {userOrder.map((step, idx) => (
                    <div key={step.id} className="flex flex-row sm:flex-col items-center shrink-0 animate-fade-in w-auto sm:w-full">
                        <button 
                            onClick={() => handleDeselectStep(step)}
                            className="bg-purple-600 text-white px-3 py-2 rounded-xl font-bold shadow-md hover:bg-purple-700 active:scale-95 transition-all flex flex-col items-center sm:flex-row sm:justify-between sm:w-full sm:px-4 min-w-[90px]"
                        >
                             <span className="text-xs opacity-70 mb-1 sm:mb-0 sm:mr-3 whitespace-nowrap">步驟 {idx + 1}</span>
                             <span className="text-sm sm:text-lg truncate">{step.text}</span>
                        </button>

                        {/* Arrow Right for Portrait */}
                        {idx < userOrder.length - 1 && (
                            <div className="mx-1 text-purple-300 sm:hidden">
                                <ArrowRight size={16}/>
                            </div>
                        )}
                        {/* Arrow Down for Landscape */}
                         {idx < userOrder.length - 1 && (
                            <div className="hidden sm:flex justify-center text-purple-300 py-1">
                                <ArrowDown size={20} />
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* Controls */}
            <div className="flex-none flex gap-3 mt-auto pt-2">
                 <button 
                    onClick={handleReset}
                    disabled={userOrder.length === 0 || isCorrect}
                    className="p-3 bg-gray-200 text-gray-700 rounded-full shadow-lg disabled:opacity-50 active:scale-95 transition-transform"
                 >
                    <RotateCcw size={24} />
                 </button>
                 <button 
                    onClick={checkAnswer}
                    disabled={availableSteps.length > 0 || isCorrect}
                    className="flex-1 bg-purple-600 text-white text-lg font-bold rounded-2xl shadow-xl hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 active:scale-95"
                 >
                    {isCorrect ? "正確！" : "確認順序"}
                    {isCorrect && <Check size={24} />}
                 </button>
            </div>
        </div>

        {/* Right Side (Landscape) / Bottom Side (Portrait) : Source Options */}
        <div className="flex-1 bg-white rounded-2xl p-3 shadow-lg border border-purple-100 overflow-y-auto min-h-0">
             <div className="flex flex-wrap gap-2 justify-center content-start">
                {availableSteps.map(step => (
                    <button 
                        key={step.id}
                        onClick={() => handleSelectStep(step)}
                        className="bg-purple-50 text-purple-900 border-2 border-purple-200 px-4 py-3 rounded-xl font-bold shadow-sm hover:bg-purple-100 hover:border-purple-300 active:scale-95 transition-all text-base sm:text-lg"
                    >
                        {step.text}
                    </button>
                ))}
             </div>
        </div>

        {showError && (
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 border-2 border-red-400 text-red-700 px-6 py-3 rounded-2xl font-bold shadow-2xl animate-bounce-short text-lg whitespace-nowrap z-50 pointer-events-none">
                 順序不對喔！
             </div>
        )}

      </div>
    </div>
  );
};

