// 1. Stroop Generator
export const generateStroopLevel = async (): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));

    const colors = [
        { name: "紅", code: "text-red-500" },
        { name: "藍", code: "text-blue-500" },
        { name: "綠", code: "text-green-500" },
        { name: "黃", code: "text-yellow-500" }, // careful with visibility on white
        { name: "黑", code: "text-black" },
        { name: "紫", code: "text-purple-500" },
    ];

    // 1. Pick a display text (e.g., "RED")
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];

    // 2. Pick a display color (e.g., Blue Ink), ensure high probability of mismatch for challenge
    let colorIndex = Math.floor(Math.random() * colors.length);
    // 70% chance to force a mismatch if it accidentally matched
    if (colorIndex === textIndex && Math.random() > 0.3) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];

    // 3. Generate options (Correct answer is the COLOR Name, not the Text)
    const correctAnswer = colorObj.name;

    // Select 2 other distractors
    const distractors = colors
        .filter(c => c.name !== correctAnswer)
        .sort(() => 0.5 - Math.random())
        .slice(0, 2)
        .map(c => c.name);

    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());

    return {
        text: textObj.name,
        colorCode: colorObj.code,
        colorName: correctAnswer,
        options
    };
}

// 2. Dots Generator
export const generateDotLevel = async (round: number): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Increase difficulty: 
    // Round 1-2: 3x3 grid, 3 dots, 2s
    // Round 3-4: 4x4 grid, 4 dots, 2s
    // Round 5+: 4x4 grid, 5 dots, 1.5s

    let gridSize = 3;
    let numDots = 3;
    let duration = 2000;

    if (round >= 3) { gridSize = 4; numDots = 4; }
    if (round >= 5) { numDots = 5; duration = 1500; }

    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];

    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }

    return { gridSize, activeIndices, duration };
}

// 3. Connect (Trail Making) Generator
export const generateConnectLevel = async (round: number): Promise<ConnectLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Number of points: 5 to 8 based on round
    const count = Math.min(5 + Math.floor((round - 1) / 2), 9); 
    const points: ConnectPoint[] = [];

    // Attempt to place points without overlapping
    // We use percentage (0-100) for x, y
    const minDist = 15; // Minimum Euclidean distance percentage

    for (let i = 1; i <= count; i++) {
        let attempts = 0;
        let valid = false;
        let x = 0, y = 0;

        while (!valid && attempts < 100) {
            x = 10 + Math.random() * 80; // Margin of 10%
            y = 10 + Math.random() * 80;

            // Check distance against all existing points
            let tooClose = false;
            for (const p of points) {
                const dist = Math.sqrt(Math.pow(p.x - x, 2) + Math.pow(p.y - y, 2));
                if (dist < minDist) {
                    tooClose = true;
                    break;
                }
            }
            if (!tooClose) valid = true;
            attempts++;
        }

        // Even if overlap (rare after 100 tries for few points), push it
        points.push({
            id: i,
            label: i.toString(),
            x,
            y
        });
    }

    return { points };
}

// 4. Emotion Generator
export const generateEmotionLevel = async (): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_EMOTION_LEVELS.length);
    const level = STATIC_EMOTION_LEVELS[randomIndex];

    // Shuffle options just in case (though static data is fixed, good practice)
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());

    return {
        ...level,
        options: shuffledOptions
    };
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, AlertTriangle } from 'lucide-react';
import { StroopLevel } from '../types';
import { generateStroopLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10; // Faster paced, more rounds

const StroopGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StroopLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [streak, setStreak] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [showError, setShowError] = useState(false);

  // Timer for fast pacing
  const [timeLeft, setTimeLeft] = useState(10); // 10 seconds per question maximum? Or total? 
  // Let's do per question time limit to force impulse

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setShowError(false);
    const data = await generateStroopLevel();
    setLevel(data);
    setLoading(false);
    setTimeLeft(5); // 5 seconds per turn to force quick decision
  };

  useEffect(() => {
      if (!loading && !isFinished && timeLeft > 0) {
          const timer = setTimeout(() => setTimeLeft(t => t - 1), 1000);
          return () => clearTimeout(timer);
      } else if (timeLeft === 0 && !loading && !isFinished) {
          // Time out - wrong
          handleAnswer(null);
      }
  }, [timeLeft, loading, isFinished]);

  const handleAnswer = (answer: string | null) => {
      if (!level) return;

      const isCorrect = answer === level.colorName;

      if (isCorrect) {
          setScore(s => s + 10 + (streak * 2)); // Streak bonus
          setStreak(s => s + 1);
      } else {
          setStreak(0);
          setShowError(true);
          // Small penalty or just no points?
          // Let's allow continuing but flash red
      }

      // Small delay then next
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
            setRound(r => r + 1);
            startRound();
        } else {
            setIsFinished(true);
        }
      }, isCorrect ? 200 : 1000); // Longer delay on error to see feedback
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setStreak(0);
      setIsFinished(false);
      startRound();
  }

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-rose-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-rose-200">
              <Trophy className="w-20 h-20 text-rose-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-rose-900 mb-2">反應超快！</h2>
              <div className="text-6xl font-black text-rose-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的專注力很強！<br/>沒有被顏色騙倒。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold hover:bg-rose-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-rose-50 flex items-center justify-center"><Loader2 className="animate-spin text-rose-500"/></div>;
  }

  return (
    <div className={`flex flex-col h-screen overflow-hidden transition-colors duration-300 ${showError ? 'bg-red-200' : 'bg-rose-50'}`}>
       {/* Header */}
       <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-rose-800 shadow-sm hover:bg-rose-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-rose-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-rose-100 px-3 py-1 rounded-full text-rose-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-4">

            <div className="mb-8 text-center">
                <p className="text-gray-500 text-lg mb-2">請回答這個字的 <span className="font-bold text-black underline">顏色</span></p>
                {/* Timer Bar */}
                <div className="w-64 h-2 bg-gray-200 rounded-full overflow-hidden mx-auto mb-6">
                    <div 
                        className="h-full bg-rose-500 transition-all duration-1000 linear"
                        style={{ width: `${(timeLeft / 5) * 100}%` }}
                    ></div>
                </div>

                {/* The Stroop Word */}
                <div className="bg-white p-12 rounded-3xl shadow-xl border-4 border-rose-100 w-80 h-80 flex items-center justify-center mb-8">
                    <span className={`text-9xl font-black ${level.colorCode}`}>
                        {level.text}
                    </span>
                </div>
            </div>

            {/* Options */}
            <div className="grid grid-cols-3 gap-4 w-full max-w-md">
                {level.options.map((opt, idx) => (
                    <button
                        key={idx}
                        onClick={() => handleAnswer(opt)}
                        className="py-4 bg-white border-2 border-rose-200 rounded-xl text-2xl font-bold text-gray-700 shadow-md hover:bg-rose-100 active:scale-95 transition-all"
                    >
                        {opt}
                    </button>
                ))}
            </div>

            {showError && (
                <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-500 text-white px-8 py-4 rounded-xl font-bold text-2xl animate-bounce shadow-xl">
                    錯了！要看顏色！
                </div>
            )}
        </div>
    </div>
  );
};

export default StroopGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, Eye, Play } from 'lucide-react';
import { DotLevel } from '../types';
import { generateDotLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const DotGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<DotLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [gameState, setGameState] = useState<'memorize' | 'recall' | 'result'>('memorize');
  const [userSelection, setUserSelection] = useState<number[]>([]);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [countdown, setCountdown] = useState(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setGameState('memorize');
    setUserSelection([]);

    const data = await generateDotLevel(round);
    setLevel(data);
    setLoading(false);

    // Countdown for memorize phase
    setCountdown(data.duration / 1000);
  };

  // Timer for Memorize Phase
  useEffect(() => {
    if (gameState === 'memorize' && level) {
        const timer = setTimeout(() => {
            setGameState('recall');
        }, level.duration);

        // Visual countdown (rough)
        const interval = setInterval(() => {
            setCountdown(c => Math.max(0, c - 0.1));
        }, 100);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }
  }, [gameState, level]);

  const handleCellClick = (index: number) => {
    if (gameState !== 'recall') return;

    // Toggle selection
    let newSelection = [...userSelection];
    if (newSelection.includes(index)) {
        newSelection = newSelection.filter(i => i !== index);
    } else {
        // Limit selection to number of dots
        if (level && newSelection.length < level.activeIndices.length) {
            newSelection.push(index);
        }
    }
    setUserSelection(newSelection);
  };

  const checkAnswer = () => {
      if (!level) return;

      const correctSet = new Set(level.activeIndices);
      const userSet = new Set(userSelection);

      // Check if sets match
      let isCorrect = true;
      if (correctSet.size !== userSet.size) isCorrect = false;
      for (let elem of userSet) {
          if (!correctSet.has(elem)) isCorrect = false;
      }

      if (isCorrect) {
          setScore(s => s + 20); // 20 pts per round
      }

      setGameState('result');

      setTimeout(() => {
          if (round < TOTAL_ROUNDS) {
              setRound(r => r + 1);
              startRound();
          } else {
              setIsFinished(true);
          }
      }, 2000); // Show result for 2s
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setIsFinished(false);
      startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-cyan-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-cyan-200">
              <Trophy className="w-20 h-20 text-cyan-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-cyan-900 mb-2">記憶大師！</h2>
              <div className="text-6xl font-black text-cyan-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的空間記憶力很棒！<br/>點點都逃不過你的眼睛。
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-cyan-500 text-white rounded-xl font-bold hover:bg-cyan-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-cyan-50 flex items-center justify-center"><Loader2 className="animate-spin text-cyan-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-cyan-50 overflow-hidden relative">
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-cyan-800 shadow-sm hover:bg-cyan-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-cyan-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-cyan-100 px-3 py-1 rounded-full text-cyan-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-4">

            <h2 className="text-2xl font-bold text-cyan-900 mb-4">
                {gameState === 'memorize' && <span className="flex items-center"><Eye className="mr-2"/> 記住紅點位置 ({countdown.toFixed(1)})</span>}
                {gameState === 'recall' && <span className="flex items-center text-orange-600">點擊剛才的位置</span>}
                {gameState === 'result' && <span>答案揭曉</span>}
            </h2>

            {/* Grid */}
            <div 
                className="grid gap-2 bg-white p-4 rounded-2xl shadow-lg border-4 border-cyan-200"
                style={{ 
                    gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
                    width: 'min(90vw, 400px)',
                    aspectRatio: '1/1'
                }}
            >
                {Array.from({ length: level.gridSize * level.gridSize }).map((_, idx) => {
                    let bgColor = "bg-cyan-50";
                    let borderColor = "border-cyan-100";

                    if (gameState === 'memorize') {
                        if (level.activeIndices.includes(idx)) {
                            bgColor = "bg-red-500";
                            borderColor = "border-red-600";
                        }
                    } else if (gameState === 'recall') {
                        if (userSelection.includes(idx)) {
                            bgColor = "bg-cyan-500";
                            borderColor = "border-cyan-600";
                        } else {
                            // Hover effect handled by CSS
                            bgColor = "bg-cyan-50 hover:bg-cyan-100 cursor-pointer";
                        }
                    } else if (gameState === 'result') {
                        // Show Correct vs User
                        const wasCorrect = level.activeIndices.includes(idx);
                        const userSelected = userSelection.includes(idx);

                        if (wasCorrect && userSelected) {
                            bgColor = "bg-green-500"; // Correct hit
                        } else if (wasCorrect && !userSelected) {
                            bgColor = "bg-red-300 opacity-50"; // Missed
                        } else if (!wasCorrect && userSelected) {
                            bgColor = "bg-gray-400"; // Wrong selection
                        }
                    }

                    return (
                        <div 
                            key={idx}
                            onClick={() => handleCellClick(idx)}
                            className={`rounded-xl border-2 transition-all duration-200 ${bgColor} ${borderColor}`}
                        ></div>
                    )
                })}
            </div>

            {gameState === 'recall' && (
                <button 
                    onClick={checkAnswer}
                    disabled={userSelection.length === 0}
                    className="mt-8 px-8 py-3 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
                >
                    <Play className="fill-current mr-2 w-5 h-5"/> 確認答案
                </button>
            )}
        </div>
    </div>
  );
};

export default DotGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, RotateCcw } from 'lucide-react';
import { ConnectLevel, ConnectPoint } from '../types';
import { generateConnectLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const ConnectGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<ConnectLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [nextNumber, setNextNumber] = useState(1);
  const [connectedPoints, setConnectedPoints] = useState<ConnectPoint[]>([]);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [showError, setShowError] = useState(false);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setNextNumber(1);
    setConnectedPoints([]);

    const data = await generateConnectLevel(round);
    setLevel(data);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 10) bonus = 10;
      return 20 + bonus;
  }

  const handlePointClick = (point: ConnectPoint) => {
      if (point.id === nextNumber) {
          // Correct
          setConnectedPoints(prev => [...prev, point]);
          setNextNumber(n => n + 1);
          setShowError(false);

          // Check Win
          if (point.id === level?.points.length) {
              const roundScore = calculateScore();
              setScore(s => s + roundScore);
              setTimeout(() => {
                  if (round < TOTAL_ROUNDS) {
                      setRound(r => r + 1);
                      startRound();
                  } else {
                      setIsFinished(true);
                  }
              }, 1000);
          }
      } else {
          // Wrong
          setShowError(true);
          setTimeout(() => setShowError(false), 1000);
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  // Helper to draw lines
  const renderLines = () => {
      if (connectedPoints.length < 2) return null;

      const lines = [];
      for (let i = 0; i < connectedPoints.length - 1; i++) {
          const p1 = connectedPoints[i];
          const p2 = connectedPoints[i+1];
          lines.push(
              <line 
                key={i}
                x1={`${p1.x}%`} y1={`${p1.y}%`}
                x2={`${p2.x}%`} y2={`${p2.y}%`}
                stroke="#6366f1" // Indigo-500
                strokeWidth="4"
                strokeLinecap="round"
                className="animate-draw"
              />
          );
      }
      return (
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
              {lines}
          </svg>
      );
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-indigo-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-indigo-200">
              <Trophy className="w-20 h-20 text-indigo-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-indigo-900 mb-2">連線成功！</h2>
              <div className="text-6xl font-black text-indigo-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的邏輯非常清晰！<br/>做事有條有理。
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold hover:bg-indigo-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-indigo-50 flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-indigo-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-indigo-800 shadow-sm hover:bg-indigo-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
            <div className="text-indigo-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
            <div className="px-3 py-1 bg-indigo-100 rounded-full text-indigo-800 font-bold text-sm">
