            </div>
             <div className="flex items-center bg-indigo-100 px-3 py-1 rounded-full text-indigo-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 relative m-4 bg-white rounded-3xl shadow-inner border-4 border-indigo-100 overflow-hidden cursor-crosshair">
          {renderLines()}

          {level.points.map((point) => {
              const isConnected = connectedPoints.some(p => p.id === point.id);
              const isNext = point.id === nextNumber;

              return (
                  <button
                    key={point.id}
                    onClick={() => handlePointClick(point)}
                    className={`
                        absolute w-12 h-12 -ml-6 -mt-6 rounded-full flex items-center justify-center text-xl font-bold shadow-md transition-all z-10
                        ${isConnected ? 'bg-indigo-500 text-white scale-110' : 'bg-white text-indigo-600 border-2 border-indigo-300 hover:border-indigo-500'}
                        ${isNext ? 'animate-pulse ring-4 ring-indigo-200' : ''}
                    `}
                    style={{ left: `${point.x}%`, top: `${point.y}%` }}
                    disabled={isConnected}
                  >
                      {point.label}
                  </button>
              )
          })}

          {showError && (
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 text-red-600 px-6 py-3 rounded-full font-bold shadow-xl animate-bounce z-50 pointer-events-none">
                 順序錯囉！
             </div>
          )}
      </div>
    </div>
  );
};

