// 1. Stroop Generator
export const generateStroopLevel = async (): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));

    const colors = [
        { name: "紅", code: "text-red-500" },
        { name: "藍", code: "text-blue-500" },
        { name: "綠", code: "text-green-500" },
        { name: "黃", code: "text-yellow-500" }, // careful with visibility on white
        { name: "黑", code: "text-black" },
        { name: "紫", code: "text-purple-500" },
    ];

    // 1. Pick a display text (e.g., "RED")
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];

    // 2. Pick a display color (e.g., Blue Ink), ensure high probability of mismatch for challenge
    let colorIndex = Math.floor(Math.random() * colors.length);
    // 70% chance to force a mismatch if it accidentally matched
    if (colorIndex === textIndex && Math.random() > 0.3) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];

    // 3. Generate options (Correct answer is the COLOR Name, not the Text)
    const correctAnswer = colorObj.name;

    // Select 2 other distractors
    const distractors = colors
        .filter(c => c.name !== correctAnswer)
        .sort(() => 0.5 - Math.random())
        .slice(0, 2)
        .map(c => c.name);

    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());

    return {
        text: textObj.name,
        colorCode: colorObj.code,
        colorName: correctAnswer,
        options
    };
}

// 2. Dots Generator
export const generateDotLevel = async (round: number): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Increase difficulty: 
    // Round 1-2: 3x3 grid, 3 dots
    // Round 3-4: 4x4 grid, 4 dots
    // Round 5+: 4x4 grid, 5 dots

    let gridSize = 3;
    let numDots = 3;
    // Set duration to 10 seconds for all rounds as requested
    let duration = 10000; 

    if (round >= 3) { gridSize = 4; numDots = 4; }
    if (round >= 5) { numDots = 5; }

    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];

    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }

    return { gridSize, activeIndices, duration };
}

// 4. Emotion Generator
export const generateEmotionLevel = async (): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_EMOTION_LEVELS.length);
    const level = STATIC_EMOTION_LEVELS[randomIndex];

    // Shuffle options just in case (though static data is fixed, good practice)
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());

    return {
        ...level,
        options: shuffledOptions
    };
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Clock, CheckCircle } from 'lucide-react';
import { StroopLevel } from '../types';
import { generateStroopLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const StroopGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StroopLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [streak, setStreak] = useState(0);
  const [isFinished, setIsFinished] = useState(false);

  // Feedback States
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  // Timer for scoring
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    const data = await generateStroopLevel();
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const handleAnswer = (answer: string) => {
      if (!level || feedback !== null) return; // Prevent double clicks

      const isCorrect = answer === level.colorName;

      if (isCorrect) {
          const timeTaken = (Date.now() - startTimeRef.current) / 1000;

          // Scoring logic: Faster is better
          let points = 10;
          if (timeTaken < 2) points += 10;
          else if (timeTaken < 4) points += 5;

          // Streak bonus
          const finalScore = points + (streak * 2);

          setScore(s => s + finalScore);
          setStreak(s => s + 1);
          setFeedback('correct');
      } else {
          setStreak(0);
          setFeedback('wrong');
      }

      // Delay then next
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
            setRound(r => r + 1);
            startRound();
        } else {
            setIsFinished(true);
        }
      }, 1000); 
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setStreak(0);
      setIsFinished(false);
      startRound();
  }

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 180) return { title: "反應神速！", desc: "你的大腦處理速度非常驚人！" };
      if (finalScore >= 120) return { title: "表現優異！", desc: "你的專注力保持得很好喔。" };
      return { title: "再接再厲！", desc: "慢慢練習，準確度最重要。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-rose-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-rose-200">
              <Trophy className="w-20 h-20 text-rose-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-rose-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-rose-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold hover:bg-rose-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-rose-50 flex items-center justify-center"><Loader2 className="animate-spin text-rose-500"/></div>;
  }

  return (
    <div className={`flex flex-col h-screen overflow-hidden transition-colors duration-300 ${feedback === 'wrong' ? 'bg-red-50' : 'bg-rose-50'}`}>
       {/* Header */}
       <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-rose-800 shadow-sm hover:bg-rose-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-rose-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-rose-100 px-3 py-1 rounded-full text-rose-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-4">

            <div className="mb-8 text-center relative">
                <p className="text-gray-500 text-lg mb-4">請回答這個字的 <span className="font-bold text-black underline decoration-rose-500 decoration-4">顏色</span></p>

                {/* The Stroop Word */}
                <div className="bg-white p-12 rounded-3xl shadow-xl border-4 border-rose-100 w-80 h-80 flex items-center justify-center mb-8 relative">
                    <span className={`text-9xl font-black ${level.colorCode}`}>
                        {level.text}
                    </span>

                    {/* Feedback Overlay */}
                    {feedback === 'correct' && (
                        <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                            <div className="text-green-600 flex flex-col items-center">
                                <CheckCircle className="w-16 h-16 mb-2" />
                                <span className="text-3xl font-bold">答對了！</span>
                            </div>
                        </div>
                    )}
                    {feedback === 'wrong' && (
                         <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                            <div className="text-red-500 flex flex-col items-center">
                                <span className="text-3xl font-bold">看錯囉！</span>
                                <span className="text-xl mt-2">是 {level.colorName} 色</span>
                            </div>
                        </div>
                    )}
