export const generateMarketLevel = async (): Promise<MarketLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_MARKET_LEVELS.length);
    return STATIC_MARKET_LEVELS[randomIndex];
}

export const generateStepsLevel = async (excludeTitles: string[] = []): Promise<StepsLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Filter out used titles
    const availableLevels = STATIC_STEPS_LEVELS.filter(l => !excludeTitles.includes(l.title));

    // If we somehow run out (e.g. played > 50 rounds), fallback to the full list to prevent crashing
    const pool = availableLevels.length > 0 ? availableLevels : STATIC_STEPS_LEVELS;

    const randomIndex = Math.floor(Math.random() * pool.length);
    const level = pool[randomIndex];

    // Scramble the steps
    const steps = [...level.steps];
    for (let i = steps.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [steps[i], steps[j]] = [steps[j], steps[i]];
    }

    return {
        title: level.title,
        steps: steps
    };
}

export const generateShadowLevel = async (): Promise<ShadowLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_SHADOW_LEVELS.length);
    const level = STATIC_SHADOW_LEVELS[randomIndex];

    // Create a shuffled version of options
    const options = [...level.options];
    for (let i = options.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [options[i], options[j]] = [options[j], options[i]];
    }

    // Find the new correct index
    const correctIndex = options.indexOf(level.target);

    return {
        target: level.target,
        options: options,
        correctIndex: correctIndex
    };
}

// --- NEW GAMES GENERATORS (Games 9-12) ---

// 1. Stroop Generator
export const generateStroopLevel = async (): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));

    const colors = [
        { name: "紅", code: "text-red-500" },
        { name: "藍", code: "text-blue-500" },
        { name: "綠", code: "text-green-500" },
        { name: "黃", code: "text-yellow-500" }, // careful with visibility on white
        { name: "黑", code: "text-black" },
        { name: "紫", code: "text-purple-500" },
    ];

    // 1. Pick a display text (e.g., "RED")
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];

    // 2. Pick a display color (e.g., Blue Ink), ensure high probability of mismatch for challenge
    let colorIndex = Math.floor(Math.random() * colors.length);
    // 70% chance to force a mismatch if it accidentally matched
    if (colorIndex === textIndex && Math.random() > 0.3) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];

    // 3. Generate options (Correct answer is the COLOR Name, not the Text)
    const correctAnswer = colorObj.name;

    // Select 2 other distractors
    const distractors = colors
        .filter(c => c.name !== correctAnswer)
        .sort(() => 0.5 - Math.random())
        .slice(0, 2)
        .map(c => c.name);

    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());

    return {
        text: textObj.name,
        colorCode: colorObj.code,
        colorName: correctAnswer,
        options
    };
}

// 2. Dots Generator
export const generateDotLevel = async (round: number): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Progression:
    // Round 1: 3 dots (3x3)
    // Round 2: 4 dots (3x3)
    // Round 3: 5 dots (4x4)
    // Round 4: 6 dots (4x4)
    // Round 5: 7 dots (4x4)
    // Round 6: 8 dots (4x4)

    let gridSize = 3;
    let numDots = 3;
    let duration = 10000; 

    // Mapping round to dots
    if (round === 1) numDots = 3;
    else if (round === 2) numDots = 4;
    else if (round === 3) { numDots = 5; gridSize = 4; }
    else if (round === 4) { numDots = 6; gridSize = 4; }
    else if (round === 5) { numDots = 7; gridSize = 4; }
    else if (round >= 6) { numDots = 8; gridSize = 4; }

    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];

    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }

    return { gridSize, activeIndices, duration };
}

// 4. Emotion Generator
export const generateEmotionLevel = async (): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_EMOTION_LEVELS.length);
    const level = STATIC_EMOTION_LEVELS[randomIndex];

    // Shuffle options just in case (though static data is fixed, good practice)
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());

    return {
        ...level,
        options: shuffledOptions
    };
}

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, Eye, Play, ArrowRight, CheckCircle, XCircle } from 'lucide-react';
import { DotLevel } from '../types';
import { generateDotLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 6; // Increased to 6 to accommodate 3->8 dots progression

const DotGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<DotLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [gameState, setGameState] = useState<'memorize' | 'recall' | 'result'>('memorize');
  const [userSelection, setUserSelection] = useState<number[]>([]);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [countdown, setCountdown] = useState(0);

  // Feedback text
  const [feedbackText, setFeedbackText] = useState("");

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setGameState('memorize');
    setUserSelection([]);
    setFeedbackText("");

    const data = await generateDotLevel(round);
    setLevel(data);
    setLoading(false);

    // Countdown for memorize phase (from service, e.g., 10000ms)
    setCountdown(data.duration / 1000);
  };

  // Timer for Memorize Phase
  useEffect(() => {
    if (gameState === 'memorize' && level) {
        const timer = setTimeout(() => {
            setGameState('recall');
        }, level.duration);

        // Visual countdown
        const interval = setInterval(() => {
            setCountdown(c => Math.max(0, c - 0.1));
        }, 100);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }
  }, [gameState, level]);

  const handleCellClick = (index: number) => {
    if (gameState !== 'recall') return;

    // Toggle selection
    let newSelection = [...userSelection];
    if (newSelection.includes(index)) {
        newSelection = newSelection.filter(i => i !== index);
    } else {
        // Limit selection to number of dots
        if (level && newSelection.length < level.activeIndices.length) {
            newSelection.push(index);
        }
    }
    setUserSelection(newSelection);
  };

  const checkAnswer = () => {
      if (!level) return;

      const correctSet = new Set(level.activeIndices);
      const userSet = new Set(userSelection);

      // Check if sets match
      let isCorrect = true;
      if (correctSet.size !== userSet.size) isCorrect = false;
      for (let elem of userSet) {
          if (!correctSet.has(elem)) isCorrect = false;
      }

      if (isCorrect) {
          setScore(s => s + 20); // 20 pts per round
          setFeedbackText("太棒了！位置完全正確！");
      } else {
          setFeedbackText("再接再厲！看下面的正確答案。");
      }

      setGameState('result');
      // No auto navigation
  };

  const handleNextLevel = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
      }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setIsFinished(false);
      startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 100) return { title: "記憶大師！", desc: "你的空間記憶力超群！" };
      if (finalScore >= 60) return { title: "表現不錯！", desc: "大部分的位置都記住了。" };
      return { title: "繼續加油！", desc: "多練習幾次，你會進步的。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-cyan-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-cyan-200">
              <Trophy className="w-20 h-20 text-cyan-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-cyan-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-cyan-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-cyan-500 text-white rounded-xl font-bold hover:bg-cyan-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-cyan-50 flex items-center justify-center"><Loader2 className="animate-spin text-cyan-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-cyan-50 overflow-hidden relative">
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-cyan-800 shadow-sm hover:bg-cyan-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-cyan-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-cyan-100 px-3 py-1 rounded-full text-cyan-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-4">

            <h2 className="text-2xl font-bold text-cyan-900 mb-4">
                {gameState === 'memorize' && <span className="flex items-center"><Eye className="mr-2"/> 記住紅點位置 ({countdown.toFixed(0)}s)</span>}
                {gameState === 'recall' && <span className="flex items-center text-orange-600">點擊剛才的數字位置</span>}
                {gameState === 'result' && <span className="text-blue-600">答案揭曉</span>}
            </h2>

            {/* Grid */}
            <div 
                className="grid gap-2 bg-white p-4 rounded-2xl shadow-lg border-4 border-cyan-200"
                style={{ 
                    gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
                    width: 'min(90vw, 400px)',
                    aspectRatio: '1/1'
                }}
            >
                {Array.from({ length: level.gridSize * level.gridSize }).map((_, idx) => {
                    let bgColor = "bg-cyan-50";
                    let borderColor = "border-cyan-100";
                    let textColor = "text-cyan-300";

                    if (gameState === 'memorize') {
                        if (level.activeIndices.includes(idx)) {
                            bgColor = "bg-red-500";
                            borderColor = "border-red-600";
                            textColor = "text-white";
                        }
                    } else if (gameState === 'recall') {
                        if (userSelection.includes(idx)) {
                            bgColor = "bg-cyan-500";
                            borderColor = "border-cyan-600";
                            textColor = "text-white";
                        } else {
                            bgColor = "bg-cyan-50 hover:bg-cyan-100 cursor-pointer";
                        }
                    } else if (gameState === 'result') {
                        const wasCorrect = level.activeIndices.includes(idx);
                        const userSelected = userSelection.includes(idx);

                        if (wasCorrect && userSelected) {
                            bgColor = "bg-green-500"; // Correct hit
                            textColor = "text-white";
                        } else if (wasCorrect && !userSelected) {
                            bgColor = "bg-red-400 opacity-70"; // Missed
                            textColor = "text-white";
                        } else if (!wasCorrect && userSelected) {
                            bgColor = "bg-gray-400"; // Wrong selection
                            textColor = "text-white";
                        }
                    }

                    return (
                        <div 
                            key={idx}
                            onClick={() => handleCellClick(idx)}
                            className={`rounded-xl border-2 transition-all duration-200 ${bgColor} ${borderColor} flex items-center justify-center`}
                        >
                            <span className={`text-4xl sm:text-6xl font-black ${textColor}`}>
                                {idx + 1}
                            </span>
                        </div>
                    )
                })}
            </div>

            {/* Controls / Feedback area */}
            <div className="mt-6 h-16 flex items-center justify-center">
                {gameState === 'recall' && (
                    <button 
                        onClick={checkAnswer}
                        disabled={userSelection.length === 0}
                        className="px-8 py-3 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center text-lg animate-fade-in"
                    >
                        <Play className="fill-current mr-2 w-5 h-5"/> 確認答案
                    </button>
                )}

                {gameState === 'result' && (
                    <div className="flex flex-col items-center animate-fade-in-up w-full">
                        <div className={`text-xl font-bold mb-4 flex items-center ${feedbackText.includes("棒") ? "text-green-600" : "text-gray-600"}`}>
                             {feedbackText.includes("棒") ? <CheckCircle className="mr-2"/> : <XCircle className="mr-2"/>}
                             {feedbackText}
                        </div>
                        <button 
                            onClick={handleNextLevel}
                            className="px-8 py-3 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 flex items-center text-lg"
                        >
                            下一題 <ArrowRight className="ml-2 w-5 h-5"/>
                        </button>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

