import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, Eye, Play, ArrowRight, CheckCircle, XCircle } from 'lucide-react';
import { DotLevel } from '../types';
import { generateDotLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 6;

const DotGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<DotLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [gameState, setGameState] = useState<'memorize' | 'recall' | 'result'>('memorize');
  const [userSelection, setUserSelection] = useState<number[]>([]);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [countdown, setCountdown] = useState(0);

  // Feedback text
  const [feedbackText, setFeedbackText] = useState("");

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setGameState('memorize');
    setUserSelection([]);
    setFeedbackText("");

    const data = await generateDotLevel(round);
    setLevel(data);
    setLoading(false);

    // Countdown for memorize phase
    setCountdown(data.duration / 1000);
  };

  // Timer for Memorize Phase
  useEffect(() => {
    if (gameState === 'memorize' && level) {
        const timer = setTimeout(() => {
            setGameState('recall');
        }, level.duration);

        // Visual countdown
        const interval = setInterval(() => {
            setCountdown(c => Math.max(0, c - 0.1));
        }, 100);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }
  }, [gameState, level]);

  const handleCellClick = (index: number) => {
    if (gameState !== 'recall') return;

    // Toggle selection
    let newSelection = [...userSelection];
    if (newSelection.includes(index)) {
        newSelection = newSelection.filter(i => i !== index);
    } else {
        // Limit selection to number of dots
        if (level && newSelection.length < level.activeIndices.length) {
            newSelection.push(index);
        }
    }
    setUserSelection(newSelection);
  };

  const checkAnswer = () => {
      if (!level) return;

      const correctSet = new Set(level.activeIndices);
      const userSet = new Set(userSelection);

      // Check if sets match
      let isCorrect = true;
      if (correctSet.size !== userSet.size) isCorrect = false;
      for (let elem of userSet) {
          if (!correctSet.has(elem)) isCorrect = false;
      }

      if (isCorrect) {
          setScore(s => s + 20); // 20 pts per round
          setFeedbackText("太棒了！位置完全正確！");
      } else {
          setFeedbackText("再接再厲！看下面的正確答案。");
      }

      setGameState('result');
  };

  const handleNextLevel = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
      }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setIsFinished(false);
      startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 100) return { title: "記憶大師！", desc: "你的空間記憶力超群！" };
      if (finalScore >= 60) return { title: "表現不錯！", desc: "大部分的位置都記住了。" };
      return { title: "繼續加油！", desc: "多練習幾次，你會進步的。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-cyan-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-cyan-200">
              <Trophy className="w-20 h-20 text-cyan-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-cyan-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-cyan-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-cyan-500 text-white rounded-xl font-bold hover:bg-cyan-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-cyan-50 flex items-center justify-center"><Loader2 className="animate-spin text-cyan-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-cyan-50 overflow-hidden relative">
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-cyan-800 shadow-sm hover:bg-cyan-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-cyan-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-cyan-100 px-3 py-1 rounded-full text-cyan-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-4 gap-4 sm:gap-8 overflow-hidden">

            {/* Left Side (Landscape): Grid */}
            <div className="flex-none flex items-center justify-center">
                <div 
                    className="grid gap-2 bg-white p-4 rounded-2xl shadow-lg border-4 border-cyan-200"
                    style={{ 
                        gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
                        width: 'min(90vw, 400px)',
                        height: 'min(90vw, 400px)', // Fixed aspect ratio
                        maxWidth: '80vh', // Ensure it fits vertically
                        maxHeight: '80vh'
                    }}
                >
                    {Array.from({ length: level.gridSize * level.gridSize }).map((_, idx) => {
                        let bgColor = "bg-cyan-50";
                        let borderColor = "border-cyan-100";
                        let textColor = "text-cyan-300";

                        if (gameState === 'memorize') {
                            if (level.activeIndices.includes(idx)) {
                                bgColor = "bg-red-500";
                                borderColor = "border-red-600";
                                textColor = "text-transparent"; // Hide text in memorize phase
                            } else {
                                textColor = "text-transparent"; // Hide text in memorize phase
                            }
                        } else if (gameState === 'recall') {
                            if (userSelection.includes(idx)) {
                                bgColor = "bg-cyan-500";
                                borderColor = "border-cyan-600";
                                textColor = "text-white";
                            } else {
                                bgColor = "bg-cyan-50 hover:bg-cyan-100 cursor-pointer";
                            }
                        } else if (gameState === 'result') {
                            const wasCorrect = level.activeIndices.includes(idx);
                            const userSelected = userSelection.includes(idx);

                            if (wasCorrect && userSelected) {
                                bgColor = "bg-green-500"; // Correct hit
                                textColor = "text-white";
                            } else if (wasCorrect && !userSelected) {
                                bgColor = "bg-red-400 opacity-70"; // Missed
                                textColor = "text-white";
                            } else if (!wasCorrect && userSelected) {
                                bgColor = "bg-gray-400"; // Wrong selection
                                textColor = "text-white";
                            }
                        }

                        return (
                            <div 
                                key={idx}
                                onClick={() => handleCellClick(idx)}
                                className={`rounded-xl border-2 transition-all duration-200 ${bgColor} ${borderColor} flex items-center justify-center`}
                            >
                                <span className={`text-4xl sm:text-6xl font-black ${textColor} transition-opacity duration-300`}>
                                    {idx + 1}
                                </span>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* Right Side (Landscape): Controls & Instruction */}
            <div className="flex-1 flex flex-col items-center justify-center max-w-sm text-center">
                <h2 className="text-2xl font-bold text-cyan-900 mb-6">
                    {gameState === 'memorize' && <span className="flex flex-col items-center"><Eye className="mb-2 w-8 h-8"/> 記住紅點位置 <br/><span className="text-4xl mt-2 text-red-500">{countdown.toFixed(0)}</span></span>}
                    {gameState === 'recall' && <span className="flex flex-col items-center text-orange-600">點擊剛才的數字位置</span>}
                    {gameState === 'result' && <span className="text-blue-600 text-3xl">答案揭曉</span>}
                </h2>

                {gameState === 'recall' && (
                    <button 
                        onClick={checkAnswer}
                        disabled={userSelection.length === 0}
                        className="px-8 py-4 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center text-xl animate-fade-in"
                    >
                        <Play className="fill-current mr-3 w-6 h-6"/> 確認答案
                    </button>
                )}

                {gameState === 'result' && (
                    <div className="flex flex-col items-center animate-fade-in-up w-full">
                        <div className={`text-xl font-bold mb-6 flex items-center ${feedbackText.includes("棒") ? "text-green-600" : "text-gray-600"}`}>
                             {feedbackText.includes("棒") ? <CheckCircle className="mr-2 w-6 h-6"/> : <XCircle className="mr-2 w-6 h-6"/>}
                             {feedbackText}
                        </div>
                        <button 
                            onClick={handleNextLevel}
                            className="px-8 py-4 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 flex items-center text-xl"
                        >
                            下一題 <ArrowRight className="ml-3 w-6 h-6"/>
                        </button>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

export default DotGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Heart } from 'lucide-react';
import { EmotionLevel } from '../types';
import { generateEmotionLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 5;

const EmotionGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<EmotionLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongOption, setWrongOption] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [hasWrongAttempt, setHasWrongAttempt] = useState(false);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setWrongOption(null);
    setErrorMsg(null);
    setHasWrongAttempt(false);

    const data = await generateEmotionLevel();
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      // If user has made a wrong attempt on this question, score is 0
      if (hasWrongAttempt) return 0;

      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let points = 10; // Base score

      // Speed bonus
      if (timeTaken < 3) points += 10;      // Super fast
      else if (timeTaken < 6) points += 5;  // Fast

      return points;
  }

  const handleOptionClick = (option: string) => {
      if (!level || feedback === 'correct') return;

      if (option === level.correctAnswer) {
          const points = calculateScore();
          setScore(s => s + points);
          setFeedback('correct');
          setErrorMsg(null);

          setTimeout(() => {
              if (round < TOTAL_ROUNDS) {
                  setRound(r => r + 1);
                  startRound();
              } else {
                  setIsFinished(true);
              }
          }, 1500);
      } else {
          setHasWrongAttempt(true);
          setFeedback('wrong');
          setWrongOption(option);
          setErrorMsg("再想想看！");

          setTimeout(() => {
              setFeedback(null);
              setWrongOption(null);
              setErrorMsg(null);
          }, 1500);
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 90) return { title: "同理心大師！", desc: "你能精準且快速地感受到他人的情緒！" };
      if (finalScore >= 60) return { title: "很棒的觀察！", desc: "對情緒的觀察很敏銳喔。" };
      return { title: "再接再厲！", desc: "試著多想想別人的感受喔。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200">
              <Heart className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-pink-50 flex items-center justify-center"><Loader2 className="animate-spin text-pink-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-pink-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-pink-800 shadow-sm hover:bg-pink-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
            <div className="text-pink-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
             <div className="flex items-center bg-pink-100 px-3 py-1 rounded-full text-pink-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-4 gap-6 max-w-5xl mx-auto w-full relative overflow-hidden">

          {/* Question Card */}
          <div className="flex-1 bg-white p-6 sm:p-8 rounded-[2rem] shadow-xl border-4 border-pink-100 text-center flex flex-col items-center justify-center h-auto max-h-[40vh] sm:max-h-full w-full sm:w-auto overflow-y-auto">
              {level.emoji && (
                  <div className="text-7xl sm:text-9xl mb-4 sm:mb-6 animate-bounce-short">
                      {level.emoji}
                  </div>
              )}
              <h3 className="text-xl sm:text-2xl font-bold text-gray-800 leading-relaxed">
                  {level.question}
              </h3>
          </div>

          {/* Feedback Overlay Message */}
          {errorMsg && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 animate-bounce-short pointer-events-none">
                  <div className="bg-red-100 text-red-600 px-8 py-4 rounded-2xl font-bold shadow-2xl border-2 border-red-200 text-2xl whitespace-nowrap">
                      {errorMsg}
                  </div>
              </div>
          )}

          {/* Options */}
          <div className="flex-none w-full sm:w-64 grid grid-cols-1 gap-3 sm:gap-4 overflow-y-auto">
              {level.options.map((opt, idx) => (
                  <button
                    key={idx}
                    onClick={() => handleOptionClick(opt)}
                    className={`
                        py-4 px-2 rounded-xl text-xl font-bold shadow-md transition-all active:scale-95 border-2 min-h-[4rem] flex items-center justify-center
                        ${feedback === 'correct' && opt === level.correctAnswer ? 'bg-green-500 text-white border-green-600' : ''}
                        ${feedback === 'wrong' && opt === wrongOption ? 'bg-gray-100 text-gray-400 border-gray-200 shake' : ''}
                        ${!feedback || (feedback === 'wrong' && opt !== wrongOption) ? 'bg-white text-pink-700 border-pink-200 hover:bg-pink-50' : ''}
                    `}
                  >
                      {opt}
                  </button>
              ))}
          </div>

      </div>
    </div>
  );
};

