          setScore(s => s + finalScore);
          setStreak(s => s + 1);
          setFeedback('correct');
      } else {
          setStreak(0);
          setFeedback('wrong');
      }

      // Delay then next
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
            setRound(r => r + 1);
            startRound();
        } else {
            setIsFinished(true);
        }
      }, 1000); 
