// 1. Stroop Generator
export const generateStroopLevel = async (): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));

    const colors = [
        { name: "紅", code: "text-red-500" },
        { name: "藍", code: "text-blue-500" },
        { name: "綠", code: "text-green-500" },
        { name: "黃", code: "text-yellow-500" }, // careful with visibility on white
        { name: "黑", code: "text-black" },
        { name: "紫", code: "text-purple-500" },
    ];

    // 1. Pick a display text (e.g., "RED")
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];

    // 2. Pick a display color (e.g., Blue Ink), ensure high probability of mismatch for challenge
    let colorIndex = Math.floor(Math.random() * colors.length);
    // 70% chance to force a mismatch if it accidentally matched
    if (colorIndex === textIndex && Math.random() > 0.3) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];

    // 3. Generate options (Correct answer is the COLOR Name, not the Text)
    const correctAnswer = colorObj.name;

    // Select 2 other distractors
    const distractors = colors
        .filter(c => c.name !== correctAnswer)
        .sort(() => 0.5 - Math.random())
        .slice(0, 2)
        .map(c => c.name);

    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());

    return {
        text: textObj.name,
        colorCode: colorObj.code,
        colorName: correctAnswer,
        options
    };
}

// 2. Dots Generator
export const generateDotLevel = async (round: number): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Progression for 10 Rounds:
    // Round 1: 3 dots (3x3)
    // Round 2: 4 dots (3x3)
    // Round 3: 5 dots (4x4)
    // Round 4: 6 dots (4x4)
    // Round 5: 7 dots (4x4)
    // Round 6: 8 dots (4x4)
    // Round 7: 8 dots (4x4)
    // Round 8: 9 dots (4x4) - Increased difficulty
    // Round 9: 9 dots (4x4)
    // Round 10: 10 dots (4x4) - Max challenge

    let gridSize = 3;
    let numDots = 3;
    let duration = 10000; 

    if (round === 1) numDots = 3;
    else if (round === 2) numDots = 4;
    else if (round === 3) { numDots = 5; gridSize = 4; }
    else if (round === 4) { numDots = 6; gridSize = 4; }
    else if (round === 5) { numDots = 7; gridSize = 4; }
    else if (round === 6) { numDots = 8; gridSize = 4; }
    else if (round === 7) { numDots = 8; gridSize = 4; }
    else if (round === 8) { numDots = 9; gridSize = 4; }
    else if (round === 9) { numDots = 9; gridSize = 4; }
    else if (round >= 10) { numDots = 10; gridSize = 4; }

    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];

    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }

    return { gridSize, activeIndices, duration };
}

// 4. Emotion Generator
export const generateEmotionLevel = async (): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_EMOTION_LEVELS.length);
    const level = STATIC_EMOTION_LEVELS[randomIndex];

    // Shuffle options just in case (though static data is fixed, good practice)
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());

    return {
        ...level,
        options: shuffledOptions
    };
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, RotateCcw, Check, XCircle, Trophy, Send, Eye, ArrowRight } from 'lucide-react';
import { SentenceLevel } from '../types';
import { generateSentenceLevel } from '../services/geminiService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const SentenceGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SentenceLevel | null>(null);
  const [userAnswer, setUserAnswer] = useState<{id: string, text: string}[]>([]);
  const [availableWords, setAvailableWords] = useState<{id: string, text: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Session & Scoring
  const [round, setRound] = useState(1);
  const [totalScore, setTotalScore] = useState(0);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startNewRound();
  }, []);

  const startNewRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);

    const data = await generateSentenceLevel();
    setLevel(data);
    setAvailableWords(data.scrambled);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    // Base 20 pts. Speed bonus: if < 5s, +10. if < 10s, +5.
    let bonus = 0;
    if (timeTaken < 5) bonus = 10;
    else if (timeTaken < 10) bonus = 5;
    return 20 + bonus;
  };

  const handleSelectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setUserAnswer([...userAnswer, word]);
    setAvailableWords(availableWords.filter(w => w.id !== word.id));
  };

  const handleDeselectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setAvailableWords([...availableWords, word]);
    setUserAnswer(userAnswer.filter(w => w.id !== word.id));
  };

  const handleNextLevel = () => {
    if (round < TOTAL_ROUNDS) {
        setRound(r => r + 1);
        startNewRound();
     } else {
        setIsSessionFinished(true);
     }
  };

  const checkAnswer = () => {
    if (!level) return;

    // If already correct, the button acts as "Next Level"
    if (isCorrect) {
        handleNextLevel();
        return;
    }

    const currentString = userAnswer.map(w => w.text).join('');
    if (currentString === level.original) {
        // Correct
        const roundScore = calculateScore();
        setTotalScore(s => s + roundScore);
        setIsCorrect(true);
        // Removed setTimeout, user must click "Next"
    } else {
        // Wrong (No penalty)
        setShowError(true);
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleShowAnswer = () => {
    if (!level || isCorrect) return;

    // Combine all words
    const allWords = [...userAnswer, ...availableWords];
    // Sort based on ID (which is index-char, e.g., "0-早")
    allWords.sort((a, b) => {
        const indexA = parseInt(a.id.split('-')[0]);
        const indexB = parseInt(b.id.split('-')[0]);
        return indexA - indexB;
    });

    setUserAnswer(allWords);
    setAvailableWords([]);
    setIsCorrect(true);
    // Do NOT add score
    // Removed setTimeout, user must click "Next"
  };

  const resetCurrent = () => {
    if (!level) return;
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);
    setAvailableWords(level.scrambled);
  }

  const handleRestart = () => {
      setRound(1);
      setTotalScore(0);
      setIsSessionFinished(false);
      startNewRound();
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[100dvh] bg-pink-50 p-4 animate-fade-in overflow-y-auto">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200 my-4">
              <Trophy className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">練習完成！</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{totalScore}</div>
              <p className="text-gray-600 mb-8">
                  你的造句能力很棒！<br/>邏輯非常清晰。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
}

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[100dvh] bg-pink-50">
        <Loader2 className="w-12 h-12 text-pink-500 animate-spin mb-4" />
        <p className="text-pink-700">準備句子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[100dvh] bg-pink-50 overflow-hidden">
