  if (!level) return null;

  return (
    <div className="flex flex-col h-screen bg-yellow-50 overflow-hidden relative">
        {/* Header - Very compact */}
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-20">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-yellow-800 shadow-sm hover:bg-yellow-100">
                <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                 <div className="px-3 py-1 bg-yellow-100 rounded-full text-yellow-800 font-bold text-sm">
                    第 {round} / {TOTAL_ROUNDS} 題
                </div>
                <div className="flex items-center bg-yellow-100 px-3 py-1 rounded-full text-yellow-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {totalScore}
                </div>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 gap-2 sm:gap-6 w-full h-full">

            {/* Target Instruction - Left (Landscape) or Top (Portrait) */}
            <div className="shrink-0 z-10 bg-yellow-100/80 p-2 sm:p-4 rounded-xl flex flex-row sm:flex-col items-center justify-center shadow-sm gap-3 sm:gap-4 border border-yellow-200">
                <span className="text-gray-700 font-medium text-sm sm:text-lg">請找出：</span>
                <div className="bg-white border-2 sm:border-4 border-yellow-400 rounded-lg sm:rounded-2xl w-12 h-12 sm:w-20 sm:h-20 flex items-center justify-center shadow-inner">
                        <span className="text-3xl sm:text-5xl leading-none">{level.target}</span>
                </div>
            </div>

            {/* Error Message Toast */}
            {errorMsg && (
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 animate-bounce-short pointer-events-none">
                    <div className="bg-red-100 border-2 border-red-400 text-red-700 px-6 py-4 rounded-xl shadow-xl flex items-center whitespace-nowrap">
                        <AlertCircle className="w-6 h-6 mr-2" />
                        <span className="font-bold text-lg">{errorMsg}</span>
                    </div>
                </div>
            )}

            {/* Grid Container Wrapper
                Logic: 
                - Portrait: Width constrained (90vw), Height adapts.
                - Landscape: Height constrained (75vh), Width adapts to maintain aspect ratio.
                This effectively "scales" the content to fit the screen without scrolling.
            */}
            <div className="
                relative flex justify-center items-center shrink-0
                w-[90vw] h-[90vw] max-w-[500px] max-h-[500px] 
                sm:w-auto sm:h-[75vh] sm:aspect-square
            ">
                <div className="flex flex-col w-full h-full">
                    {/* Column Labels (A-D) */}
                    <div className="flex pl-8 mb-1">
                        {['A', 'B', 'C', 'D'].map(label => (
                            <div key={label} className="flex-1 text-center font-bold text-yellow-700 text-lg md:text-xl">
                                {label}
                            </div>
                        ))}
                    </div>

                    <div className="flex flex-1">
                        {/* Row Labels (1-4) */}
                        <div className="flex flex-col w-8 justify-around pr-1">
                            {[1, 2, 3, 4].map(label => (
                                <div key={label} className="flex-1 flex items-center justify-center font-bold text-yellow-700 text-lg md:text-xl">
                                    {label}
                                </div>
                            ))}
                        </div>

                        {/* Buttons Grid - 4x4 */}
                        <div className="flex-1 grid grid-cols-4 gap-1.5 sm:gap-2 bg-white rounded-xl shadow-lg p-2 border-2 sm:border-4 border-yellow-100">
                            {Array.from({ length: level.gridSize }).map((_, index) => {
                                const isTarget = index === level.targetPosition;
                                return (
                                    <button
                                        key={index}
                                        onClick={() => handleItemClick(index)}
                                        className={`
                                            w-full h-full flex items-center justify-center text-3xl md:text-4xl rounded-lg transition-all duration-200
                                            ${showResult && isTarget ? 'bg-green-200 border-2 border-green-500 scale-105 z-10' : 'bg-gray-50 hover:bg-yellow-50 active:bg-yellow-100'}
                                            ${showResult && !isTarget ? 'opacity-30' : ''}
                                        `}
                                    >
                                        <span className="pointer-events-none select-none">
                                            {isTarget ? level.target : level.distractor}
                                        </span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

export default FindGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, CheckCircle, XCircle } from 'lucide-react';
import { MarketLevel } from '../types';
import { generateMarketLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const MarketGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<MarketLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongOption, setWrongOption] = useState<number | null>(null);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setWrongOption(null);
    const data = await generateMarketLevel();
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 5) bonus = 10;
      else if (timeTaken < 10) bonus = 5;
      return 20 + bonus;
  }

  const handleOptionClick = (value: number) => {
    if (!level || feedback === 'correct') return;

    if (value === level.correctAnswer) {
      const roundScore = calculateScore();
      setScore(s => s + roundScore);
      setFeedback('correct');
      soundService.playCorrect();
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
        } else {
          setIsFinished(true);
          soundService.playWin();
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      setWrongOption(value);
      soundService.playWrong();
      setTimeout(() => {
          setFeedback(null);
          setWrongOption(null);
      }, 1000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-green-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-green-200">
              <Trophy className="w-20 h-20 text-green-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-green-900 mb-2">採購完成！</h2>
              <div className="text-6xl font-black text-green-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的算術能力很棒！<br/>金錢管理沒問題。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-green-500 text-white rounded-xl font-bold hover:bg-green-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-green-50">
        <Loader2 className="w-12 h-12 text-green-600 animate-spin mb-4" />
        <p className="text-green-800">準備市集中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-green-50 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-green-800 shadow-sm hover:bg-green-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
             <div className="px-3 py-1 bg-green-100 rounded-full text-green-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-green-100 px-3 py-1 rounded-full text-green-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      {/* Main Content: Flex-col portrait, Flex-row landscape */}
      <div className="flex-1 flex flex-col sm:flex-row items-center p-2 sm:p-4 max-w-4xl mx-auto w-full gap-4 sm:gap-6 overflow-hidden">

        {/* Question Area - Left in Landscape */}
        <div className="flex-none sm:flex-1 w-full sm:h-full bg-white rounded-3xl p-4 sm:p-6 shadow-lg border-2 border-green-100 flex flex-col items-center justify-center animate-fade-in-up overflow-y-auto max-h-[45vh] sm:max-h-none">
            <h2 className="text-lg md:text-2xl font-bold text-gray-800 mb-4 text-center sticky top-0 bg-white/95 py-2 z-10">{level.question}</h2>

            <div className="flex flex-wrap justify-center gap-4 mb-2 w-full">
                {level.items.map((item, idx) => (
                    <div key={idx} className="flex flex-col items-center p-2 bg-green-50 rounded-xl border border-green-200 w-24 sm:w-28 shrink-0">
                        <div className="text-4xl sm:text-5xl mb-1">{item.icon}</div>
                        <div className="font-bold text-gray-700 mb-1 text-sm sm:text-base whitespace-nowrap">{item.name}</div>
                        <div className="bg-green-600 text-white px-3 py-0.5 rounded-full text-xs sm:text-sm font-bold shadow-sm">
                            ${item.price}
                        </div>
                    </div>
                ))}
            </div>
        </div>

        {/* Options Area - Right in Landscape */}
        <div className="flex-none sm:flex-1 w-full sm:h-full flex flex-col justify-center gap-3 sm:gap-4 overflow-y-auto">
            {level.options.map((opt, idx) => (
                <button
                    key={idx}
                    onClick={() => handleOptionClick(opt)}
                    className={`
                        w-full py-4 sm:py-6 rounded-2xl text-2xl sm:text-3xl font-bold shadow-md border-2 transition-all active:scale-95 flex items-center justify-center shrink-0
                        ${feedback === 'correct' && opt === level.correctAnswer ? 'bg-green-500 text-white border-green-600' : ''}
                        ${feedback === 'wrong' && opt === wrongOption ? 'bg-gray-100 text-gray-400 border-gray-200 shake' : ''}
                        ${!feedback || (feedback === 'wrong' && opt !== wrongOption) ? 'bg-white text-green-800 border-green-200 hover:bg-green-50 hover:border-green-300' : ''}
                    `}
                    disabled={feedback === 'correct'}
                >
                    <span className="mr-1">$</span> {opt}
                    {feedback === 'correct' && opt === level.correctAnswer && <CheckCircle className="ml-3 w-6 h-6 animate-bounce" />}
                </button>
            ))}
        </div>

        {/* Feedback Message */}
        {feedback === 'wrong' && (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 text-red-600 px-6 py-3 rounded-full font-bold shadow-xl animate-bounce-short border-2 border-red-200 whitespace-nowrap z-50 pointer-events-none">
                算錯囉，再試一次！
            </div>
        )}
      </div>
    </div>
  );
};

export default MarketGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, RotateCcw, Check, Eye } from 'lucide-react';
import { StepsLevel, StepItem } from '../types';
import { generateStepsLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const StepsGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StepsLevel | null>(null);
  const [availableSteps, setAvailableSteps] = useState<StepItem[]>([]);
  const [userOrder, setUserOrder] = useState<StepItem[]>([]);
  const [loading, setLoading] = useState(true);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Track used titles to prevent repetition in a session
  const [usedTitles, setUsedTitles] = useState<string[]>([]);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserOrder([]);

    // Pass current history of used titles to filter them out
    const data = await generateStepsLevel(usedTitles);
    setLevel(data);
    setAvailableSteps(data.steps); 

    // Add new title to history
    setUsedTitles(prev => [...prev, data.title]);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 10) bonus = 10;
      else if (timeTaken < 20) bonus = 5;
      return 20 + bonus;
  }

  const handleSelectStep = (step: StepItem) => {
    if (isCorrect) return;
    setUserOrder([...userOrder, step]);
    setAvailableSteps(availableSteps.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleDeselectStep = (step: StepItem) => {
    if (isCorrect) return;
    setAvailableSteps([...availableSteps, step]);
    setUserOrder(userOrder.filter(s => s.id !== step.id));
    setShowError(false);
  };

  const handleReset = () => {
     if (!level || isCorrect) return;
     setAvailableSteps([...availableSteps, ...userOrder]);
     setUserOrder([]);
  };

  const handleNextLevel = () => {
    if (round < TOTAL_ROUNDS) {
        setRound(r => r + 1);
        startRound();
    } else {
        setIsFinished(true);
        soundService.playWin();
    }
  };

  const checkAnswer = () => {
    if (!level) return;

    // If already correct, button acts as Next
    if (isCorrect) {
        handleNextLevel();
        return;
    }

    let correct = true;
    for (let i = 0; i < userOrder.length; i++) {
        if (userOrder[i].order !== i + 1) {
            correct = false;
            break;
        }
    }

    if (correct && userOrder.length === level.steps.length) {
        setIsCorrect(true);
        const roundScore = calculateScore();
        setScore(s => s + roundScore);
        soundService.playCorrect();
    } else {
        setShowError(true);
        soundService.playWrong();
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleShowAnswer = () => {
      if (!level || isCorrect) return;

      const allSteps = [...userOrder, ...availableSteps];
      allSteps.sort((a, b) => a.order - b.order);

      setUserOrder(allSteps);
      setAvailableSteps([]);
      setIsCorrect(true);

      // Do NOT add score
      soundService.playCorrect();
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    setUsedTitles([]); // Reset history on restart
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-purple-200">
              <Check className="w-20 h-20 text-purple-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-purple-900 mb-2">步驟大師！</h2>
              <div className="text-6xl font-black text-purple-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的邏輯非常清晰！<br/>做事井然有序。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-purple-500 text-white rounded-xl font-bold hover:bg-purple-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-purple-50">
        <Loader2 className="w-12 h-12 text-purple-600 animate-spin mb-4" />
        <p className="text-purple-800">準備步驟中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[100dvh] bg-purple-50 overflow-hidden relative">
      {/* Header - Extremely Compact */}
      <div className="flex-none px-3 py-1 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10 h-12">
        <button onClick={onBack} className="p-1.5 bg-white rounded-full text-purple-800 shadow-sm hover:bg-purple-100">
          <ArrowLeft size={18} />
        </button>
        <div className="flex items-center gap-2">
             <div className="px-2 py-0.5 bg-purple-100 rounded-full text-purple-800 font-bold text-xs sm:text-sm">
                題 {round}/{TOTAL_ROUNDS}
             </div>
             <div className="flex items-center bg-purple-100 px-2 py-0.5 rounded-full text-purple-800 font-bold text-sm">
                <Trophy size={14} className="mr-1"/> {score}
             </div>
        </div>
        <button onClick={startRound} className="px-3 py-1 bg-white rounded-full text-purple-600 text-xs sm:text-sm font-medium hover:bg-purple-100 shadow-sm">
            跳過
        </button>
      </div>

      <div className="flex-1 flex flex-col sm:flex-row p-2 max-w-6xl mx-auto w-full gap-2 relative overflow-hidden min-h-0">

        {/* Game Area: Split View in Landscape, Vertical Stack in Portrait */}

        {/* Left/Top: Answer Drop Zone + Controls */}
        <div className="flex-[1.2] flex flex-col min-h-0 bg-white/60 rounded-xl border-2 border-purple-200 shadow-inner overflow-hidden relative">

            {/* Embedded Title Header */}
            <div className="flex-none bg-purple-100/50 p-2 text-center border-b border-purple-200">
                <h2 className="text-base sm:text-lg font-bold text-purple-900 truncate leading-tight">
                    題目：<span className="text-purple-700">{level.title}</span>
                </h2>
                <div className="text-purple-400 text-xs">請依序點擊右方選項</div>
            </div>

            {/* Answer Content - Flex Wrap (Auto-width) */}
            <div className="flex-1 overflow-y-auto p-2">
                 <div className="flex flex-wrap gap-2 content-start items-center">
                    {userOrder.length === 0 && (
                        <div className="w-full h-20 flex items-center justify-center text-purple-300 font-bold text-sm">
                            答案區 (空白)
                        </div>
                    )}

                    {userOrder.map((step, idx) => (
                        <React.Fragment key={step.id}>
                            <button 
                                onClick={() => handleDeselectStep(step)}
                                className="group w-auto bg-white border border-purple-300 text-purple-900 px-3 py-1.5 rounded-full font-bold shadow-sm hover:bg-red-50 hover:border-red-300 hover:text-red-600 transition-all flex items-center gap-2 animate-fade-in text-sm sm:text-base whitespace-nowrap"
                            >
                                <div className="w-5 h-5 sm:w-6 sm:h-6 rounded-full bg-purple-100 text-purple-700 flex items-center justify-center text-xs group-hover:bg-red-100 group-hover:text-red-600">
                                    {idx + 1}
                                </div>
                                {step.text}
                            </button>
                            {/* Visual connector */}
                            {idx < userOrder.length - 1 && (
                                <ArrowRight className="text-purple-200 w-4 h-4" />
                            )}
                        </React.Fragment>
                    ))}
                 </div>
            </div>

            {/* Controls - Docked inside the Left/Top Pane at bottom */}
            <div className="flex-none p-2 bg-white/50 border-t border-purple-100 flex gap-2">
                <button 
                    onClick={handleShowAnswer}
                    disabled={isCorrect}
                    className="p-2 sm:px-4 bg-yellow-100 text-yellow-700 rounded-lg shadow-sm disabled:opacity-50 active:scale-95 transition-transform flex items-center justify-center gap-1"
                >
                    <Eye size={18} />
                    <span className="text-sm font-bold hidden sm:inline">答案</span>
                </button>
                <button 
                    onClick={handleReset}
                    disabled={userOrder.length === 0 || isCorrect}
                    className="p-2 sm:px-4 bg-gray-200 text-gray-700 rounded-lg shadow-sm disabled:opacity-50 active:scale-95 transition-transform flex items-center justify-center gap-1"
                >
                    <RotateCcw size={18} />
                    <span className="text-sm font-bold hidden sm:inline">重置</span>
                </button>
                <button 
                    onClick={checkAnswer}
                    disabled={availableSteps.length > 0 && !isCorrect}
                    className={`
                        flex-1 text-white text-base font-bold rounded-lg shadow-md hover:opacity-90 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 active:scale-95 py-2
                        ${isCorrect ? 'bg-green-600' : 'bg-purple-600'}
                    `}
                >
                    {isCorrect ? "下一題" : "確認"}
                    {isCorrect ? <ArrowRight size={18} /> : <Check size={18} />}
                </button>
            </div>
        </div>

        {/* Right/Bottom: Source Options - Compact Flex Wrap */}
        <div className="flex-1 min-h-0 bg-white rounded-xl shadow-lg border border-purple-100 flex flex-col overflow-hidden">
                <div className="flex-none bg-gray-50 p-1.5 text-center text-gray-400 text-xs border-b border-gray-100">
                    選項區
                </div>

                {/* Scrollable Area */}
                <div className="flex-1 overflow-y-auto p-2">
                    {/* Flex Wrap for auto width */}
                    <div className="flex flex-wrap gap-2 justify-center sm:justify-start content-start">
                    {availableSteps.map(step => (
                        <button 
                            key={step.id}
                            onClick={() => handleSelectStep(step)}
                            className="w-auto bg-purple-50 text-purple-900 border border-purple-200 px-3 py-2 rounded-lg font-bold shadow-sm hover:bg-purple-100 hover:border-purple-300 active:scale-95 transition-all text-sm sm:text-base whitespace-nowrap"
                        >
                            {step.text}
                        </button>
                    ))}
                    </div>
                </div>
        </div>

        {showError && (
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 border-2 border-red-400 text-red-700 px-6 py-3 rounded-2xl font-bold shadow-2xl animate-bounce-short text-lg whitespace-nowrap z-50 pointer-events-none">
                 順序不對喔！
             </div>
        )}

      </div>
    </div>
  );
};

export default StepsGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Sun, CheckCircle } from 'lucide-react';
import { ShadowLevel } from '../types';
import { generateShadowLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const ShadowGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<ShadowLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongIndex, setWrongIndex] = useState<number | null>(null);
  const [showErrorMsg, setShowErrorMsg] = useState(false);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setWrongIndex(null);
    setShowErrorMsg(false);
    const data = await generateShadowLevel();
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 5) bonus = 10;
      else if (timeTaken < 10) bonus = 5;
      return 20 + bonus;
  }

  const handleOptionClick = (idx: number) => {
    if (!level || feedback === 'correct') return;

    if (idx === level.correctIndex) {
      const roundScore = calculateScore();
      setScore(s => s + roundScore);
      setFeedback('correct');
      soundService.playCorrect();
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
        } else {
          setIsFinished(true);
          soundService.playWin();
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      setWrongIndex(idx);
      setShowErrorMsg(true);
      soundService.playWrong();
      setTimeout(() => {
        setFeedback(null);
        setWrongIndex(null);
        setShowErrorMsg(false);
      }, 1000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-slate-300">
              <Sun className="w-20 h-20 text-slate-800 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-slate-900 mb-2">觀察入微！</h2>
              <div className="text-6xl font-black text-slate-700 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的視覺辨識能力很強！<br/>完全難不倒你。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-700 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50">
        <Loader2 className="w-12 h-12 text-slate-600 animate-spin mb-4" />
        <p className="text-slate-800">準備影子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-100 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-slate-800 shadow-sm hover:bg-slate-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
             <div className="px-3 py-1 bg-slate-200 rounded-full text-slate-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-slate-200 px-3 py-1 rounded-full text-slate-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      {/* Main Content: Flex-col on portrait, Flex-row on landscape/large screens */}
      <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 sm:p-4 max-w-4xl mx-auto w-full gap-4 md:gap-8 overflow-hidden">

        {/* Target Area */}
        <div className="flex-none sm:flex-1 bg-white p-4 md:p-8 rounded-[2rem] shadow-xl border-4 border-white ring-4 ring-slate-200 flex flex-col items-center justify-center h-auto sm:h-auto w-full sm:w-auto max-h-[40vh] sm:max-h-none">
             <div className="text-7xl sm:text-8xl md:text-9xl filter drop-shadow-lg mb-2 animate-bounce-short">
                 {level.target}
             </div>
             <p className="text-slate-500 font-bold text-base md:text-lg">它的影子是哪一個？</p>
        </div>

        {/* Options Area - 2x2 Grid */}
        <div className="flex-none sm:flex-1 w-full sm:w-auto max-w-md aspect-square max-h-[50vh] sm:max-h-none">
            <div className="grid grid-cols-2 gap-3 sm:gap-4 w-full h-full">
                {level.options.map((opt, idx) => (
                    <button
                        key={idx}
                        onClick={() => handleOptionClick(idx)}
                        className={`
                            w-full h-full rounded-2xl flex flex-col items-center justify-center relative transition-all duration-200 p-2 border-2
                            ${feedback === 'correct' && idx === level.correctIndex ? 'bg-green-100 border-green-500 scale-105 z-10' : ''}
                            ${feedback === 'wrong' && idx === wrongIndex ? 'bg-red-100 border-red-400 shake' : 'border-transparent'}
                            ${!feedback || (feedback === 'wrong' && idx !== wrongIndex) ? 'bg-white shadow-md hover:bg-slate-50 hover:shadow-xl hover:-translate-y-1' : ''}
                        `}
                        disabled={feedback === 'correct'}
                    >
                        {/* Number label */}
                        <div className="absolute top-2 left-3 text-slate-400 font-bold text-lg md:text-xl">
                            {idx + 1}
                        </div>

                        {/* Render the emoji as a black silhouette */}
                        <span 
                            className="transition-all duration-500 text-5xl sm:text-6xl md:text-7xl mb-1"
                            style={{ 
                                filter: feedback === 'correct' && idx === level.correctIndex ? 'none' : 'brightness(0)',
                                opacity: feedback === 'correct' && idx === level.correctIndex ? 1 : 0.7 
                            }}
                        >
                            {opt}
                        </span>

                        {/* Overlay Success Icon */}
                        {feedback === 'correct' && idx === level.correctIndex && (
                            <div className="absolute -top-2 -right-2 bg-white rounded-full">
                                <CheckCircle className="text-green-500 w-8 h-8" />
                            </div>
                        )}
                    </button>
                ))}
            </div>
        </div>

        {/* Error Feedback Text (Fixed Position) */}
        {showErrorMsg && (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 text-red-600 px-8 py-4 rounded-2xl font-bold shadow-2xl animate-bounce-short text-xl whitespace-nowrap z-50 border-2 border-red-200 pointer-events-none">
                再看清楚一點喔！
            </div>
        )}

      </div>
    </div>
  );
};

export default ShadowGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Clock, CheckCircle } from 'lucide-react';
import { StroopLevel } from '../types';
import { generateStroopLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const StroopGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<StroopLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [streak, setStreak] = useState(0);
  const [isFinished, setIsFinished] = useState(false);

  // Feedback States
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  // Timer for scoring
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    const data = await generateStroopLevel();
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const handleAnswer = (answer: string) => {
      if (!level || feedback !== null) return; // Prevent double clicks

      const isCorrect = answer === level.colorName;

      if (isCorrect) {
          const timeTaken = (Date.now() - startTimeRef.current) / 1000;

          // Scoring logic: Faster is better
          let points = 10;
          if (timeTaken < 2) points += 10;
          else if (timeTaken < 4) points += 5;

          // Streak bonus
          const finalScore = points + (streak * 2);

          setScore(s => s + finalScore);
          setStreak(s => s + 1);
          setFeedback('correct');
          soundService.playCorrect();
      } else {
          setStreak(0);
          setFeedback('wrong');
          soundService.playWrong();
      }

      // Delay then next
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
            setRound(r => r + 1);
            startRound();
        } else {
            setIsFinished(true);
            soundService.playWin();
        }
      }, 1000); 
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setStreak(0);
      setIsFinished(false);
      startRound();
  }

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 180) return { title: "反應神速！", desc: "你的大腦處理速度非常驚人！" };
      if (finalScore >= 120) return { title: "表現優異！", desc: "你的專注力保持得很好喔。" };
      return { title: "再接再厲！", desc: "慢慢練習，準確度最重要。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-rose-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-rose-200">
              <Trophy className="w-20 h-20 text-rose-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-rose-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-rose-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold hover:bg-rose-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-rose-50 flex items-center justify-center"><Loader2 className="animate-spin text-rose-500"/></div>;
  }

  return (
    <div className={`flex flex-col h-screen overflow-hidden transition-colors duration-300 ${feedback === 'wrong' ? 'bg-red-50' : 'bg-rose-50'}`}>
       {/* Header */}
       <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-rose-800 shadow-sm hover:bg-rose-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-rose-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-rose-100 px-3 py-1 rounded-full text-rose-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        {/* Main Content - Allow scrolling if height is small (landscape) */}
        <div className="flex-1 overflow-y-auto p-4">
            <div className="flex flex-col sm:flex-row items-center justify-center gap-4 sm:gap-8 min-h-full">

                {/* Left Side: Question */}
                <div className="flex-none flex flex-col items-center justify-center max-w-sm">
                    <p className="text-gray-500 text-lg mb-2 text-center shrink-0">
                        請回答這個字的 <span className="font-bold text-black underline decoration-rose-500 decoration-4">顏色</span>
                    </p>

                    {/* The Stroop Word - Responsive Sizing */}
                    <div className="bg-white rounded-3xl shadow-xl border-4 border-rose-100 w-56 h-56 sm:w-72 sm:h-72 flex items-center justify-center relative shrink-0">
                        <span className={`text-7xl sm:text-9xl font-black ${level.colorCode}`}>
                            {level.text}
                        </span>

                        {/* Feedback Overlay */}
                        {feedback === 'correct' && (
                            <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                                <div className="text-green-600 flex flex-col items-center">
                                    <CheckCircle className="w-16 h-16 mb-2" />
                                    <span className="text-3xl font-bold">答對了！</span>
                                </div>
                            </div>
                        )}
                        {feedback === 'wrong' && (
                             <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                                <div className="text-red-500 flex flex-col items-center">
                                    <span className="text-3xl font-bold">看錯囉！</span>
                                    <span className="text-xl mt-2">是 {level.colorName} 色</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Right Side: Options - Responsive Grid */}
                <div className="flex-none w-full max-w-sm grid grid-cols-3 gap-3 sm:gap-4 content-center">
                    {level.options.map((opt, idx) => (
                        <button
                            key={idx}
                            onClick={() => handleAnswer(opt)}
                            disabled={feedback !== null}
                            className="py-3 sm:py-4 bg-white border-2 border-rose-200 rounded-xl text-xl sm:text-2xl font-bold text-gray-700 shadow-md hover:bg-rose-100 active:scale-95 transition-all disabled:opacity-50 h-20 sm:h-24 flex items-center justify-center"
                        >
                            {opt}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    </div>
  );
};

export default StroopGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, Eye, Play, ArrowRight, CheckCircle, XCircle } from 'lucide-react';
import { DotLevel } from '../types';
import { generateDotLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const DotGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<DotLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [gameState, setGameState] = useState<'memorize' | 'recall' | 'result'>('memorize');
  const [userSelection, setUserSelection] = useState<number[]>([]);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [countdown, setCountdown] = useState(0);

  // Feedback text
  const [feedbackText, setFeedbackText] = useState("");

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setGameState('memorize');
    setUserSelection([]);
    setFeedbackText("");

    const data = await generateDotLevel(round);
    setLevel(data);
    setLoading(false);

    // Countdown for memorize phase
    setCountdown(data.duration / 1000);
  };

  // Timer for Memorize Phase
  useEffect(() => {
    if (gameState === 'memorize' && level) {
        const timer = setTimeout(() => {
            setGameState('recall');
        }, level.duration);

        // Visual countdown
        const interval = setInterval(() => {
            setCountdown(c => Math.max(0, c - 0.1));
        }, 100);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }
  }, [gameState, level]);

  const handleCellClick = (index: number) => {
    if (gameState !== 'recall') return;

    // Toggle selection
    let newSelection = [...userSelection];
    if (newSelection.includes(index)) {
        newSelection = newSelection.filter(i => i !== index);
    } else {
        // Limit selection to number of dots
        if (level && newSelection.length < level.activeIndices.length) {
            newSelection.push(index);
        }
    }
    setUserSelection(newSelection);
  };

  const checkAnswer = () => {
      if (!level) return;

      const correctSet = new Set(level.activeIndices);
      const userSet = new Set(userSelection);

      // Check if sets match
      let isCorrect = true;
      if (correctSet.size !== userSet.size) isCorrect = false;
      for (let elem of userSet) {
          if (!correctSet.has(elem)) isCorrect = false;
      }

      if (isCorrect) {
          setScore(s => s + 20); // 20 pts per round
          setFeedbackText("太棒了！位置完全正確！");
          soundService.playCorrect();
      } else {
          setFeedbackText("再接再厲！看下面的正確答案。");
          soundService.playWrong();
      }

      setGameState('result');
  };

  const handleNextLevel = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setIsFinished(false);
      startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 160) return { title: "記憶大師！", desc: "你的空間記憶力超群！" };
      if (finalScore >= 100) return { title: "表現不錯！", desc: "大部分的位置都記住了。" };
      return { title: "繼續加油！", desc: "多練習幾次，你會進步的。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-cyan-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-cyan-200">
              <Trophy className="w-20 h-20 text-cyan-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-cyan-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-cyan-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-cyan-500 text-white rounded-xl font-bold hover:bg-cyan-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-cyan-50 flex items-center justify-center"><Loader2 className="animate-spin text-cyan-500"/></div>;
  }

  // Dynamic sizing logic
  // Use vmin to keep it square and fitting within the smaller dimension of the screen
  const gridContainerStyle = {
      gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
      width: 'min(75vmin, 450px)',
      height: 'min(75vmin, 450px)', 
  };

  // Adjust font size based on grid density to prevent layout break
  const fontSizeClass = level.gridSize > 3 ? 'text-3xl sm:text-5xl' : 'text-4xl sm:text-6xl';

  return (
    <div className="flex flex-col h-screen bg-cyan-50 overflow-hidden relative">
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-cyan-800 shadow-sm hover:bg-cyan-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                <div className="text-cyan-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-cyan-100 px-3 py-1 rounded-full text-cyan-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 gap-4 sm:gap-12 overflow-hidden">

            {/* Left Side (Landscape): Grid */}
            <div className="flex-none flex items-center justify-center">
                <div 
                    className="grid gap-2 bg-white p-3 rounded-2xl shadow-lg border-4 border-cyan-200"
                    style={gridContainerStyle}
                >
                    {Array.from({ length: level.gridSize * level.gridSize }).map((_, idx) => {
                        let bgColor = "bg-cyan-50";
                        let borderColor = "border-cyan-100";
                        let textColor = "text-cyan-300";

                        if (gameState === 'memorize') {
                            if (level.activeIndices.includes(idx)) {
                                bgColor = "bg-red-500";
                                borderColor = "border-red-600";
                                textColor = "text-transparent"; // Hide text in memorize phase
                            } else {
                                textColor = "text-transparent"; // Hide text in memorize phase
                            }
                        } else if (gameState === 'recall') {
                            if (userSelection.includes(idx)) {
                                bgColor = "bg-cyan-500";
                                borderColor = "border-cyan-600";
                                textColor = "text-white";
                            } else {
                                bgColor = "bg-cyan-50 hover:bg-cyan-100 cursor-pointer";
                            }
                        } else if (gameState === 'result') {
                            const wasCorrect = level.activeIndices.includes(idx);
                            const userSelected = userSelection.includes(idx);

                            if (wasCorrect && userSelected) {
                                bgColor = "bg-green-500"; // Correct hit
                                textColor = "text-white";
                            } else if (wasCorrect && !userSelected) {
                                bgColor = "bg-red-400 opacity-70"; // Missed
                                textColor = "text-white";
                            } else if (!wasCorrect && userSelected) {
                                bgColor = "bg-gray-400"; // Wrong selection
                                textColor = "text-white";
                            }
                        }

                        return (
                            <div 
                                key={idx}
                                onClick={() => handleCellClick(idx)}
                                className={`rounded-xl border-2 transition-all duration-200 ${bgColor} ${borderColor} flex items-center justify-center`}
                            >
                                <span className={`${fontSizeClass} font-black ${textColor} transition-opacity duration-300 select-none`}>
                                    {idx + 1}
                                </span>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* Right Side (Landscape): Controls & Instruction */}
            <div className="flex-none flex flex-col items-center justify-center max-w-sm text-center">
                <h2 className="text-xl sm:text-2xl font-bold text-cyan-900 mb-4 sm:mb-6">
                    {gameState === 'memorize' && <span className="flex flex-col items-center"><Eye className="mb-2 w-8 h-8"/> 記住紅點位置 <br/><span className="text-4xl mt-2 text-red-500">{countdown.toFixed(0)}</span></span>}
                    {gameState === 'recall' && <span className="flex flex-col items-center text-orange-600">點擊剛才的數字位置</span>}
                    {gameState === 'result' && <span className="text-blue-600 text-3xl">答案揭曉</span>}
                </h2>

                {gameState === 'recall' && (
                    <button 
