                    </button>
                )}

                {gameState === 'result' && (
                    <div className="flex flex-col items-center animate-fade-in-up w-full">
                        <div className={`text-xl font-bold mb-4 sm:mb-6 flex items-center ${feedbackText.includes("棒") ? "text-green-600" : "text-gray-600"}`}>
