import { SortingLevel, SentenceLevel, FindLevel, MarketLevel, StepsLevel, ShadowLevel, StroopLevel, DotLevel, EmotionLevel } from "../types";
import { 
    STATIC_SENTENCES, 
    STATIC_SORTING_LEVELS, 
    STATIC_FIND_PAIRS, 
