// 1. Stroop Generator
export const generateStroopLevel = async (): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));

    const colors = [
        { name: "紅", code: "text-red-500" },
        { name: "藍", code: "text-blue-500" },
        { name: "綠", code: "text-green-500" },
        { name: "黃", code: "text-yellow-500" }, // careful with visibility on white
        { name: "黑", code: "text-black" },
        { name: "紫", code: "text-purple-500" },
    ];

    // 1. Pick a display text (e.g., "RED")
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];

    // 2. Pick a display color (e.g., Blue Ink), ensure high probability of mismatch for challenge
    let colorIndex = Math.floor(Math.random() * colors.length);
    // 70% chance to force a mismatch if it accidentally matched
    if (colorIndex === textIndex && Math.random() > 0.3) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];

    // 3. Generate options (Correct answer is the COLOR Name, not the Text)
    const correctAnswer = colorObj.name;

    // Select 2 other distractors
    const distractors = colors
        .filter(c => c.name !== correctAnswer)
        .sort(() => 0.5 - Math.random())
        .slice(0, 2)
        .map(c => c.name);

    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());

    return {
        text: textObj.name,
        colorCode: colorObj.code,
        colorName: correctAnswer,
        options
    };
}

// 2. Dots Generator
export const generateDotLevel = async (round: number): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));

    // Progression for 10 Rounds:
    // Round 1: 3 dots (3x3)
    // Round 2: 4 dots (3x3)
    // Round 3: 5 dots (4x4)
    // Round 4: 6 dots (4x4)
    // Round 5: 7 dots (4x4)
    // Round 6: 8 dots (4x4)
    // Round 7: 8 dots (4x4)
    // Round 8: 9 dots (4x4) - Increased difficulty
    // Round 9: 9 dots (4x4)
    // Round 10: 10 dots (4x4) - Max challenge

    let gridSize = 3;
    let numDots = 3;
    let duration = 10000; 

    if (round === 1) numDots = 3;
    else if (round === 2) numDots = 4;
    else if (round === 3) { numDots = 5; gridSize = 4; }
    else if (round === 4) { numDots = 6; gridSize = 4; }
    else if (round === 5) { numDots = 7; gridSize = 4; }
    else if (round === 6) { numDots = 8; gridSize = 4; }
    else if (round === 7) { numDots = 8; gridSize = 4; }
    else if (round === 8) { numDots = 9; gridSize = 4; }
    else if (round === 9) { numDots = 9; gridSize = 4; }
    else if (round >= 10) { numDots = 10; gridSize = 4; }

    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];

    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }

    return { gridSize, activeIndices, duration };
}

// 4. Emotion Generator
export const generateEmotionLevel = async (): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const randomIndex = Math.floor(Math.random() * STATIC_EMOTION_LEVELS.length);
    const level = STATIC_EMOTION_LEVELS[randomIndex];

    // Shuffle options just in case (though static data is fixed, good practice)
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());

    return {
        ...level,
        options: shuffledOptions
    };
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, ThumbsUp, AlertCircle, Clock, Trophy, ArrowRight, CheckCircle, XCircle } from 'lucide-react';
import { SortingLevel } from '../types';
import { generateSortingLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';
// We need to access STATIC_SORTING_LEVELS length to randomize the initial index, 
// but since we can't import it directly from staticData easily without exposing it, 
// we will just assume a large enough range or rely on the service to handle the initial random pick if we pass null.
// However, to keep it simple and clean, let's just make the service handle "pick a random index and return it" effectively by calling it once without ID.
// Actually, simpler: The service returns the index. We just need to store it.

interface Props {
  onBack: () => void;
}

const TOTAL_ROUNDS = 10;

const SortingGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SortingLevel | null>(null);
  const [score, setScore] = useState(0);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [showResult, setShowResult] = useState(false); // New state for review phase

  // Session State
  const [round, setRound] = useState(1);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  // Store the fixed category index for this entire session (10 rounds)
  const [sessionLevelIndex, setSessionLevelIndex] = useState<number | null>(null);

  const startTimeRef = useRef<number>(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const timerIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    loadLevel();
    return () => stopTimer();
  }, []);

  const startTimer = () => {
    stopTimer();
    startTimeRef.current = Date.now();
    setElapsedTime(0);
    timerIntervalRef.current = setInterval(() => {
      setElapsedTime(Math.floor((Date.now() - startTimeRef.current) / 1000));
    }, 1000);
  };

  const stopTimer = () => {
    if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
  };

  const loadLevel = async () => {
    setLevel(null); 
    setLoading(true);
    setFeedback(null);
    setShowResult(false);

    // Get a category pair. 
    // If sessionLevelIndex is null (first round), the service will pick a random one.
    // If it's set, we pass it to ensure we get the SAME category pair.
    const result = await generateSortingLevel([], sessionLevelIndex);

    // If this is the first round, lock this category index for the rest of the session
    if (sessionLevelIndex === null) {
        setSessionLevelIndex(result.index);
    }

    // Pick only ONE random item from the set for this round
    // Note: Since we are reusing the category, items will eventually repeat within 10 rounds (as there are only ~6 items per category in static data).
    // This is expected behavior given the constraint of "same category type".
    const randomItem = result.level.items[Math.floor(Math.random() * result.level.items.length)];

    const singleItemLevel: SortingLevel = {
        ...result.level,
        items: [randomItem] // Only 1 item per round
    };

    setLevel(singleItemLevel);

    setLoading(false);
    startTimer();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    // Base 10 pts. Speed bonus: if < 3s, +10. if < 6s, +5.
    let bonus = 0;
    if (timeTaken < 3) bonus = 10;
    else if (timeTaken < 6) bonus = 5;
    return 10 + bonus;
  };

  const handleSort = (selectedCategory: 'A' | 'B') => {
    if (!level || showResult) return; // Prevent clicks during result phase

    const currentItem = level.items[0];
    const isCorrect = currentItem.category === selectedCategory;

    stopTimer();

    if (isCorrect) {
      const roundScore = calculateScore();
      setScore(s => s + roundScore);
      setFeedback('correct');
      soundService.playCorrect();
    } else {
      setFeedback('wrong');
      soundService.playWrong();
    }

    setShowResult(true); // Enable review mode
  };

  const handleNext = () => {
    if (round < TOTAL_ROUNDS) {
      setRound(r => r + 1);
      loadLevel();
    } else {
      setIsSessionFinished(true);
      soundService.playWin();
    }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setSessionLevelIndex(null); // Reset the fixed category so we get a new one next game
      setIsSessionFinished(false);
      // We need to trigger loadLevel via useEffect or manual call after state update.
      // Since setting state is async, we can just reload. 
      // However, loadLevel depends on sessionLevelIndex being null for a new random pick.
      // We pass explicit null here to override the current state which hasn't updated yet in this closure.
      // But actually, it's safer to just trigger a re-mount or force update logic. 
      // Calling loadLevel() directly here might use the old sessionLevelIndex state.
      // Let's rely on the state update to trigger a re-render if we were using useEffect on round, 
      // but we aren't. We'll manually reset and reload.

      // Temporary hack to ensure clean slate: reload with null explicitly
      setLoading(true);
      setFeedback(null);
      setShowResult(false);

      generateSortingLevel([], null).then(result => {
          setSessionLevelIndex(result.index);
           const randomItem = result.level.items[Math.floor(Math.random() * result.level.items.length)];
            const singleItemLevel: SortingLevel = {
                ...result.level,
                items: [randomItem]
            };
            setLevel(singleItemLevel);
            setLoading(false);
            startTimer();
      });
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-orange-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-orange-200">
              <Trophy className="w-20 h-20 text-orange-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-orange-900 mb-2">分類大師挑戰成功！</h2>
              <div className="text-6xl font-black text-orange-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的邏輯非常清晰！<br/>繼續保持這樣的好腦力。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-orange-500 text-white rounded-xl font-bold hover:bg-orange-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-orange-50">
        <Loader2 className="w-12 h-12 text-orange-500 animate-spin mb-4" />
        <p className="text-orange-700 text-lg">AI 正在準備題目中...</p>
      </div>
    );
  }

  const currentItem = level.items[0];
  const correctCategoryName = currentItem.category === 'A' ? level.categoryA : level.categoryB;

  return (
    <div className="flex flex-col h-screen bg-orange-50 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none p-2 sm:p-4 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-orange-800 shadow-sm hover:bg-orange-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex gap-4 items-center">
          <div className="px-3 py-1 bg-orange-100 rounded-full text-orange-800 font-bold text-sm md:text-base">
             第 {round} / {TOTAL_ROUNDS} 題
          </div>
          <div className="flex items-center text-orange-800 font-bold bg-orange-100 px-3 py-1 rounded-full text-sm md:text-base">
            <Trophy size={16} className="mr-2" />
            {score}
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-2 sm:p-4 w-full max-w-4xl mx-auto overflow-y-auto pb-32">

          <div className="flex flex-col sm:flex-row w-full gap-4 sm:gap-8 items-center h-full sm:max-h-[500px]">
            {/* Left: Card Display Area */}
            <div className="w-full sm:w-1/2 flex flex-col items-center justify-center h-full min-h-[200px]">

                <div className="relative w-full h-full max-h-[300px] aspect-[3/2] sm:aspect-square flex items-center justify-center perspective">
                    <div className={`
                        w-full h-full bg-white rounded-2xl shadow-xl flex flex-col items-center justify-center border-4 p-4 text-center
                        transition-all duration-300
                        ${feedback === 'correct' ? 'border-green-400 bg-green-50 scale-105' : ''}
                        ${feedback === 'wrong' ? 'border-red-400 bg-red-50' : 'border-white'}
                    `}>
                        <h3 className="text-4xl sm:text-6xl font-bold text-gray-800 mb-2 sm:mb-4 tracking-wider">
                            {currentItem.name}
                        </h3>

                        {/* Dynamic Text: Question or Result Review */}
                        {!showResult ? (
                            <p className="text-gray-500 text-sm sm:text-lg animate-pulse">這個屬於哪一類？</p>
                        ) : (
                            <div className="animate-fade-in-up">
                                <p className={`text-xl font-bold mb-2 ${feedback === 'correct' ? 'text-green-600' : 'text-red-500'}`}>
                                    {feedback === 'correct' ? '答對了！' : '答錯囉！'}
                                </p>
                                <p className="text-gray-600 text-sm sm:text-base">
                                    它是 <span className="font-bold text-orange-600 underline">{correctCategoryName}</span>
                                </p>
                            </div>
                        )}

                        {feedback === 'correct' && <ThumbsUp className="absolute top-4 right-4 text-green-500 w-12 h-12 opacity-80 animate-bounce" />}
                        {feedback === 'wrong' && <AlertCircle className="absolute top-4 right-4 text-red-500 w-12 h-12 opacity-80 animate-shake" />}
                    </div>
                </div>
            </div>

            {/* Right: Buttons / Controls */}
            <div className="w-full sm:w-1/2 flex flex-col gap-4 h-auto min-h-[150px] sm:h-auto justify-center">

                {/* When showing result, buttons reflect the answer */}
                <button
                    disabled={showResult}
                    onClick={() => handleSort('A')}
