                    {showResult && currentItem.category === 'A' && <CheckCircle className="absolute right-4 w-8 h-8 text-white"/>}
                </button>

                <button
                    disabled={showResult}
                    onClick={() => handleSort('B')}
                    className={`
                        flex-1 py-6 rounded-2xl shadow-md flex flex-col items-center justify-center transition-all border-4 relative
                        ${!showResult ? 'bg-green-100 hover:bg-green-200 text-green-900 border-green-200 active:scale-95' : ''}
