import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, ThumbsUp, AlertCircle, Trophy, ArrowRight, CheckCircle, XCircle, RotateCcw } from 'lucide-react';
import { SortingLevel } from '../types';
import { generateSortingLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
}

interface RoundHistory {
  round: number;
  itemName: string;
  categoryAName: string;
  categoryBName: string;
  correctCategory: 'A' | 'B';
  isCorrect: boolean;
}

const TOTAL_ROUNDS = 10;

const SortingGame: React.FC<Props> = ({ onBack }) => {
  const [level, setLevel] = useState<SortingLevel | null>(null);
  const [score, setScore] = useState(0);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [showResult, setShowResult] = useState(false); // Review phase state

  // Session State
  const [round, setRound] = useState(1);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  const [sessionLevelIndex, setSessionLevelIndex] = useState<number | null>(null);
  const [history, setHistory] = useState<RoundHistory[]>([]);

  const startTimeRef = useRef<number>(0);
  const [elapsedTime, setElapsedTime] = useState(0);
  const timerIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    loadLevel();
    return () => stopTimer();
  }, []);

  const startTimer = () => {
    stopTimer();
    startTimeRef.current = Date.now();
    setElapsedTime(0);
    timerIntervalRef.current = setInterval(() => {
      setElapsedTime(Math.floor((Date.now() - startTimeRef.current) / 1000));
    }, 1000);
  };

  const stopTimer = () => {
    if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
  };

  const loadLevel = async () => {
    setLevel(null); 
    setLoading(true);
    setFeedback(null);
    setShowResult(false);

    // Generate level logic...
    const result = await generateSortingLevel([], sessionLevelIndex);

    if (sessionLevelIndex === null) {
        setSessionLevelIndex(result.index);
    }

    const randomItem = result.level.items[Math.floor(Math.random() * result.level.items.length)];

    const singleItemLevel: SortingLevel = {
        ...result.level,
        items: [randomItem]
    };

    setLevel(singleItemLevel);
    setLoading(false);
    startTimer();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    let bonus = 0;
    if (timeTaken < 3) bonus = 10;
    else if (timeTaken < 6) bonus = 5;
    return 10 + bonus;
  };

  const handleSort = (selectedCategory: 'A' | 'B') => {
    if (!level || showResult) return;

    const currentItem = level.items[0];
    const isCorrect = currentItem.category === selectedCategory;

    stopTimer();

    if (isCorrect) {
      const roundScore = calculateScore();
      setScore(s => s + roundScore);
      setFeedback('correct');
      soundService.playCorrect();
    } else {
      setFeedback('wrong');
      soundService.playWrong();
    }

    // Record History
    setHistory(prev => [
      ...prev,
      {
        round: round,
        itemName: currentItem.name,
        categoryAName: level.categoryA,
        categoryBName: level.categoryB,
        correctCategory: currentItem.category,
        isCorrect: isCorrect
      }
    ]);

    setShowResult(true);
  };

  const handleNext = () => {
    if (round < TOTAL_ROUNDS) {
      setRound(r => r + 1);
      loadLevel();
    } else {
      setIsSessionFinished(true);
      soundService.playWin();
    }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setSessionLevelIndex(null);
      setHistory([]);
      setIsSessionFinished(false);

      setLoading(true);
      setFeedback(null);
      setShowResult(false);

      generateSortingLevel([], null).then(result => {
          setSessionLevelIndex(result.index);
           const randomItem = result.level.items[Math.floor(Math.random() * result.level.items.length)];
            const singleItemLevel: SortingLevel = {
                ...result.level,
                items: [randomItem]
            };
            setLevel(singleItemLevel);
            setLoading(false);
            startTimer();
      });
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col h-screen bg-orange-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-4 flex justify-between items-center bg-white shadow-sm z-10">
            <h2 className="text-xl font-bold text-orange-800 flex items-center">
                <Trophy className="mr-2 text-orange-500" /> 挑戰完成
            </h2>
            <div className="text-2xl font-black text-orange-600">{score} 分</div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
            <div className="bg-white p-6 rounded-2xl shadow-md text-center border-b-4 border-orange-200">
                <p className="text-gray-600 mb-2">太棒了！你的分類能力非常好。</p>
                <div className="text-sm text-gray-500">以下是你的答題紀錄：</div>
            </div>

            <div className="space-y-3 pb-20">
                {history.map((record, idx) => (
                    <div key={idx} className="bg-white p-4 rounded-xl shadow-sm flex items-center justify-between border-l-4 border-orange-300">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${record.isCorrect ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                                {record.isCorrect ? <CheckCircle size={18} /> : <XCircle size={18} />}
                            </div>
                            <div>
                                <div className="font-bold text-gray-800 text-lg">{record.itemName}</div>
                                <div className="text-sm text-gray-500">
                                    正確分類：
                                    <span className="font-medium text-orange-700">
                                        {record.correctCategory === 'A' ? record.categoryAName : record.categoryBName}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>

        {/* Bottom Actions */}
        <div className="flex-none p-4 bg-white border-t border-orange-100 flex gap-4">
            <button 
                onClick={onBack}
                className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300 transition-colors"
            >
                回主選單
            </button>
            <button 
                onClick={handleRestart}
                className="flex-1 py-3 bg-orange-500 text-white rounded-xl font-bold hover:bg-orange-600 shadow-lg flex items-center justify-center gap-2 transition-colors"
            >
                <RotateCcw size={20} /> 再玩一次
            </button>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-orange-50">
        <Loader2 className="w-12 h-12 text-orange-500 animate-spin mb-4" />
        <p className="text-orange-700 text-lg">AI 正在準備題目中...</p>
      </div>
    );
  }

  const currentItem = level.items[0];
  const correctCategoryName = currentItem.category === 'A' ? level.categoryA : level.categoryB;

  return (
    <div className="flex flex-col h-screen bg-orange-50 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none p-2 sm:p-4 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
