            </h2>
            <div className="text-2xl font-black text-orange-600">{score} 分</div>
        </div>

        {/* Scrollable Content - List all items */}
        <div className="flex-1 overflow-y-auto p-4">
            <div className="max-w-2xl mx-auto space-y-4 pb-24">
