import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Footprints, X } from 'lucide-react';
import { MemoryCard, Difficulty } from '../types';
import { generateEncouragement } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

// Extended Emoji Pool for ~20 distinct themes/variations
// We will pick 8 random unique emojis from this list every game to ensure variety.
const EMOJIS = [
    // Animals
    '🐶', '🐱', '🐭', '🐹', '🐰', '🦊', '🐻', '🐼', '🐨', '🐯', '🦁', '🐮', '🐷', '🐸', '🐵', '🐔',
    // Fruits & Food
    '🍎', '🍐', '🍊', '🍋', '🍌', '🍉', '🍇', '🍓', '🍒', '🍑', '🍍', '🥥', '🥝', '🍅', '🥑', '🍔', '🍕', '🍩', '🍦', '🍰',
    // Nature & Weather
    '🌵', '🌲', '🌳', '🌴', '🌻', '🌼', '🌷', '🌹', '🍀', '🍁', '🍄', '☀️', '🌤️', '🌈', '⚡', '❄️', '🔥', '💧',
    // Vehicles
    '🚗', '🚕', '🚙', '🚌', '🚎', '🏎️', '🚓', '🚑', '🚒', '🚐', '🚚', '🚜', '🛵', '🚲', '🚂', '✈️', '🚀', '🚁',
    // Sports & Activities
    '⚽', '🏀', '🏈', '⚾', '🥎', '🎾', '🏐', '🏉', '🎱', '🏓', '🏸', '🥊', '🥋', '⛳', '⛸️', '🎣', '🎨', '🎬',
    // Objects
    '⌚', '📱', '💻', '📷', '💡', '🔦', '📕', '✏️', '🗝️', '🎁', '🎈', '🎉', '🧸', '👑', '💎', '🔔', '🚪', '🪑'
];

const MemoryGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [cards, setCards] = useState<MemoryCard[]>([]);
  const [flippedIndices, setFlippedIndices] = useState<number[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isWon, setIsWon] = useState(false);
  const [moves, setMoves] = useState(0);
  const [encouragement, setEncouragement] = useState("");
  const [isMismatchWaiting, setIsMismatchWaiting] = useState(false);

  const initializeGame = () => {
    // For Advanced: Maybe select emojis from same category to make it harder?
    // For now, random picking is challenging enough for 4x4.

    // 1. Pick 8 random unique emojis from the large pool
    const selectedEmojis: string[] = [];
    const pool = [...EMOJIS];

    while (selectedEmojis.length < 8) {
        if (pool.length === 0) break;
        const randomIndex = Math.floor(Math.random() * pool.length);
        selectedEmojis.push(pool[randomIndex]);
        pool.splice(randomIndex, 1); // remove to ensure uniqueness
    }

    // 2. Create pairs
    const gameItems = [...selectedEmojis, ...selectedEmojis];

    // 3. Shuffle
    for (let i = gameItems.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [gameItems[i], gameItems[j]] = [gameItems[j], gameItems[i]];
    }

    setCards(gameItems.map((emoji, index) => ({
      id: index,
      content: emoji,
      isFlipped: false,
      isMatched: false
    })));
    setFlippedIndices([]);
    setIsWon(false);
    setMoves(0);
    setEncouragement("");
    setIsMismatchWaiting(false);
    setIsProcessing(false);
  };

  useEffect(() => {
    initializeGame();
  }, []);

  const handleCardClick = (index: number) => {
    // Block clicks if processing, already flipped/matched, OR if waiting for manual reset
    if (isProcessing || isMismatchWaiting || cards[index].isFlipped || cards[index].isMatched) return;

    const newCards = [...cards];
    newCards[index].isFlipped = true;
    setCards(newCards);

    const newFlipped = [...flippedIndices, index];
    setFlippedIndices(newFlipped);

    if (newFlipped.length === 2) {
      setIsProcessing(true);
      setMoves(m => m + 1);

      const [firstIndex, secondIndex] = newFlipped;

      if (newCards[firstIndex].content === newCards[secondIndex].content) {
        // Match found - Auto proceed
        soundService.playCorrect(); // Sound for match
        setTimeout(() => {
          newCards[firstIndex].isMatched = true;
          newCards[secondIndex].isMatched = true;
          setCards(newCards);
          setFlippedIndices([]);
          setIsProcessing(false);

          if (newCards.every(c => c.isMatched)) {
            handleWin();
          }
        }, 500);
      } else {
        // No match - Wait for manual reset
        soundService.playWrong(); // Sound for mismatch
        setIsMismatchWaiting(true);
        setIsProcessing(false); 
      }
    }
  };

  const handleManualReset = () => {
    const newCards = [...cards];
    // Flip back the currently flipped cards that aren't matched
    flippedIndices.forEach(idx => {
        newCards[idx].isFlipped = false;
    });
    setCards(newCards);
    setFlippedIndices([]);
    setIsMismatchWaiting(false);
  };

  const handleWin = async () => {
    setIsWon(true);
    soundService.playWin(); // Sound for win
    const msg = await generateEncouragement(100);
    setEncouragement(msg);
  };

  return (
    <div className="flex flex-col h-screen bg-indigo-50 overflow-hidden relative">
        {/* Header */}
      <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10">
        <button 
          onClick={onBack}
          className="p-2 bg-gray-100 rounded-full text-indigo-600 hover:bg-indigo-100"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-2">
            {difficulty === 'ADVANCED' && <span className="bg-indigo-600 text-white px-2 py-1 rounded text-xs">進階</span>}
            <div className="flex items-center bg-indigo-100 px-4 py-1 rounded-full text-indigo-800 font-bold">
                <Footprints className="w-4 h-4 mr-2" />
                步數: {moves}
            </div>
        </div>
        <button 
          onClick={initializeGame}
          className="p-2 bg-gray-100 rounded-full text-indigo-600 hover:bg-indigo-100"
        >
          <RefreshCw size={20} />
        </button>
      </div>

      {/* Main Content: Flex Row on landscape, Flex Col on portrait */}
      <div className="flex-1 flex flex-col sm:flex-row overflow-hidden relative">

        {/* Game Area - Centered & Scrollable */}
        <div className="flex-1 flex items-center justify-center p-2 overflow-y-auto">
            <div className="relative">
                {/* Column Labels (A-D) */}
                <div className="flex mb-1 pl-8">
                    {['A', 'B', 'C', 'D'].map(label => (
                        <div key={label} className="flex-1 text-center font-bold text-indigo-400 text-lg md:text-xl">
                            {label}
                        </div>
                    ))}
                </div>

                <div className="flex">
                    {/* Row Labels (1-4) */}
                    <div className="flex flex-col w-8 justify-around pr-2">
                        {[1, 2, 3, 4].map(label => (
                            <div key={label} className="flex-1 flex items-center justify-center font-bold text-indigo-400 text-lg md:text-xl">
                                {label}
                            </div>
                        ))}
                    </div>

                    {/* Grid - Adjusted for landscape (limit height) */}
                    <div className="grid grid-cols-4 gap-2 md:gap-3 
                        w-[80vw] max-w-[400px] aspect-square
                        sm:h-[75vh] sm:w-[75vh] sm:max-w-none sm:max-h-none
                    ">
                        {cards.map((card, index) => (
                        <div
                            key={card.id}
                            onClick={() => handleCardClick(index)}
                            className={`relative cursor-pointer perspective-1000 w-full h-full`}
                        >
                            {/* Card Inner */}
                            <div className={`
                                w-full h-full absolute inset-0
                                transition-all duration-500 transform
                                flex items-center justify-center
                                border-2 rounded-lg md:rounded-xl shadow-md
                                text-3xl md:text-5xl select-none
                                ${card.isFlipped || card.isMatched 
                                    ? 'bg-white border-indigo-400 rotate-y-180' 
                                    : 'bg-indigo-300 border-indigo-300'}
                                ${isMismatchWaiting && card.isFlipped && !card.isMatched ? 'border-red-400 ring-2 ring-red-200' : ''}
                            `}>
                                {/* We use a fixed container for the emoji to prevent layout shifts */}
                                <div className="w-full h-full flex items-center justify-center backface-hidden">
                                    {(card.isFlipped || card.isMatched) ? card.content : ''}
                                </div>
                            </div>
                        </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Side Panel / Overlay Action Area (For Reset Button) 
            Use Absolute positioning to prevent layout shifts on the grid.
        */}
        {isMismatchWaiting && (
            <div className="absolute inset-x-0 bottom-4 flex justify-center z-20 pointer-events-none sm:inset-y-0 sm:right-4 sm:left-auto sm:bottom-auto sm:top-1/2 sm:-translate-y-1/2">
                <div className="pointer-events-auto bg-white/90 backdrop-blur-sm p-4 rounded-2xl shadow-xl border border-indigo-100 flex flex-row sm:flex-col items-center gap-4 animate-fade-in-up">
                    <div className="text-center text-gray-600 font-bold whitespace-nowrap">
                        沒配對成功<br className="hidden sm:block"/>請記住位置
                    </div>
                    <button 
                        onClick={handleManualReset}
                        className="bg-indigo-600 text-white text-lg font-bold px-6 py-2 rounded-xl shadow-md hover:bg-indigo-700 animate-pulse flex items-center whitespace-nowrap"
                    >
                        <RefreshCw className="mr-2 w-5 h-5" />
                        蓋上卡片
                    </button>
                </div>
            </div>
        )}

      </div>

      {isWon && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl p-6 md:p-8 max-w-sm w-full text-center shadow-2xl animate-bounce-short">
            <Trophy className="w-16 h-16 md:w-20 md:h-20 text-yellow-400 mx-auto mb-4" />
            <h3 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">恭喜完成！</h3>
            <p className="text-gray-500 mb-6">{encouragement || "很棒！大腦活化成功。"}</p>

            <div className="bg-indigo-50 rounded-xl p-4 mb-6 border-2 border-indigo-100">
                <p className="text-indigo-900 font-medium mb-1 text-sm">本次使用總步數</p>
                <div className="text-4xl md:text-6xl font-black text-indigo-600 flex items-center justify-center">
                    {moves}
                    <span className="text-xl md:text-2xl ml-2 font-normal text-indigo-400">步</span>
                </div>
            </div>

            <button
              onClick={initializeGame}
              className="w-full py-3 bg-indigo-600 text-white rounded-xl font-semibold hover:bg-indigo-700 transition-colors shadow-lg"
            >
              再挑戰一次
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default MemoryGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, RotateCcw, Check, XCircle, Trophy, Send, Eye, ArrowRight } from 'lucide-react';
import { SentenceLevel, Difficulty } from '../types';
import { generateSentenceLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const SentenceGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<SentenceLevel | null>(null);
  const [userAnswer, setUserAnswer] = useState<{id: string, text: string}[]>([]);
  const [availableWords, setAvailableWords] = useState<{id: string, text: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCorrect, setIsCorrect] = useState(false);
  const [showError, setShowError] = useState(false);

  // Session & Scoring
  const [round, setRound] = useState(1);
  const [totalScore, setTotalScore] = useState(0);
  const [isSessionFinished, setIsSessionFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startNewRound();
  }, []);

  const startNewRound = async () => {
    setLoading(true);
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);

    const data = await generateSentenceLevel(difficulty);
    setLevel(data);
    setAvailableWords(data.scrambled);

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTimeRef.current) / 1000;
    // Base 20 pts. Speed bonus: if < 5s, +10. if < 10s, +5.
    let bonus = 0;
    if (timeTaken < 5) bonus = 10;
    else if (timeTaken < 10) bonus = 5;
    return 20 + bonus;
  };

  const handleSelectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setUserAnswer([...userAnswer, word]);
    setAvailableWords(availableWords.filter(w => w.id !== word.id));
  };

  const handleDeselectWord = (word: {id: string, text: string}) => {
    if (isCorrect) return;
    setShowError(false);
    setAvailableWords([...availableWords, word]);
    setUserAnswer(userAnswer.filter(w => w.id !== word.id));
  };

  const handleNextLevel = () => {
    if (round < TOTAL_ROUNDS) {
        setRound(r => r + 1);
        startNewRound();
     } else {
        setIsSessionFinished(true);
        soundService.playWin(); // Win sound for session completion
     }
  };

  const checkAnswer = () => {
    if (!level) return;

    // If already correct, the button acts as "Next Level"
    if (isCorrect) {
        handleNextLevel();
        return;
    }

    const currentString = userAnswer.map(w => w.text).join('');
    if (currentString === level.original) {
        // Correct
        const roundScore = calculateScore();
        setTotalScore(s => s + roundScore);
        setIsCorrect(true);
        soundService.playCorrect();
    } else {
        // Wrong (No penalty)
        setShowError(true);
        soundService.playWrong();
        setTimeout(() => setShowError(false), 2000);
    }
  };

  const handleShowAnswer = () => {
    if (!level || isCorrect) return;

    // Combine all words
    const allWords = [...userAnswer, ...availableWords];
    // Sort based on ID (which is index-char, e.g., "0-早")
    allWords.sort((a, b) => {
        const indexA = parseInt(a.id.split('-')[0]);
        const indexB = parseInt(b.id.split('-')[0]);
        return indexA - indexB;
    });

    setUserAnswer(allWords);
    setAvailableWords([]);
    setIsCorrect(true);
    // Do NOT add score
    soundService.playCorrect(); // Still play correct sound
  };

  const resetCurrent = () => {
    if (!level) return;
    setIsCorrect(false);
    setShowError(false);
    setUserAnswer([]);
    setAvailableWords(level.scrambled);
  }

  const handleRestart = () => {
      setRound(1);
      setTotalScore(0);
      setIsSessionFinished(false);
      startNewRound();
  };

  if (isSessionFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[100dvh] bg-pink-50 p-4 animate-fade-in overflow-y-auto">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200 my-4">
              <Trophy className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">練習完成！</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{totalScore}</div>
              <p className="text-gray-600 mb-8">
                  你的造句能力很棒！<br/>邏輯非常清晰。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
}

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[100dvh] bg-pink-50">
        <Loader2 className="w-12 h-12 text-pink-500 animate-spin mb-4" />
        <p className="text-pink-700">準備句子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[100dvh] bg-pink-50 overflow-hidden">
      {/* Header - Compact */}
      <div className="flex-none px-4 py-1 sm:py-2 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-pink-800 shadow-sm hover:bg-pink-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
            {difficulty === 'ADVANCED' && <span className="bg-pink-600 text-white px-2 py-1 rounded text-xs">進階</span>}
             <div className="px-3 py-1 bg-pink-100 rounded-full text-pink-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-pink-100 px-3 py-1 rounded-full text-pink-800 font-bold">
                <Trophy size={16} className="mr-2"/> {totalScore}
             </div>
        </div>
        <button onClick={startNewRound} className="px-3 py-1 bg-white rounded-full text-pink-600 text-sm font-medium hover:bg-pink-100 shadow-sm">
            跳過
        </button>
      </div>

      {/* Main Layout: Flex Column */}
      <div className="flex-1 flex flex-col items-center p-1 sm:p-2 max-w-4xl mx-auto w-full gap-1 sm:gap-2 relative overflow-hidden">

        {/* Error Toast */}
        {showError && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 animate-bounce-short z-50 bg-red-100 border-2 border-red-400 text-red-700 px-6 py-3 rounded-full flex items-center shadow-lg whitespace-nowrap">
                <XCircle className="w-6 h-6 mr-2" />
                <span className="font-bold">順序不對喔，再試試看！</span>
            </div>
        )}

        {/* TOP: Answer Area - Reduced Height */}
        <div className="w-full flex-none flex flex-col items-center justify-center bg-white/40 rounded-xl p-1 sm:p-2">
             {/* Hide label on mobile to save vertical space */}
             <p className="text-gray-500 mb-1 text-sm self-start pl-2 hidden sm:block">請組成通順的句子：</p>
             <div className={`
                w-full min-h-[3rem] sm:min-h-[4rem]
                bg-white rounded-xl shadow-inner p-1 sm:p-2 
                flex flex-nowrap items-center gap-2 overflow-x-auto
                border-4 transition-colors duration-300 
                ${isCorrect ? 'border-green-400 bg-green-50' : showError ? 'border-red-300 bg-red-50' : 'border-pink-200'}
             `}>
                {userAnswer.length === 0 && !isCorrect && (
                   <span className="text-gray-300 text-base sm:text-lg w-full text-center">答案區</span>
                )}
                {userAnswer.map(word => (
                    <button 
                        key={word.id} 
                        onClick={() => handleDeselectWord(word)}
                        className="flex-shrink-0 bg-pink-500 text-white text-lg sm:text-2xl font-bold px-3 py-1 sm:px-4 sm:py-2 rounded-lg shadow-md hover:bg-pink-600 transition-all animate-fade-in"
                    >
                        {word.text}
                    </button>
                ))}
                {isCorrect && <Check className="text-green-500 w-8 h-8 sm:w-10 sm:h-10 ml-2 animate-bounce flex-shrink-0"/>}
             </div>
        </div>

        {/* BOTTOM: Source Words & Controls - Use full remaining height */}
        <div className="flex-1 w-full relative min-h-0 bg-white/30 rounded-2xl border border-pink-100 overflow-hidden">

            {/* Scrollable Word List - Absolute fill with padding at bottom for floating buttons */}
            <div className="absolute inset-0 overflow-y-auto content-start p-2 pb-20">
                <div className="flex flex-wrap gap-2 justify-center pt-2">
                    {availableWords.map(word => (
                        <button 
                            key={word.id} 
                            onClick={() => handleSelectWord(word)}
                            className="bg-white text-pink-700 text-lg sm:text-2xl font-bold px-4 py-2 sm:px-5 sm:py-3 rounded-lg sm:rounded-xl shadow border-2 border-pink-100 hover:border-pink-300 active:scale-95 transition-all"
                        >
                            {word.text}
                        </button>
                    ))}
                </div>
            </div>

            {/* Controls - Floating Buttons */}

            {/* Left Group: Show Answer & Reset */}
            <div className="absolute bottom-3 left-3 flex gap-2 z-20">
                 <button 
                    onClick={handleShowAnswer}
                    disabled={isCorrect}
                    className="flex items-center justify-center p-3 sm:px-4 sm:py-2 bg-yellow-100/90 backdrop-blur-sm text-yellow-700 rounded-full shadow-lg border border-yellow-200 hover:bg-yellow-200 transition disabled:opacity-50 active:scale-95"
                    title="看答案 (不計分)"
                >
                    <Eye size={20} />
                    <span className="ml-1 text-sm font-bold hidden sm:inline">看答案</span>
                </button>

                <button 
                    onClick={resetCurrent}
                    disabled={isCorrect}
                    className="flex items-center justify-center p-3 sm:px-4 sm:py-2 bg-gray-100/90 backdrop-blur-sm text-gray-600 rounded-full shadow-lg border border-gray-200 hover:bg-gray-200 transition disabled:opacity-50 active:scale-95"
                >
                    <RotateCcw size={20} />
                    <span className="ml-1 text-sm font-bold hidden sm:inline">重置</span>
                </button>
            </div>

            {/* Confirm: Bottom Right */}
            <button 
                onClick={checkAnswer}
                disabled={userAnswer.length === 0 && !isCorrect}
                className={`
                    absolute bottom-3 right-3 flex items-center justify-center py-3 px-5 
                    backdrop-blur-sm text-white rounded-full font-bold shadow-xl 
                    transition z-20 active:scale-95
                    disabled:opacity-50 disabled:cursor-not-allowed
                    ${isCorrect ? 'bg-green-500 hover:bg-green-600' : 'bg-pink-500/95 hover:bg-pink-600'}
                `}
            >
                <span className="mr-1 text-sm sm:text-base">{isCorrect ? "下一題" : "確認"}</span>
                {isCorrect ? <ArrowRight size={18} /> : <Send size={18} />}
            </button>

        </div>

      </div>
    </div>
  );
};

