  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 160) return { title: "同理心大師！", desc: "你能精準且快速地感受到他人的情緒！" };
      if (finalScore >= 100) return { title: "很棒的觀察！", desc: "對情緒的觀察很敏銳喔。" };
      return { title: "再接再厲！", desc: "試著多想想別人的感受喔。" };
