import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Sun, CheckCircle } from 'lucide-react';
import { ShadowLevel, Difficulty } from '../types';
import { generateShadowLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const ShadowGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<ShadowLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongIndex, setWrongIndex] = useState<number | null>(null);
  const [showErrorMsg, setShowErrorMsg] = useState(false);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setWrongIndex(null);
    setShowErrorMsg(false);
    const data = await generateShadowLevel(difficulty as Difficulty);
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let bonus = 0;
      if (timeTaken < 5) bonus = 10;
      else if (timeTaken < 10) bonus = 5;
      return 20 + bonus;
  }

  const handleOptionClick = (idx: number) => {
    if (!level || feedback === 'correct') return;

    if (idx === level.correctIndex) {
      const roundScore = calculateScore();
      setScore(s => s + roundScore);
      setFeedback('correct');
      soundService.playCorrect();
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
        } else {
          setIsFinished(true);
          soundService.playWin();
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      setWrongIndex(idx);
      setShowErrorMsg(true);
      soundService.playWrong();
      setTimeout(() => {
        setFeedback(null);
        setWrongIndex(null);
        setShowErrorMsg(false);
      }, 1000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-slate-300">
              <Sun className="w-20 h-20 text-slate-800 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-slate-900 mb-2">觀察入微！</h2>
              <div className="text-6xl font-black text-slate-700 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  你的視覺辨識能力很強！<br/>完全難不倒你。
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-slate-800 text-white rounded-xl font-bold hover:bg-slate-700 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50">
        <Loader2 className="w-12 h-12 text-slate-600 animate-spin mb-4" />
        <p className="text-slate-800">準備影子中...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-100 overflow-hidden relative">
      {/* Header */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-slate-800 shadow-sm hover:bg-slate-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
            {difficulty === 'ADVANCED' && <span className="bg-slate-600 text-white px-2 py-1 rounded text-xs">進階</span>}
             <div className="px-3 py-1 bg-slate-200 rounded-full text-slate-800 font-bold text-sm">
                第 {round} / {TOTAL_ROUNDS} 題
             </div>
             <div className="flex items-center bg-slate-200 px-3 py-1 rounded-full text-slate-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      {/* Main Content: Flex-col on portrait, Flex-row on landscape/large screens */}
      <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 sm:p-4 max-w-4xl mx-auto w-full gap-4 md:gap-8 overflow-hidden">

        {/* Target Area */}
        <div className="flex-none sm:flex-1 bg-white p-4 md:p-8 rounded-[2rem] shadow-xl border-4 border-white ring-4 ring-slate-200 flex flex-col items-center justify-center h-auto sm:h-auto w-full sm:w-auto max-h-[40vh] sm:max-h-none">
             <div className="text-7xl sm:text-8xl md:text-9xl filter drop-shadow-lg mb-2 animate-bounce-short">
                 {level.target}
             </div>
             <p className="text-slate-500 font-bold text-base md:text-lg">它的影子是哪一個？</p>
        </div>

        {/* Options Area - 2x2 Grid */}
        <div className="flex-none sm:flex-1 w-full sm:w-auto max-w-md aspect-square max-h-[50vh] sm:max-h-none">
            <div className="grid grid-cols-2 gap-3 sm:gap-4 w-full h-full">
                {level.options.map((opt, idx) => (
                    <button
                        key={idx}
                        onClick={() => handleOptionClick(idx)}
                        className={`
                            w-full h-full rounded-2xl flex flex-col items-center justify-center relative transition-all duration-200 p-2 border-2
                            ${feedback === 'correct' && idx === level.correctIndex ? 'bg-green-100 border-green-500 scale-105 z-10' : ''}
                            ${feedback === 'wrong' && idx === wrongIndex ? 'bg-red-100 border-red-400 shake' : 'border-transparent'}
                            ${!feedback || (feedback === 'wrong' && idx !== wrongIndex) ? 'bg-white shadow-md hover:bg-slate-50 hover:shadow-xl hover:-translate-y-1' : ''}
                        `}
                        disabled={feedback === 'correct'}
                    >
                        {/* Number label */}
                        <div className="absolute top-2 left-3 text-slate-400 font-bold text-lg md:text-xl">
                            {idx + 1}
                        </div>

                        {/* Render the emoji as a black silhouette */}
                        <span 
                            className="transition-all duration-500 text-5xl sm:text-6xl md:text-7xl mb-1"
                            style={{ 
                                filter: feedback === 'correct' && idx === level.correctIndex ? 'none' : 'brightness(0)',
                                opacity: feedback === 'correct' && idx === level.correctIndex ? 1 : 0.7 
                            }}
                        >
                            {opt}
                        </span>

                        {/* Overlay Success Icon */}
                        {feedback === 'correct' && idx === level.correctIndex && (
                            <div className="absolute -top-2 -right-2 bg-white rounded-full">
                                <CheckCircle className="text-green-500 w-8 h-8" />
                            </div>
                        )}
                    </button>
                ))}
            </div>
        </div>

        {/* Error Feedback Text (Fixed Position) */}
        {showErrorMsg && (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-red-100 text-red-600 px-8 py-4 rounded-2xl font-bold shadow-2xl animate-bounce-short text-xl whitespace-nowrap z-50 border-2 border-red-200 pointer-events-none">
                再看清楚一點喔！
            </div>
        )}

      </div>
    </div>
  );
};

export default ShadowGame;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Clock, CheckCircle } from 'lucide-react';
import { StroopLevel, Difficulty } from '../types';
import { generateStroopLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const StroopGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<StroopLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [streak, setStreak] = useState(0);
  const [isFinished, setIsFinished] = useState(false);

  // Feedback States
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  // Timer for scoring
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    const data = await generateStroopLevel(difficulty as Difficulty);
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const handleAnswer = (answer: string) => {
      if (!level || feedback !== null) return; // Prevent double clicks

      const isCorrect = answer === level.colorName;

      if (isCorrect) {
          const timeTaken = (Date.now() - startTimeRef.current) / 1000;

          // Scoring logic: Faster is better
          // Advanced mode expects faster reactions
          let points = 10;
          if (difficulty === 'ADVANCED') {
             if (timeTaken < 1.5) points += 10;
             else if (timeTaken < 3) points += 5;
          } else {
             if (timeTaken < 2) points += 10;
             else if (timeTaken < 4) points += 5;
          }

          // Streak bonus
          const finalScore = points + (streak * 2);

          setScore(s => s + finalScore);
          setStreak(s => s + 1);
          setFeedback('correct');
          soundService.playCorrect();
      } else {
          setStreak(0);
          setFeedback('wrong');
          soundService.playWrong();
      }

      // Delay then next
      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
            setRound(r => r + 1);
            startRound();
        } else {
            setIsFinished(true);
            soundService.playWin();
        }
      }, 1000); 
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setStreak(0);
      setIsFinished(false);
      startRound();
  }

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      const threshold = difficulty === 'ADVANCED' ? 200 : 180;
      if (finalScore >= threshold) return { title: "反應神速！", desc: "你的大腦處理速度非常驚人！" };
      if (finalScore >= (threshold * 0.6)) return { title: "表現優異！", desc: "你的專注力保持得很好喔。" };
      return { title: "再接再厲！", desc: "慢慢練習，準確度最重要。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-rose-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-rose-200">
              <Trophy className="w-20 h-20 text-rose-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-rose-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-rose-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button 
                      onClick={onBack}
                      className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300"
                  >
                      回主選單
                  </button>
                  <button 
                      onClick={handleRestart}
                      className="flex-1 py-3 bg-rose-500 text-white rounded-xl font-bold hover:bg-rose-600 shadow-lg"
                  >
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-rose-50 flex items-center justify-center"><Loader2 className="animate-spin text-rose-500"/></div>;
  }

  return (
    <div className={`flex flex-col h-screen overflow-hidden transition-colors duration-300 ${feedback === 'wrong' ? 'bg-red-50' : 'bg-rose-50'}`}>
       {/* Header */}
       <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-rose-800 shadow-sm hover:bg-rose-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                {difficulty === 'ADVANCED' && <span className="bg-rose-600 text-white px-2 py-1 rounded text-xs">進階</span>}
                <div className="text-rose-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-rose-100 px-3 py-1 rounded-full text-rose-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        {/* Main Content - Allow scrolling if height is small (landscape) */}
        <div className="flex-1 overflow-y-auto p-4">
            <div className="flex flex-col sm:flex-row items-center justify-center gap-4 sm:gap-8 min-h-full">

                {/* Left Side: Question */}
                <div className="flex-none flex flex-col items-center justify-center max-w-sm">
                    <p className="text-gray-500 text-lg mb-2 text-center shrink-0">
                        請回答這個字的 <span className="font-bold text-black underline decoration-rose-500 decoration-4">顏色</span>
                    </p>

                    {/* The Stroop Word - Responsive Sizing */}
                    <div className="bg-white rounded-3xl shadow-xl border-4 border-rose-100 w-56 h-56 sm:w-72 sm:h-72 flex items-center justify-center relative shrink-0">
                        <span className={`text-7xl sm:text-9xl font-black ${level.colorCode}`}>
                            {level.text}
                        </span>

                        {/* Feedback Overlay */}
                        {feedback === 'correct' && (
                            <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                                <div className="text-green-600 flex flex-col items-center">
                                    <CheckCircle className="w-16 h-16 mb-2" />
                                    <span className="text-3xl font-bold">答對了！</span>
                                </div>
                            </div>
                        )}
                        {feedback === 'wrong' && (
                             <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-2xl animate-fade-in z-20">
                                <div className="text-red-500 flex flex-col items-center">
                                    <span className="text-3xl font-bold">看錯囉！</span>
                                    <span className="text-xl mt-2">是 {level.colorName} 色</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Right Side: Options - Responsive Grid */}
                <div className="flex-none w-full max-w-sm grid grid-cols-3 gap-3 sm:gap-4 content-center">
                    {level.options.map((opt, idx) => (
                        <button
                            key={idx}
                            onClick={() => handleAnswer(opt)}
                            disabled={feedback !== null}
                            className="py-3 sm:py-4 bg-white border-2 border-rose-200 rounded-xl text-xl sm:text-2xl font-bold text-gray-700 shadow-md hover:bg-rose-100 active:scale-95 transition-all disabled:opacity-50 h-20 sm:h-24 flex items-center justify-center"
                        >
                            {opt}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    </div>
  );
};

export default StroopGame;

