import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, Heart } from 'lucide-react';
import { EmotionLevel, Difficulty } from '../types';
import { generateEmotionLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const EmotionGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<EmotionLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongOption, setWrongOption] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [hasWrongAttempt, setHasWrongAttempt] = useState(false);

  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setWrongOption(null);
    setErrorMsg(null);
    setHasWrongAttempt(false);

    const data = await generateEmotionLevel(difficulty as Difficulty);
    setLevel(data);
    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const calculateScore = () => {
      // If user has made a wrong attempt on this question, score is 0
      if (hasWrongAttempt) return 0;

      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let points = 10; // Base score

      // Speed bonus
      if (timeTaken < 3) points += 10;      // Super fast
      else if (timeTaken < 6) points += 5;  // Fast

      return points;
  }

  const handleOptionClick = (option: string) => {
      if (!level || feedback === 'correct') return;

      if (option === level.correctAnswer) {
          const points = calculateScore();
          setScore(s => s + points);
          setFeedback('correct');
          setErrorMsg(null);
          soundService.playCorrect();

          setTimeout(() => {
              if (round < TOTAL_ROUNDS) {
                  setRound(r => r + 1);
                  startRound();
              } else {
                  setIsFinished(true);
                  soundService.playWin();
              }
          }, 1500);
      } else {
          setHasWrongAttempt(true);
          setFeedback('wrong');
          setWrongOption(option);
          setErrorMsg("再想想看！");
          soundService.playWrong();

          setTimeout(() => {
              setFeedback(null);
              setWrongOption(null);
              setErrorMsg(null);
          }, 1500);
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 160) return { title: "同理心大師！", desc: "你能精準且快速地感受到他人的情緒！" };
      if (finalScore >= 100) return { title: "很棒的觀察！", desc: "對情緒的觀察很敏銳喔。" };
      return { title: "再接再厲！", desc: "試著多想想別人的感受喔。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-pink-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-pink-200">
              <Heart className="w-20 h-20 text-pink-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-pink-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-pink-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-pink-500 text-white rounded-xl font-bold hover:bg-pink-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-pink-50 flex items-center justify-center"><Loader2 className="animate-spin text-pink-500"/></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-pink-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-pink-800 shadow-sm hover:bg-pink-100">
          <ArrowLeft size={20} />
        </button>
        <div className="flex items-center gap-4">
            {difficulty === 'ADVANCED' && <span className="bg-pink-600 text-white px-2 py-1 rounded text-xs">進階</span>}
            <div className="text-pink-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
             <div className="flex items-center bg-pink-100 px-3 py-1 rounded-full text-pink-800 font-bold">
                <Trophy size={16} className="mr-2"/> {score}
             </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-4 gap-6 max-w-5xl mx-auto w-full relative overflow-hidden">

          {/* Question Card */}
          <div className="flex-1 bg-white p-6 sm:p-8 rounded-[2rem] shadow-xl border-4 border-pink-100 text-center flex flex-col items-center justify-center h-auto max-h-[40vh] sm:max-h-full w-full sm:w-auto overflow-y-auto">
              {level.emoji && (
                  <div className="text-7xl sm:text-9xl mb-4 sm:mb-6 animate-bounce-short">
                      {level.emoji}
                  </div>
              )}
              <h3 className="text-xl sm:text-2xl font-bold text-gray-800 leading-relaxed">
                  {level.question}
              </h3>
          </div>

          {/* Feedback Overlay Message */}
          {errorMsg && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 animate-bounce-short pointer-events-none">
                  <div className="bg-red-100 text-red-600 px-8 py-4 rounded-2xl font-bold shadow-2xl border-2 border-red-200 text-2xl whitespace-nowrap">
                      {errorMsg}
                  </div>
              </div>
          )}

          {/* Options */}
          <div className="flex-none w-full sm:w-64 grid grid-cols-1 gap-3 sm:gap-4 overflow-y-auto">
              {level.options.map((opt, idx) => (
                  <button
                    key={idx}
                    onClick={() => handleOptionClick(opt)}
                    className={`
                        py-4 px-2 rounded-xl text-xl font-bold shadow-md transition-all active:scale-95 border-2 min-h-[4rem] flex items-center justify-center
                        ${feedback === 'correct' && opt === level.correctAnswer ? 'bg-green-500 text-white border-green-600' : ''}
                        ${feedback === 'wrong' && opt === wrongOption ? 'bg-gray-100 text-gray-400 border-gray-200 shake' : ''}
                        ${!feedback || (feedback === 'wrong' && opt !== wrongOption) ? 'bg-white text-pink-700 border-pink-200 hover:bg-pink-50' : ''}
                    `}
                  >
                      {opt}
                  </button>
              ))}
          </div>

      </div>
    </div>
  );
};

export default EmotionGame;

export enum GameState {
  MENU = 'MENU',
  SORTING = 'SORTING',
  MEMORY = 'MEMORY',
  BREATHING = 'BREATHING',
  SENTENCE = 'SENTENCE',
  FIND = 'FIND',
  MARKET = 'MARKET',
  STEPS = 'STEPS',
  SHADOW = 'SHADOW',
  STROOP = 'STROOP',
  DOTS = 'DOTS',
  EMOTION = 'EMOTION',
  PATTERN = 'PATTERN',
  TIME = 'TIME',
  ODD_ONE = 'ODD_ONE',
  SOUND = 'SOUND',
  PUZZLE = 'PUZZLE'
}

export type Difficulty = 'NORMAL' | 'ADVANCED';

export interface SortingItem {
  id: string;
  name: string;
  category: 'A' | 'B';
}

export interface SortingLevel {
  categoryA: string;
  categoryB: string;
  items: SortingItem[];
}

export interface MemoryCard {
  id: number;
  content: string; // Emoji or Icon name
  isFlipped: boolean;
  isMatched: boolean;
}

export interface SentenceLevel {
  original: string;
  scrambled: { id: string, text: string }[];
}

export interface FindLevel {
  target: string;
  distractor: string;
  gridSize: number; // e.g. 5 for 5x5
  targetPosition: number; // index
}

// --- NEW GAMES TYPES ---

export interface MarketItem {
  name: string;
  icon: string;
  price: number;
}

export interface MarketLevel {
  items: MarketItem[];
  question: string;
  options: number[]; // 3 numeric options
  correctAnswer: number;
}

export interface StepItem {
  id: string;
  text: string;
  order: number; // Correct order (1, 2, 3...)
}

export interface StepsLevel {
  title: string;
  steps: StepItem[]; // Scrambled when delivered
}

export interface ShadowLevel {
  target: string; // The correct emoji
  options: string[]; // List of emojis (one is target, others are distractors)
  correctIndex: number;
}

// 1. Stroop (Color Trap)
export interface StroopLevel {
  text: string;        // The word displayed (e.g., "紅")
  colorCode: string;   // The css color of the word (e.g., "text-green-500")
  colorName: string;   // The semantic name of the colorCode (e.g., "綠") -> Correct Answer
  options: string[];   // Options displayed to user (e.g., ["紅", "綠", "藍"])
}

// 2. Dots (Spatial Working Memory)
export interface DotLevel {
  gridSize: number;    // 3 for 3x3, 4 for 4x4
  activeIndices: number[]; // Indices of dots to memorize
  duration: number;    // How long to show the dots (ms)
}

// 3. Emotion (Social Cognition)
export interface EmotionLevel {
  question: string;     // Scenario text or "How does he feel?"
  emoji?: string;       // Optional central image/emoji
  options: string[];    // Text options (e.g., "開心", "生氣")
  correctAnswer: string; 
}

// 4. Pattern (Logic)
export interface PatternLevel {
  sequence: string[]; // e.g. ["A", "B", "A", "?"]
  options: string[];  // e.g. ["A", "B", "C"]
  answer: string;
}

// 5. Time (Reality Orientation)
export interface TimeLevel {
  type: 'CLOCK' | 'MATH';
  question: string;
  clockTime?: { hour: number, minute: number }; // For visual clock
  options: string[];
  correctAnswer: string;
}

// 6. Odd One Out (Semantic)
export interface OddOneLevel {
  items: { text: string, icon: string }[];
  correctIndex: number; // The index of the odd one
  reason?: string; // Optional explanation
}

// 7. Sound Match (Auditory Attention)
export interface SoundLevel {
  soundType: 'HIGH' | 'LOW' | 'RISE' | 'FALL' | 'ALARM' | 'GAME';
  targetIcon: string;
  options: { icon: string, label: string, isCorrect: boolean }[];
}

// 8. Puzzle (Visual Spatial)
export interface PuzzleLevel {
  gridSize: number; // 2 or 3
  targetImage: string[]; // Array of icons/colors in correct order
  scrambled: { id: number, content: string }[];
}

class SoundService {
  private ctx: AudioContext | null = null;
  private isMuted: boolean = false;

  private getContext(): AudioContext {
    if (!this.ctx) {
      // Use standard or webkit prefix for broader compatibility
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return this.ctx;
  }

  // Allow user to toggle sound if needed (optional feature for future)
  toggleMute() {
    this.isMuted = !this.isMuted;
  }

  // Safe play wrapper
  private playTone(freq: number, type: OscillatorType, duration: number, startTime: number = 0) {
    if (this.isMuted) return;
    try {
      const ctx = this.getContext();
      // Resume context if suspended (browser policy requires user interaction)
      if (ctx.state === 'suspended') {
        ctx.resume().catch(e => console.error(e));
      }

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.type = type;
      osc.frequency.value = freq;

      const now = ctx.currentTime + startTime;

      // Envelope to avoid clicking sounds
      gain.gain.setValueAtTime(0.01, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05); // Attack
      gain.gain.exponentialRampToValueAtTime(0.001, now + duration); // Decay

      osc.start(now);
      osc.stop(now + duration + 0.1);
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  // --- Standard UI Sounds ---

  playCorrect() {
    // High pitched "Ding" - E5 then C6
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;

    const osc1 = ctx.createOscillator(); const gain1 = ctx.createGain();
    osc1.connect(gain1); gain1.connect(ctx.destination);
    osc1.frequency.setValueAtTime(659.25, now);
    gain1.gain.setValueAtTime(0, now); gain1.gain.linearRampToValueAtTime(0.1, now + 0.05); gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
    osc1.start(now); osc1.stop(now + 0.3);

    const osc2 = ctx.createOscillator(); const gain2 = ctx.createGain();
    osc2.connect(gain2); gain2.connect(ctx.destination);
    osc2.frequency.setValueAtTime(1046.50, now + 0.1);
    gain2.gain.setValueAtTime(0, now + 0.1); gain2.gain.linearRampToValueAtTime(0.1, now + 0.15); gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
    osc2.start(now + 0.1); osc2.stop(now + 0.6);
  }

  playWrong() {
    // Low pitched "Buzz"
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();

    const osc = ctx.createOscillator(); const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(100, ctx.currentTime + 0.2);
    gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.2);
    osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.2);
  }

  playWin() {
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;
    const notes = [{ f: 523.25, t: 0 }, { f: 659.25, t: 0.15 }, { f: 783.99, t: 0.30 }, { f: 1046.50, t: 0.45 }];
    notes.forEach(note => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'triangle'; osc.frequency.value = note.f;
        const startTime = now + note.t;
        gain.gain.setValueAtTime(0, startTime); gain.gain.linearRampToValueAtTime(0.1, startTime + 0.05); gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.5);
        osc.start(startTime); osc.stop(startTime + 0.5);
    });
  }

  // --- Game Specific Pattern Sounds ---

  playGameSound(type: 'HIGH' | 'LOW' | 'RISE' | 'FALL' | 'ALARM' | 'GAME') {
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    switch (type) {
        case 'HIGH': // High Bird-like chirp
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1200, now);
            osc.frequency.linearRampToValueAtTime(1500, now + 0.1);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
            osc.start(now); osc.stop(now + 0.5);
            break;
        case 'LOW': // Low Drum/Bass
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(100, now);
            gain.gain.setValueAtTime(0.3, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
            osc.start(now); osc.stop(now + 0.8);
            break;
        case 'RISE': // Whistle up
            osc.type = 'sine';
            osc.frequency.setValueAtTime(300, now);
            osc.frequency.linearRampToValueAtTime(800, now + 0.5);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0, now + 0.5);
            osc.start(now); osc.stop(now + 0.5);
            break;
        case 'FALL': // Slide down
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.linearRampToValueAtTime(300, now + 0.5);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0, now + 0.5);
            osc.start(now); osc.stop(now + 0.5);
            break;
        case 'ALARM': // Two tone alarm
            osc.type = 'square';
            osc.frequency.setValueAtTime(600, now);
            osc.frequency.setValueAtTime(800, now + 0.2);
            osc.frequency.setValueAtTime(600, now + 0.4);
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 0.6);
            osc.start(now); osc.stop(now + 0.6);
            break;
        case 'GAME': // 8-bit jump
            osc.type = 'square';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.linearRampToValueAtTime(600, now + 0.1);
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 0.2);
            osc.start(now); osc.stop(now + 0.2);
            break;
    }
  }
}

