// Simple Analog Clock Component
const AnalogClock = ({ hour, minute }: { hour: number, minute: number }) => {
    const minuteDeg = minute * 6;
    const hourDeg = (hour % 12) * 30 + minute * 0.5;
    return (
        <div className="relative w-48 h-48 sm:w-64 sm:h-64 rounded-full border-8 border-slate-700 bg-white shadow-xl flex items-center justify-center">
            {/* Markers */}
            {[...Array(12)].map((_, i) => (
                <div key={i} className="absolute w-1 h-3 bg-slate-300" style={{ transform: `rotate(${i * 30}deg) translateY(-85px)` }} />
            ))}
            {/* Hour Hand */}
            <div className="absolute w-2 h-16 sm:h-20 bg-slate-800 rounded-full origin-bottom" style={{ transform: `rotate(${hourDeg}deg) translateY(-50%)`, bottom: '50%' }} />
            {/* Minute Hand */}
            <div className="absolute w-1 h-20 sm:h-28 bg-slate-500 rounded-full origin-bottom" style={{ transform: `rotate(${minuteDeg}deg) translateY(-50%)`, bottom: '50%' }} />
            {/* Center Dot */}
            <div className="absolute w-4 h-4 bg-slate-800 rounded-full z-10" />
        </div>
    );
};

