import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, RotateCcw, CheckCircle } from 'lucide-react';
import { PuzzleLevel, Difficulty } from '../types';
import { generatePuzzleLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 5; // Puzzles take longer, reduce rounds

const PuzzleGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<PuzzleLevel | null>(null);
  const [currentGrid, setCurrentGrid] = useState<{id: number, content: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isRoundComplete, setIsRoundComplete] = useState(false);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsRoundComplete(false);
    setSelectedIdx(null);

    const data = await generatePuzzleLevel(difficulty as Difficulty);
    setLevel(data);
    setCurrentGrid(data.scrambled);

    setLoading(false);
  };

  const handleTileClick = (index: number) => {
    if (isRoundComplete || !level) return;

    if (selectedIdx === null) {
        // Select first tile
        setSelectedIdx(index);
    } else {
        if (selectedIdx === index) {
            // Deselect
            setSelectedIdx(null);
        } else {
            // Swap
            const newGrid = [...currentGrid];
            const temp = newGrid[selectedIdx];
            newGrid[selectedIdx] = newGrid[index];
            newGrid[index] = temp;
            setCurrentGrid(newGrid);
            setSelectedIdx(null);

            checkWin(newGrid);
        }
    }
  };

  const checkWin = (grid: {id: number, content: string}[]) => {
      if (!level) return;
      // Check if IDs match their index (0, 1, 2...)
      const isCorrect = grid.every((item, idx) => item.id === idx);

      if (isCorrect) {
          soundService.playCorrect();
          setIsRoundComplete(true);
          setScore(s => s + 20);
      }
  };

  const handleNext = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-teal-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-teal-200">
          <Trophy className="w-20 h-20 text-teal-500 mx-auto mb-4" />
          <h2 className="text-3xl font-bold text-teal-900 mb-2">拼圖大師！</h2>
          <div className="text-6xl font-black text-teal-600 mb-4">{score}</div>
          <p className="text-gray-600 mb-8">你的空間概念很棒！</p>
          <div className="flex gap-4">
            <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">回主選單</button>
            <button onClick={handleRestart} className="flex-1 py-3 bg-teal-500 text-white rounded-xl font-bold hover:bg-teal-600 shadow-lg">再玩一次</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return <div className="min-h-screen bg-teal-50 flex items-center justify-center"><Loader2 className="animate-spin text-teal-500 w-12 h-12" /></div>;
  }

  const gridStyle = {
      gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
  };

  const labels = ['A', 'B', 'C'].slice(0, level.gridSize);
  const rows = [1, 2, 3].slice(0, level.gridSize);

  return (
    <div className="flex flex-col h-screen bg-teal-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-teal-800 shadow-sm hover:bg-teal-100"><ArrowLeft size={20} /></button>
        <div className="flex items-center gap-4">
          {difficulty === 'ADVANCED' && <span className="bg-teal-600 text-white px-2 py-1 rounded text-xs">進階</span>}
          <div className="text-teal-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
          <div className="flex items-center bg-teal-100 px-3 py-1 rounded-full text-teal-800 font-bold"><Trophy size={16} className="mr-2"/> {score}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 gap-6">

        <div className="mb-4 text-center">
            <h2 className="text-xl font-bold text-teal-900 mb-1">還原圖片</h2>
            <p className="text-teal-600 text-sm">點擊兩個方塊交換位置</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-8 items-center">

            {/* Target Preview (Small) */}
            <div className="bg-white p-2 rounded-xl shadow border-2 border-teal-100">
                <div className="text-xs text-center text-gray-400 mb-1">目標</div>
                <div className="grid gap-1 w-24 h-24" style={gridStyle}>
                    {level.targetImage.map((item, idx) => (
                        <div key={idx} className="bg-gray-100 flex items-center justify-center text-xl rounded">
                            {item}
                        </div>
                    ))}
                </div>
            </div>

            {/* Main Game Grid with Coordinates */}
            <div className="flex flex-col items-center">
                {/* Column Labels */}
                <div className="flex pl-8 mb-1 w-full max-w-[20rem] sm:max-w-[24rem]">
                    {labels.map((label) => (
                        <div key={label} className="flex-1 text-center font-bold text-teal-700 text-lg">
                            {label}
                        </div>
                    ))}
                </div>

                <div className="flex">
                    {/* Row Labels */}
                    <div className="flex flex-col w-8 justify-around pr-1">
                        {rows.map((r) => (
                            <div key={r} className="flex-1 flex items-center justify-center font-bold text-teal-700 text-lg">
                                {r}
                            </div>
                        ))}
                    </div>

                    <div className={`grid gap-2 bg-white p-3 rounded-2xl shadow-xl border-4 ${isRoundComplete ? 'border-green-400' : 'border-teal-200'} w-72 h-72 sm:w-96 sm:h-96`} style={gridStyle}>
                        {currentGrid.map((tile, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleTileClick(idx)}
                                disabled={isRoundComplete}
                                className={`
                                    rounded-xl flex items-center justify-center text-4xl sm:text-6xl transition-all duration-300
                                    ${selectedIdx === idx ? 'bg-yellow-100 ring-4 ring-yellow-300 scale-95 z-10' : 'bg-gray-50 hover:bg-gray-100'}
                                    ${isRoundComplete ? 'bg-green-50' : ''}
                                `}
                            >
                                {tile.content}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Feedback Overlay / Controls */}
        <div className="h-20 flex items-center justify-center relative w-full">
            {isRoundComplete ? (
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center gap-4 z-50">
                    <div className="bg-green-100 border-green-500 text-green-700 px-8 py-3 rounded-full font-bold shadow-xl animate-bounce-short flex items-center gap-2 border-2 whitespace-nowrap">
                        <CheckCircle size={28} />
                        <span className="text-xl">答對了！</span>
                    </div>
                    <button 
                        onClick={handleNext}
                        className="px-8 py-3 bg-teal-600 text-white rounded-full font-bold shadow-lg hover:bg-teal-700 flex items-center text-lg"
                    >
                        下一題 <ArrowRight className="ml-2"/>
                    </button>
                </div>
            ) : (
                <div className="w-full h-full" />
            )}
        </div>

      </div>
    </div>
  );
};

export default PuzzleGame;

class SoundService {
  private ctx: AudioContext | null = null;
  private isMuted: boolean = false;

  private getContext(): AudioContext {
    if (!this.ctx) {
      // Use standard or webkit prefix for broader compatibility
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return this.ctx;
  }

  // Allow user to toggle sound if needed (optional feature for future)
  toggleMute() {
    this.isMuted = !this.isMuted;
  }

  // Safe play wrapper
  private playTone(freq: number, type: OscillatorType, duration: number, startTime: number = 0) {
    if (this.isMuted) return;
    try {
      const ctx = this.getContext();
      // Resume context if suspended (browser policy requires user interaction)
      if (ctx.state === 'suspended') {
        ctx.resume().catch(e => console.error(e));
      }

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.type = type;
      osc.frequency.value = freq;

      const now = ctx.currentTime + startTime;

      // Envelope to avoid clicking sounds
      gain.gain.setValueAtTime(0.01, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05); // Attack
      gain.gain.exponentialRampToValueAtTime(0.001, now + duration); // Decay

      osc.start(now);
      osc.stop(now + duration + 0.1);
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  // --- Standard UI Sounds ---

  playCorrect() {
    // High pitched "Ding" - E5 then C6
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;

    const osc1 = ctx.createOscillator(); const gain1 = ctx.createGain();
    osc1.connect(gain1); gain1.connect(ctx.destination);
    osc1.frequency.setValueAtTime(659.25, now);
    gain1.gain.setValueAtTime(0, now); gain1.gain.linearRampToValueAtTime(0.1, now + 0.05); gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
    osc1.start(now); osc1.stop(now + 0.3);

    const osc2 = ctx.createOscillator(); const gain2 = ctx.createGain();
    osc2.connect(gain2); gain2.connect(ctx.destination);
    osc2.frequency.setValueAtTime(1046.50, now + 0.1);
    gain2.gain.setValueAtTime(0, now + 0.1); gain2.gain.linearRampToValueAtTime(0.1, now + 0.15); gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
    osc2.start(now + 0.1); osc2.stop(now + 0.6);
  }

  playWrong() {
    // Low pitched "Buzz"
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();

    const osc = ctx.createOscillator(); const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(100, ctx.currentTime + 0.2);
    gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.2);
    osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.2);
  }

  playWin() {
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;
    const notes = [{ f: 523.25, t: 0 }, { f: 659.25, t: 0.15 }, { f: 783.99, t: 0.30 }, { f: 1046.50, t: 0.45 }];
    notes.forEach(note => {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = 'triangle'; osc.frequency.value = note.f;
        const startTime = now + note.t;
        gain.gain.setValueAtTime(0, startTime); gain.gain.linearRampToValueAtTime(0.1, startTime + 0.05); gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.5);
        osc.start(startTime); osc.stop(startTime + 0.5);
    });
  }

  // --- Game Specific Pattern Sounds (Longer & More Varieties) ---

  playGameSound(type: 'HIGH' | 'LOW' | 'RISE' | 'FALL' | 'ALARM' | 'GAME' | 'BOUNCE' | 'MAGIC' | 'TELEPHONE') {
    const ctx = this.getContext();
    if (this.isMuted) return;
    if (ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    switch (type) {
        case 'HIGH': // High Bird-like chirp (Longer)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1200, now);
            osc.frequency.linearRampToValueAtTime(1600, now + 0.2);
            osc.frequency.linearRampToValueAtTime(1200, now + 0.4);
            osc.frequency.linearRampToValueAtTime(1600, now + 0.6);
            osc.frequency.linearRampToValueAtTime(1200, now + 0.8);

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 1.5);
            osc.start(now); osc.stop(now + 1.5);
            break;
        case 'LOW': // Low Drum/Bass (Longer)
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(100, now);
            gain.gain.setValueAtTime(0.4, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 1.5);
            osc.start(now); osc.stop(now + 1.5);
            break;
        case 'RISE': // Whistle up (Longer)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.exponentialRampToValueAtTime(1200, now + 1.5);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.5);
            osc.start(now); osc.stop(now + 1.5);
            break;
        case 'FALL': // Slide down (Longer)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1200, now);
            osc.frequency.exponentialRampToValueAtTime(100, now + 1.5);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.5);
            osc.start(now); osc.stop(now + 1.5);
            break;
        case 'ALARM': // Two tone alarm (Longer loop)
            osc.type = 'square';
            // Beep 1
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.setValueAtTime(600, now + 0.3);
            // Beep 2
            osc.frequency.setValueAtTime(800, now + 0.6);
            osc.frequency.setValueAtTime(600, now + 0.9);
            // Beep 3
            osc.frequency.setValueAtTime(800, now + 1.2);
            osc.frequency.setValueAtTime(600, now + 1.5);

            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.8);
            osc.start(now); osc.stop(now + 1.8);
            break;
        case 'GAME': // 8-bit jump (Longer sequence)
            osc.type = 'square';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.linearRampToValueAtTime(600, now + 0.2); // Jump 1
            osc.frequency.setValueAtTime(200, now + 0.3);
            osc.frequency.linearRampToValueAtTime(700, now + 0.5); // Jump 2
            osc.frequency.setValueAtTime(200, now + 0.6);
            osc.frequency.linearRampToValueAtTime(800, now + 0.9); // Jump 3

            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.0);
            osc.start(now); osc.stop(now + 1.0);
            break;
        case 'BOUNCE': // Frequency modulation (boing)
            osc.type = 'sine';
            osc.frequency.setValueAtTime(400, now);
            osc.frequency.exponentialRampToValueAtTime(100, now + 0.3); // Drop
            osc.frequency.setValueAtTime(300, now + 0.3);
            osc.frequency.exponentialRampToValueAtTime(100, now + 0.5); // Drop 2

            gain.gain.setValueAtTime(0.1, now);
            gain.gain.linearRampToValueAtTime(0, now + 0.8);
            osc.start(now); osc.stop(now + 0.8);
            break;
        case 'MAGIC': // Sparkly Arpeggio
            osc.type = 'triangle';
            // C5, E5, G5, C6, E6
            [523, 659, 784, 1046, 1318].forEach((f, i) => {
                osc.frequency.setValueAtTime(f, now + i * 0.2);
            });
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.2);
            osc.start(now); osc.stop(now + 1.2);
            break;
        case 'TELEPHONE': // Trill
            osc.type = 'square';
            const startTime = now;
            for(let i=0; i<15; i++) {
                osc.frequency.setValueAtTime(i % 2 === 0 ? 800 : 1000, startTime + i * 0.1);
            }
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.linearRampToValueAtTime(0, now + 1.5);
            osc.start(now); osc.stop(now + 1.5);
            break;
    }
  }
}

