const SoundGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<SoundLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setSelectedIndex(null);
    const data = await generateSoundLevel(difficulty as Difficulty);
    setLevel(data);
    setLoading(false);
    // Auto play sound after slight delay
    setTimeout(() => playSound(data.soundType), 500);
  };

  const playSound = (type: any) => {
      setIsPlaying(true);
      soundService.playGameSound(type);
      setTimeout(() => setIsPlaying(false), 1000);
  }

  const handleOptionClick = (index: number) => {
    if (!level || feedback) return;
    setSelectedIndex(index);

    if (level.options[index].isCorrect) {
      setFeedback('correct');
      soundService.playCorrect();
      setScore(s => s + 10);

      setTimeout(() => {
        if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
        } else {
          setIsFinished(true);
          soundService.playWin();
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      soundService.playWrong();
      setTimeout(() => {
        setFeedback(null);
        setSelectedIndex(null);
      }, 1000);
    }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-indigo-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-indigo-200">
          <Trophy className="w-20 h-20 text-indigo-500 mx-auto mb-4" />
          <h2 className="text-3xl font-bold text-indigo-900 mb-2">聽力絕佳！</h2>
          <div className="text-6xl font-black text-indigo-600 mb-4">{score}</div>
          <p className="text-gray-600 mb-8">你的專注力很棒！</p>
          <div className="flex gap-4">
            <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">回主選單</button>
            <button onClick={handleRestart} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl font-bold hover:bg-indigo-600 shadow-lg">再玩一次</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return <div className="min-h-screen bg-indigo-50 flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500 w-12 h-12" /></div>;
  }

  return (
    <div className="flex flex-col h-screen bg-indigo-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-indigo-800 shadow-sm hover:bg-indigo-100"><ArrowLeft size={20} /></button>
        <div className="flex items-center gap-4">
          {difficulty === 'ADVANCED' && <span className="bg-indigo-600 text-white px-2 py-1 rounded text-xs">進階</span>}
          <div className="text-indigo-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
          <div className="flex items-center bg-indigo-100 px-3 py-1 rounded-full text-indigo-800 font-bold"><Trophy size={16} className="mr-2"/> {score}</div>
        </div>
      </div>

      {/* Main Content - Flex-row on Landscape */}
      <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-4 gap-6 sm:gap-12 w-full max-w-5xl mx-auto overflow-hidden">

        {/* Left: Options Grid */}
        <div className="flex-1 grid grid-cols-2 gap-3 sm:gap-4 w-full max-w-md aspect-square sm:aspect-auto sm:h-full sm:max-h-[60vh]">
          {level.options.map((opt, idx) => (
            <button
              key={idx}
              onClick={() => handleOptionClick(idx)}
              disabled={!!feedback}
              className={`
                rounded-xl shadow-md border-2 p-2 sm:p-4 flex flex-col items-center justify-center transition-all active:scale-95 h-full
                ${feedback === 'correct' && opt.isCorrect ? 'bg-green-100 border-green-500' : ''}
                ${feedback === 'wrong' && idx === selectedIndex ? 'bg-red-100 border-red-300' : 'bg-white border-indigo-100 hover:border-indigo-300'}
              `}
            >
              <span className="text-4xl sm:text-5xl mb-2">{opt.icon}</span>
              <span className="text-gray-700 font-bold text-lg">{opt.label}</span>
            </button>
          ))}
        </div>

        {/* Right: Play Button & Instructions */}
        <div className="flex-none flex flex-col items-center gap-4">
            <button 
                onClick={() => playSound(level.soundType)}
                className={`
                    w-32 h-32 sm:w-40 sm:h-40 rounded-full shadow-2xl border-8 flex flex-col items-center justify-center transition-transform active:scale-95
                    ${isPlaying ? 'bg-indigo-200 border-indigo-400 scale-105' : 'bg-white border-indigo-100 hover:bg-indigo-50'}
                `}
            >
                <Volume2 size={48} className={`mb-1 ${isPlaying ? 'text-indigo-600 animate-pulse' : 'text-indigo-400'}`} />
                <span className="text-indigo-900 font-bold text-base">播放聲音</span>
            </button>
            <div className="text-gray-500 font-bold bg-white/50 px-4 py-1 rounded-full">請選擇對應的聲音</div>
        </div>

        {/* Feedback Overlay */}
        {feedback && (
            <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 px-8 py-4 rounded-3xl shadow-2xl border-4 z-50 animate-bounce-short flex items-center gap-3 ${feedback === 'correct' ? 'bg-green-100 border-green-500 text-green-700' : 'bg-red-100 border-red-500 text-red-700'}`}>
                {feedback === 'correct' ? <CheckCircle size={32} /> : <XCircle size={32} />}
                <span className="text-2xl font-bold">{feedback === 'correct' ? "答對了！" : "再想想看"}</span>
            </div>
        )}
      </div>
    </div>
  );
};

export default SoundGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, RotateCcw, CheckCircle } from 'lucide-react';
import { PuzzleLevel, Difficulty } from '../types';
import { generatePuzzleLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 5; // Puzzles take longer, reduce rounds

const PuzzleGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<PuzzleLevel | null>(null);
  const [currentGrid, setCurrentGrid] = useState<{id: number, content: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isRoundComplete, setIsRoundComplete] = useState(false);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsRoundComplete(false);
    setSelectedIdx(null);

    const data = await generatePuzzleLevel(difficulty as Difficulty);
    setLevel(data);
    setCurrentGrid(data.scrambled);

    setLoading(false);
  };

  const handleTileClick = (index: number) => {
    if (isRoundComplete || !level) return;

    if (selectedIdx === null) {
        // Select first tile
        setSelectedIdx(index);
    } else {
        if (selectedIdx === index) {
            // Deselect
            setSelectedIdx(null);
        } else {
            // Swap
            const newGrid = [...currentGrid];
            const temp = newGrid[selectedIdx];
            newGrid[selectedIdx] = newGrid[index];
            newGrid[index] = temp;
            setCurrentGrid(newGrid);
            setSelectedIdx(null);

            checkWin(newGrid);
        }
    }
  };

  const checkWin = (grid: {id: number, content: string}[]) => {
      if (!level) return;
      // Check if IDs match their index (0, 1, 2...)
      const isCorrect = grid.every((item, idx) => item.id === idx);

      if (isCorrect) {
          soundService.playCorrect();
          setIsRoundComplete(true);
          setScore(s => s + 20);
      }
  };

  const handleNext = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-teal-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-teal-200">
          <Trophy className="w-20 h-20 text-teal-500 mx-auto mb-4" />
          <h2 className="text-3xl font-bold text-teal-900 mb-2">拼圖大師！</h2>
          <div className="text-6xl font-black text-teal-600 mb-4">{score}</div>
          <p className="text-gray-600 mb-8">你的空間概念很棒！</p>
          <div className="flex gap-4">
            <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">回主選單</button>
            <button onClick={handleRestart} className="flex-1 py-3 bg-teal-500 text-white rounded-xl font-bold hover:bg-teal-600 shadow-lg">再玩一次</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return <div className="min-h-screen bg-teal-50 flex items-center justify-center"><Loader2 className="animate-spin text-teal-500 w-12 h-12" /></div>;
  }

  const gridStyle = {
      gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
  };

  const labels = ['A', 'B', 'C'].slice(0, level.gridSize);
  const rows = [1, 2, 3].slice(0, level.gridSize);

  return (
    <div className="flex flex-col h-screen bg-teal-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-teal-800 shadow-sm hover:bg-teal-100"><ArrowLeft size={20} /></button>
        <div className="flex items-center gap-4">
          {difficulty === 'ADVANCED' && <span className="bg-teal-600 text-white px-2 py-1 rounded text-xs">進階</span>}
          <div className="text-teal-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
          <div className="flex items-center bg-teal-100 px-3 py-1 rounded-full text-teal-800 font-bold"><Trophy size={16} className="mr-2"/> {score}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-2 sm:p-4 gap-4 w-full h-full overflow-hidden">

        {/* Title removed to save space or made very small */}
        <div className="text-center shrink-0">
            <h2 className="text-lg sm:text-xl font-bold text-teal-900">還原圖片</h2>
        </div>

        <div className="flex flex-row items-center justify-center gap-6 sm:gap-12 w-full max-w-5xl">

            {/* Target Preview (Small -> Medium) */}
            <div className="bg-white p-3 rounded-xl shadow-md border-2 border-teal-100 shrink-0">
                <div className="text-sm text-center text-gray-400 mb-1 font-bold">目標</div>
                <div className="grid gap-1 w-32 h-32 sm:w-40 sm:h-40" style={gridStyle}>
                    {level.targetImage.map((item, idx) => (
                        <div key={idx} className="bg-gray-100 flex items-center justify-center text-3xl rounded">
                            {item}
                        </div>
                    ))}
                </div>
            </div>

            {/* Main Game Grid with Coordinates */}
            <div className="flex flex-col items-center shrink-0">
                {/* Column Labels */}
                <div className="flex pl-8 mb-1 w-full max-w-[20rem] sm:max-w-[24rem]">
                    {labels.map((label) => (
                        <div key={label} className="flex-1 text-center font-bold text-teal-700 text-lg">
                            {label}
                        </div>
                    ))}
                </div>

                <div className="flex">
                    {/* Row Labels */}
                    <div className="flex flex-col w-8 justify-around pr-1">
                        {rows.map((r) => (
                            <div key={r} className="flex-1 flex items-center justify-center font-bold text-teal-700 text-lg">
                                {r}
                            </div>
                        ))}
                    </div>

                    <div className={`grid gap-2 bg-white p-3 rounded-2xl shadow-xl border-4 ${isRoundComplete ? 'border-green-400' : 'border-teal-200'} w-64 h-64 sm:w-80 sm:h-80`} style={gridStyle}>
                        {currentGrid.map((tile, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleTileClick(idx)}
                                disabled={isRoundComplete}
                                className={`
                                    rounded-xl flex items-center justify-center text-4xl sm:text-5xl transition-all duration-300
                                    ${selectedIdx === idx ? 'bg-yellow-100 ring-4 ring-yellow-300 scale-95 z-10' : 'bg-gray-50 hover:bg-gray-100'}
                                    ${isRoundComplete ? 'bg-green-50' : ''}
                                `}
                            >
                                {tile.content}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Feedback Overlay / Controls - Occupy remaining space but don't overflow */}
        <div className="h-16 flex items-center justify-center relative w-full shrink-0">
            {isRoundComplete ? (
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center gap-2 z-50">
                    <div className="bg-green-100 border-green-500 text-green-700 px-8 py-2 rounded-full font-bold shadow-xl animate-bounce-short flex items-center gap-2 border-2 whitespace-nowrap">
                        <CheckCircle size={24} />
                        <span className="text-lg">答對了！</span>
                    </div>
                    <button 
                        onClick={handleNext}
                        className="px-8 py-2 bg-teal-600 text-white rounded-full font-bold shadow-lg hover:bg-teal-700 flex items-center text-lg"
                    >
                        下一題 <ArrowRight className="ml-2"/>
                    </button>
                </div>
            ) : (
                <p className="text-teal-600 text-sm animate-pulse">點擊兩個方塊交換位置</p>
            )}
        </div>

      </div>
    </div>
  );
};

export default PuzzleGame;

import { SortingLevel, SentenceLevel, FindLevel, MarketLevel, StepsLevel, ShadowLevel, StroopLevel, DotLevel, EmotionLevel, PatternLevel, TimeLevel, OddOneLevel, SoundLevel, PuzzleLevel, Difficulty } from "../types";
import { 
    STATIC_SENTENCES, 
    STATIC_SENTENCES_ADVANCED,
    STATIC_SORTING_LEVELS, 
    STATIC_SORTING_LEVELS_ADVANCED,
    STATIC_FIND_PAIRS, 
    STATIC_ENCOURAGEMENTS,
    STATIC_MARKET_LEVELS,
    STATIC_MARKET_LEVELS_ADVANCED_FIXED,
    STATIC_STEPS_LEVELS,
    STATIC_STEPS_LEVELS_ADVANCED,
    STATIC_SHADOW_LEVELS,
    STATIC_SHADOW_LEVELS_ADVANCED,
    STATIC_EMOTION_LEVELS,
    STATIC_EMOTION_LEVELS_ADVANCED,
    STATIC_PATTERN_LEVELS,
    STATIC_PATTERN_LEVELS_ADVANCED,
    STATIC_TIME_LEVELS,
    STATIC_TIME_LEVELS_ADVANCED,
    STATIC_ODD_ONE_LEVELS,
    STATIC_ODD_ONE_LEVELS_ADVANCED,
    STATIC_SOUND_LEVELS,
    STATIC_PUZZLE_LEVELS,
    STATIC_PUZZLE_LEVELS_ADVANCED
} from "./staticData";

// --- SORTING GAME ---
export const generateSortingLevel = async (excludeIndices: number[] = [], fixedIndex: number | null = null, difficulty: Difficulty = 'NORMAL'): Promise<{level: SortingLevel, index: number}> => {
  await new Promise(resolve => setTimeout(resolve, 100));
  const dataSource = difficulty === 'ADVANCED' ? STATIC_SORTING_LEVELS_ADVANCED : STATIC_SORTING_LEVELS;
  let randomIndex: number;
  if (fixedIndex !== null && fixedIndex >= 0 && fixedIndex < dataSource.length) {
      randomIndex = fixedIndex;
  } else {
      const availableIndices = dataSource.map((_, idx) => idx).filter(idx => !excludeIndices.includes(idx));
      const pool = availableIndices.length > 0 ? availableIndices : dataSource.map((_, idx) => idx);
      randomIndex = pool[Math.floor(Math.random() * pool.length)];
  }
  const levelData = dataSource[randomIndex];
  const items = [...levelData.items.map(item => ({...item}))];
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return {
    level: { categoryA: levelData.categoryA, categoryB: levelData.categoryB, items: items },
    index: randomIndex
  };
};

// --- SENTENCE GAME ---
export const generateSentenceLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<SentenceLevel> => {
  await new Promise(resolve => setTimeout(resolve, 100));
  const dataSource = difficulty === 'ADVANCED' ? STATIC_SENTENCES_ADVANCED : STATIC_SENTENCES;
  const randomIndex = Math.floor(Math.random() * dataSource.length);
  const sentence = dataSource[randomIndex];
  const chars = sentence.split('').map((char: string, index: number) => ({ id: `${index}-${char}`, text: char }));
  const shuffled = [...chars];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return { original: sentence, scrambled: shuffled };
};

// --- FIND GAME ---
export const generateFindLevel = async (round: number = 1, difficulty: Difficulty = 'NORMAL'): Promise<FindLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    let targetDifficulty = 1;
    if (difficulty === 'NORMAL') {
        if (round >= 4 && round <= 6) targetDifficulty = 2;
        if (round >= 7) targetDifficulty = 3;
    } else {
        if (round <= 4) targetDifficulty = 2;
        else targetDifficulty = 3;
    }
    const eligiblePairs = STATIC_FIND_PAIRS.filter(p => p.difficulty === targetDifficulty);
    const pool = eligiblePairs.length > 0 ? eligiblePairs : STATIC_FIND_PAIRS;
    const randomIndex = Math.floor(Math.random() * pool.length);
    const pair = pool[randomIndex];
    const gridSize = 16; 
    const targetPosition = Math.floor(Math.random() * gridSize);
    return { target: pair.target, distractor: pair.distractor, gridSize, targetPosition };
}

// --- MARKET GAME ---
export const generateMarketLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<MarketLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_MARKET_LEVELS_ADVANCED_FIXED : STATIC_MARKET_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    return dataSource[randomIndex];
}

// --- STEPS GAME ---
export const generateStepsLevel = async (excludeTitles: string[] = [], difficulty: Difficulty = 'NORMAL'): Promise<StepsLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_STEPS_LEVELS_ADVANCED : STATIC_STEPS_LEVELS;
    const availableLevels = dataSource.filter(l => !excludeTitles.includes(l.title));
    const pool = availableLevels.length > 0 ? availableLevels : dataSource;
    const randomIndex = Math.floor(Math.random() * pool.length);
    const level = pool[randomIndex];
    const steps = [...level.steps];
    for (let i = steps.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [steps[i], steps[j]] = [steps[j], steps[i]];
    }
    return { title: level.title, steps: steps };
}

// --- SHADOW GAME ---
export const generateShadowLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<ShadowLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_SHADOW_LEVELS_ADVANCED : STATIC_SHADOW_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];
    const options = [...level.options];
    for (let i = options.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [options[i], options[j]] = [options[j], options[i]];
    }
    const correctIndex = options.indexOf(level.target);
    return { target: level.target, options: options, correctIndex: correctIndex };
}

// --- STROOP GAME ---
export const generateStroopLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<StroopLevel> => {
    await new Promise(resolve => setTimeout(resolve, 50));
    const baseColors = [{ name: "紅", code: "text-red-500" }, { name: "藍", code: "text-blue-500" }, { name: "綠", code: "text-green-500" }, { name: "黑", code: "text-black" }];
    const advancedColors = [...baseColors, { name: "紫", code: "text-purple-500" }, { name: "橘", code: "text-orange-500" }, { name: "灰", code: "text-gray-500" }];
    const colors = difficulty === 'ADVANCED' ? advancedColors : baseColors;
    const textIndex = Math.floor(Math.random() * colors.length);
    const textObj = colors[textIndex];
    let colorIndex = Math.floor(Math.random() * colors.length);
    const mismatchChance = difficulty === 'ADVANCED' ? 0.9 : 0.7;
    if (colorIndex === textIndex && Math.random() < mismatchChance) {
         colorIndex = (colorIndex + 1) % colors.length;
    }
    const colorObj = colors[colorIndex];
    const correctAnswer = colorObj.name;
    const distractors = colors.filter(c => c.name !== correctAnswer).sort(() => 0.5 - Math.random()).slice(0, 2).map(c => c.name);
    const options = [...distractors, correctAnswer].sort(() => 0.5 - Math.random());
    return { text: textObj.name, colorCode: colorObj.code, colorName: correctAnswer, options };
}

// --- DOTS GAME ---
export const generateDotLevel = async (round: number, difficulty: Difficulty = 'NORMAL'): Promise<DotLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    let gridSize = 3;
    let numDots = 3;
    let duration = 10000; 
    if (difficulty === 'NORMAL') {
        if (round === 1) numDots = 3;
        else if (round === 2) numDots = 4;
        else if (round === 3) { numDots = 5; gridSize = 4; }
        else if (round === 4) { numDots = 6; gridSize = 4; }
        else if (round === 5) { numDots = 7; gridSize = 4; }
        else if (round >= 6) { numDots = 8; gridSize = 4; }
    } else {
        if (round === 1) { numDots = 4; gridSize = 3; duration = 8000; }
        else if (round === 2) { numDots = 5; gridSize = 4; duration = 8000; }
        else if (round === 3) { numDots = 6; gridSize = 4; duration = 7000; }
        else if (round === 4) { numDots = 7; gridSize = 4; duration = 6000; } 
        else if (round === 5) { numDots = 8; gridSize = 4; duration = 5000; }
        else if (round >= 6) { numDots = 9; gridSize = 4; duration = 4000; }
    }
    const totalCells = gridSize * gridSize;
    const activeIndices: number[] = [];
    while (activeIndices.length < numDots) {
        const idx = Math.floor(Math.random() * totalCells);
        if (!activeIndices.includes(idx)) {
            activeIndices.push(idx);
        }
    }
    return { gridSize, activeIndices, duration };
}

// --- EMOTION GAME ---
export const generateEmotionLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<EmotionLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_EMOTION_LEVELS_ADVANCED : STATIC_EMOTION_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];
    const shuffledOptions = [...level.options].sort(() => 0.5 - Math.random());
    return { ...level, options: shuffledOptions };
}

// --- NEW GENERATORS ---

// 4. Pattern
export const generatePatternLevel = async (excludeIndices: number[] = [], difficulty: Difficulty = 'NORMAL'): Promise<{level: PatternLevel, index: number}> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_PATTERN_LEVELS_ADVANCED : STATIC_PATTERN_LEVELS;

    const availableIndices = dataSource.map((_, idx) => idx).filter(idx => !excludeIndices.includes(idx));
    const pool = availableIndices.length > 0 ? availableIndices : dataSource.map((_, idx) => idx);

    const randomIndex = pool[Math.floor(Math.random() * pool.length)];
    return { level: dataSource[randomIndex], index: randomIndex };
};

// 5. Time
export const generateTimeLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<TimeLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_TIME_LEVELS_ADVANCED : STATIC_TIME_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];
    return {
        ...level,
        options: [...level.options].sort(() => 0.5 - Math.random()) // Shuffle options
    };
};

// 6. Odd One Out
export const generateOddOneLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<OddOneLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_ODD_ONE_LEVELS_ADVANCED : STATIC_ODD_ONE_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];

    // We need to shuffle items but keep track of the correct answer
    const originalItems = level.items;
    const correctItem = originalItems[level.correctIndex];

    const shuffledItems = [...originalItems].sort(() => 0.5 - Math.random());
    const newCorrectIndex = shuffledItems.indexOf(correctItem);

    return {
        items: shuffledItems,
        correctIndex: newCorrectIndex,
        reason: level.reason
    };
};

// 7. Sound
export const generateSoundLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<SoundLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    // Sound game logic is simpler, difficulty mainly affects response time requirements in scoring, 
    // or we could add more confusing sounds later. For now, use the same pool.
    const dataSource = STATIC_SOUND_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];

    return {
        ...level,
        options: [...level.options].sort(() => 0.5 - Math.random())
    };
};

// 8. Puzzle
export const generatePuzzleLevel = async (difficulty: Difficulty = 'NORMAL'): Promise<PuzzleLevel> => {
    await new Promise(resolve => setTimeout(resolve, 100));
    const dataSource = difficulty === 'ADVANCED' ? STATIC_PUZZLE_LEVELS_ADVANCED : STATIC_PUZZLE_LEVELS;
    const randomIndex = Math.floor(Math.random() * dataSource.length);
    const level = dataSource[randomIndex];

    // Create scrambled pieces
    const pieces = level.targetImage.map((content, idx) => ({ id: idx, content }));
    let scrambled = [...pieces].sort(() => 0.5 - Math.random());

    // Ensure not solved initially
    const isSolved = (arr: any[]) => arr.every((p, i) => p.id === i);
    while (isSolved(scrambled)) {
        scrambled = [...pieces].sort(() => 0.5 - Math.random());
    }

    return {
        gridSize: level.gridSize,
        targetImage: level.targetImage,
        scrambled: scrambled
    };
};

// --- ENCOURAGEMENT ---
export const generateEncouragement = async (score: number): Promise<string> => {
    const randomIndex = Math.floor(Math.random() * STATIC_ENCOURAGEMENTS.length);
    return STATIC_ENCOURAGEMENTS[randomIndex];
};

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Loader2, Trophy, HelpCircle, CheckCircle, XCircle, ArrowRight } from 'lucide-react';
import { PatternLevel, Difficulty } from '../types';
import { generatePatternLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const PatternGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<PatternLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isRoundComplete, setIsRoundComplete] = useState(false);
  const startTimeRef = useRef<number>(0);

  // Track used indices to avoid repeats in a session
  const [usedIndices, setUsedIndices] = useState<number[]>([]);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setFeedback(null);
    setSelectedOption(null);
    setIsRoundComplete(false);

    // Pass used indices to exclude them
    const { level: data, index } = await generatePatternLevel(usedIndices, difficulty as Difficulty);

    setLevel(data);
    setUsedIndices(prev => [...prev, index]); // Add current to history

    setLoading(false);
    startTimeRef.current = Date.now();
  };

  const handleOptionClick = (option: string) => {
    if (!level || feedback || isRoundComplete) return;
    setSelectedOption(option);

    if (option === level.answer) {
      setFeedback('correct');
      setIsRoundComplete(true);
      soundService.playCorrect();
      const timeTaken = (Date.now() - startTimeRef.current) / 1000;
      let points = 10;
      if (timeTaken < 5) points += 10;
      setScore(s => s + points);
      // Removed auto-advance logic
    } else {
      setFeedback('wrong');
      soundService.playWrong();
      setTimeout(() => {
        setFeedback(null);
        setSelectedOption(null);
      }, 1000);
    }
  };

  const handleNext = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setUsedIndices([]); // Reset history
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-blue-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-blue-200">
          <Trophy className="w-20 h-20 text-blue-500 mx-auto mb-4" />
          <h2 className="text-3xl font-bold text-blue-900 mb-2">推理完成！</h2>
          <div className="text-6xl font-black text-blue-600 mb-4">{score}</div>
          <p className="text-gray-600 mb-8">你的邏輯非常清晰！</p>
          <div className="flex gap-4">
            <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">回主選單</button>
            <button onClick={handleRestart} className="flex-1 py-3 bg-blue-500 text-white rounded-xl font-bold hover:bg-blue-600 shadow-lg">再玩一次</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return (
      <div className="min-h-screen bg-blue-50 flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-500 w-12 h-12" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-blue-50 overflow-hidden relative">
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-blue-800 shadow-sm hover:bg-blue-100"><ArrowLeft size={20} /></button>
        <div className="flex items-center gap-4">
          {difficulty === 'ADVANCED' && <span className="bg-blue-600 text-white px-2 py-1 rounded text-xs">進階</span>}
          <div className="text-blue-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
          <div className="flex items-center bg-blue-100 px-3 py-1 rounded-full text-blue-800 font-bold"><Trophy size={16} className="mr-2"/> {score}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-2 sm:p-4 gap-4 sm:gap-8 overflow-hidden">

        {/* Question Sequence */}
        <div className="bg-white p-4 sm:p-6 rounded-3xl shadow-lg border-2 border-blue-100 w-full max-w-4xl flex flex-wrap justify-center gap-2 sm:gap-6 min-h-[100px] sm:min-h-[120px] items-center shrink-0">
          {level.sequence.map((item, idx) => {
            const isQuestionMark = item === '?';
            // If round is complete and this is the question mark, show the answer
            const content = (isQuestionMark && isRoundComplete) ? level.answer : item;
            // Highlight style for the revealed answer
            const isRevealedAnswer = isQuestionMark && isRoundComplete;

            return (
                <div key={idx} className={`
                    text-4xl sm:text-6xl transition-all duration-500
                    ${isQuestionMark && !isRoundComplete ? 'text-blue-300 animate-pulse' : ''}
                    ${isRevealedAnswer ? 'text-green-600 scale-125 font-bold' : ''}
                `}>
                {(isQuestionMark && !isRoundComplete) ? <HelpCircle size={40} className="sm:w-16 sm:h-16" /> : content}
                </div>
            );
          })}
        </div>

        {/* Options / Result Area - Fixed Height Container to prevent jumping */}
        <div className="w-full max-w-xl flex flex-col items-center justify-center min-h-[120px] sm:min-h-[160px]">
            {!isRoundComplete ? (
                <>
                    <div className="grid grid-cols-3 gap-3 sm:gap-4 w-full">
                    {level.options.map((opt, idx) => (
                        <button
                        key={idx}
                        onClick={() => handleOptionClick(opt)}
                        disabled={!!feedback}
                        className={`
                            h-20 sm:h-24 rounded-2xl text-3xl sm:text-4xl shadow-md border-2 transition-all active:scale-95 flex items-center justify-center
                            ${feedback === 'wrong' && opt === selectedOption ? 'bg-red-100 border-red-300' : 'bg-white hover:bg-blue-50 border-blue-200'}
                        `}
                        >
                        {opt}
                        </button>
                    ))}
                    </div>
                    <div className="text-blue-400 font-bold text-base sm:text-lg mt-4 animate-fade-in">下一個是什麼？</div>
                </>
            ) : (
                <div className="flex flex-col items-center gap-4 animate-fade-in-up w-full">
                    <div className="flex items-center gap-2 text-green-600 bg-green-100 px-6 py-2 rounded-full border-2 border-green-300">
                        <CheckCircle size={32} />
                        <span className="text-2xl font-bold">答對了！</span>
                    </div>
                    <button 
                        onClick={handleNext}
                        className="w-full sm:w-auto px-12 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg hover:bg-blue-700 flex items-center justify-center text-xl transition-all active:scale-95"
                    >
                        下一題 <ArrowRight className="ml-2" />
                    </button>
                </div>
            )}
        </div>

        {/* Wrong Feedback Overlay (Transient) */}
        {feedback === 'wrong' && (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 px-8 py-4 rounded-3xl shadow-2xl border-4 z-50 animate-bounce-short flex items-center gap-3 bg-red-100 border-red-500 text-red-700 pointer-events-none">
                <XCircle size={32} />
                <span className="text-2xl font-bold">再想想看</span>
            </div>
        )}
      </div>
    </div>
  );
};

export default PatternGame;

