import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, Eye, Play, ArrowRight, CheckCircle, XCircle } from 'lucide-react';
import { DotLevel, Difficulty } from '../types';
import { generateDotLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const DotGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<DotLevel | null>(null);
  const [loading, setLoading] = useState(true);
  const [gameState, setGameState] = useState<'memorize' | 'recall' | 'result'>('memorize');
  const [userSelection, setUserSelection] = useState<number[]>([]);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [countdown, setCountdown] = useState(0);

  // Feedback text
  const [feedbackText, setFeedbackText] = useState("");

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setGameState('memorize');
    setUserSelection([]);
    setFeedbackText("");

    const data = await generateDotLevel(round, difficulty as Difficulty);
    setLevel(data);
    setLoading(false);

    // Countdown for memorize phase
    setCountdown(data.duration / 1000);
  };

  // Timer for Memorize Phase
  useEffect(() => {
    if (gameState === 'memorize' && level) {
        const timer = setTimeout(() => {
            setGameState('recall');
        }, level.duration);

        // Visual countdown
        const interval = setInterval(() => {
            setCountdown(c => Math.max(0, c - 0.1));
        }, 100);

        return () => {
            clearTimeout(timer);
            clearInterval(interval);
        };
    }
  }, [gameState, level]);

  const handleCellClick = (index: number) => {
    if (gameState !== 'recall') return;

    // Toggle selection
    let newSelection = [...userSelection];
    if (newSelection.includes(index)) {
        newSelection = newSelection.filter(i => i !== index);
    } else {
        // Limit selection to number of dots
        if (level && newSelection.length < level.activeIndices.length) {
            newSelection.push(index);
        }
    }
    setUserSelection(newSelection);
  };

  const checkAnswer = () => {
      if (!level) return;

      const correctSet = new Set(level.activeIndices);
      const userSet = new Set(userSelection);

      // Check if sets match
      let isCorrect = true;
      if (correctSet.size !== userSet.size) isCorrect = false;
      for (let elem of userSet) {
          if (!correctSet.has(elem)) isCorrect = false;
      }

      if (isCorrect) {
          setScore(s => s + 20); // 20 pts per round
          setFeedbackText("太棒了！位置完全正確！");
          soundService.playCorrect();
      } else {
          setFeedbackText("再接再厲！看下面的正確答案。");
          soundService.playWrong();
      }

      setGameState('result');
  };

  const handleNextLevel = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
      setRound(1);
      setScore(0);
      setIsFinished(false);
      startRound();
  };

  // Tiered Evaluation
  const getEvaluation = (finalScore: number) => {
      if (finalScore >= 160) return { title: "記憶大師！", desc: "你的空間記憶力超群！" };
      if (finalScore >= 100) return { title: "表現不錯！", desc: "大部分的位置都記住了。" };
      return { title: "繼續加油！", desc: "多練習幾次，你會進步的。" };
  };

  if (isFinished) {
    const evalResult = getEvaluation(score);
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-cyan-50 p-4 animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-cyan-200">
              <Trophy className="w-20 h-20 text-cyan-500 mx-auto mb-4" />
              <h2 className="text-3xl font-bold text-cyan-900 mb-2">{evalResult.title}</h2>
              <div className="text-6xl font-black text-cyan-600 mb-4">{score}</div>
              <p className="text-gray-600 mb-8">
                  {evalResult.desc}
              </p>
              <div className="flex gap-4">
                   <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">
                      回主選單
                  </button>
                  <button onClick={handleRestart} className="flex-1 py-3 bg-cyan-500 text-white rounded-xl font-bold hover:bg-cyan-600 shadow-lg">
                      再玩一次
                  </button>
              </div>
          </div>
      </div>
    );
  }

  if (loading || !level) {
      return <div className="min-h-screen bg-cyan-50 flex items-center justify-center"><Loader2 className="animate-spin text-cyan-500"/></div>;
  }

  // Dynamic sizing logic
  // Use vmin to keep it square and fitting within the smaller dimension of the screen
  const gridContainerStyle = {
      gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
      width: 'min(75vmin, 450px)',
      height: 'min(75vmin, 450px)', 
  };

  // Adjust font size based on grid density to prevent layout break
  const fontSizeClass = level.gridSize > 3 ? 'text-3xl sm:text-5xl' : 'text-4xl sm:text-6xl';

  return (
    <div className="flex flex-col h-screen bg-cyan-50 overflow-hidden relative">
        <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-white rounded-full text-cyan-800 shadow-sm hover:bg-cyan-100">
            <ArrowLeft size={20} />
            </button>
            <div className="flex items-center gap-4">
                {difficulty === 'ADVANCED' && <span className="bg-cyan-600 text-white px-2 py-1 rounded text-xs">進階</span>}
                <div className="text-cyan-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
                <div className="flex items-center bg-cyan-100 px-3 py-1 rounded-full text-cyan-800 font-bold">
                    <Trophy size={16} className="mr-2"/> {score}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 gap-4 sm:gap-12 overflow-hidden">

            {/* Left Side (Landscape): Grid */}
            <div className="flex-none flex items-center justify-center">
                <div 
                    className="grid gap-2 bg-white p-3 rounded-2xl shadow-lg border-4 border-cyan-200"
                    style={gridContainerStyle}
                >
                    {Array.from({ length: level.gridSize * level.gridSize }).map((_, idx) => {
                        let bgColor = "bg-cyan-50";
                        let borderColor = "border-cyan-100";
                        let textColor = "text-cyan-300";

                        if (gameState === 'memorize') {
                            if (level.activeIndices.includes(idx)) {
                                bgColor = "bg-red-500";
                                borderColor = "border-red-600";
                                textColor = "text-transparent"; // Hide text in memorize phase
                            } else {
                                textColor = "text-transparent"; // Hide text in memorize phase
                            }
                        } else if (gameState === 'recall') {
                            if (userSelection.includes(idx)) {
                                bgColor = "bg-cyan-500";
                                borderColor = "border-cyan-600";
                                textColor = "text-white";
                            } else {
                                bgColor = "bg-cyan-50 hover:bg-cyan-100 cursor-pointer";
                            }
                        } else if (gameState === 'result') {
                            const wasCorrect = level.activeIndices.includes(idx);
                            const userSelected = userSelection.includes(idx);

                            if (wasCorrect && userSelected) {
                                bgColor = "bg-green-500"; // Correct hit
                                textColor = "text-white";
                            } else if (wasCorrect && !userSelected) {
                                bgColor = "bg-red-400 opacity-70"; // Missed
                                textColor = "text-white";
                            } else if (!wasCorrect && userSelected) {
                                bgColor = "bg-gray-400"; // Wrong selection
                                textColor = "text-white";
                            }
                        }

                        return (
                            <div 
                                key={idx}
                                onClick={() => handleCellClick(idx)}
                                className={`rounded-lg border-2 transition-all duration-200 ${bgColor} ${borderColor} flex items-center justify-center`}
                            >
                                <span className={`${fontSizeClass} font-black ${textColor} transition-opacity duration-300 select-none`}>
                                    {idx + 1}
                                </span>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* Right Side (Landscape): Controls & Instruction */}
            <div className="flex-none flex flex-col items-center justify-center max-w-sm text-center">
                <h2 className="text-xl sm:text-2xl font-bold text-cyan-900 mb-4 sm:mb-6">
                    {gameState === 'memorize' && <span className="flex flex-col items-center"><Eye className="mb-2 w-8 h-8"/> 記住方塊位置 <br/><span className="text-4xl mt-2 text-red-500">{countdown.toFixed(0)}</span></span>}
                    {gameState === 'recall' && <span className="flex flex-col items-center text-orange-600">點擊剛才的方塊位置</span>}
                    {gameState === 'result' && <span className="text-blue-600 text-3xl">答案揭曉</span>}
                </h2>

                {gameState === 'recall' && (
                    <button 
                        onClick={checkAnswer}
                        disabled={userSelection.length === 0}
                        className="px-8 py-3 sm:py-4 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center text-lg sm:text-xl animate-fade-in"
                    >
                        <Play className="fill-current mr-2 sm:mr-3 w-5 h-5 sm:w-6 sm:h-6"/> 確認答案
                    </button>
                )}

                {gameState === 'result' && (
                    <div className="flex flex-col items-center animate-fade-in-up w-full">
                        <div className={`text-xl font-bold mb-4 sm:mb-6 flex items-center ${feedbackText.includes("棒") ? "text-green-600" : "text-gray-600"}`}>
                             {feedbackText.includes("棒") ? <CheckCircle className="mr-2 w-6 h-6"/> : <XCircle className="mr-2 w-6 h-6"/>}
                             {feedbackText}
                        </div>
                        <button 
                            onClick={handleNextLevel}
                            className="px-8 py-3 sm:py-4 bg-cyan-600 text-white rounded-full font-bold shadow-lg hover:bg-cyan-700 flex items-center text-lg sm:text-xl"
                        >
                            下一題 <ArrowRight className="ml-2 sm:ml-3 w-5 h-5 sm:w-6 sm:h-6"/>
                        </button>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

export default DotGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Trophy, ArrowRight, RotateCcw, CheckCircle } from 'lucide-react';
import { PuzzleLevel, Difficulty } from '../types';
import { generatePuzzleLevel } from '../services/geminiService';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const TOTAL_ROUNDS = 10;

const PuzzleGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [level, setLevel] = useState<PuzzleLevel | null>(null);
  const [currentGrid, setCurrentGrid] = useState<{id: number, content: string}[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [round, setRound] = useState(1);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [isRoundComplete, setIsRoundComplete] = useState(false);

  useEffect(() => {
    startRound();
  }, []);

  const startRound = async () => {
    setLoading(true);
    setIsRoundComplete(false);
    setSelectedIdx(null);

    const data = await generatePuzzleLevel(difficulty as Difficulty);
    setLevel(data);
    setCurrentGrid(data.scrambled);

    setLoading(false);
  };

  const handleTileClick = (index: number) => {
    if (isRoundComplete || !level) return;

    if (selectedIdx === null) {
        // Select first tile
        setSelectedIdx(index);
    } else {
        if (selectedIdx === index) {
            // Deselect
            setSelectedIdx(null);
        } else {
            // Swap
            const newGrid = [...currentGrid];
            const temp = newGrid[selectedIdx];
            newGrid[selectedIdx] = newGrid[index];
            newGrid[index] = temp;
            setCurrentGrid(newGrid);
            setSelectedIdx(null);

            checkWin(newGrid);
        }
    }
  };

  const checkWin = (grid: {id: number, content: string}[]) => {
      if (!level) return;
      // Check if IDs match their index (0, 1, 2...)
      const isCorrect = grid.every((item, idx) => item.id === idx);

      if (isCorrect) {
          soundService.playCorrect();
          setIsRoundComplete(true);
          setScore(s => s + 20);
      }
  };

  const handleNext = () => {
      if (round < TOTAL_ROUNDS) {
          setRound(r => r + 1);
          startRound();
      } else {
          setIsFinished(true);
          soundService.playWin();
      }
  };

  const handleRestart = () => {
    setRound(1);
    setScore(0);
    setIsFinished(false);
    startRound();
  };

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-teal-50 p-4 animate-fade-in">
        <div className="bg-white p-8 rounded-3xl shadow-xl text-center max-w-sm w-full border-4 border-teal-200">
          <Trophy className="w-20 h-20 text-teal-500 mx-auto mb-4" />
          <h2 className="text-3xl font-bold text-teal-900 mb-2">拼圖大師！</h2>
          <div className="text-6xl font-black text-teal-600 mb-4">{score}</div>
          <p className="text-gray-600 mb-8">你的空間概念很棒！</p>
          <div className="flex gap-4">
            <button onClick={onBack} className="flex-1 py-3 bg-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-300">回主選單</button>
            <button onClick={handleRestart} className="flex-1 py-3 bg-teal-500 text-white rounded-xl font-bold hover:bg-teal-600 shadow-lg">再玩一次</button>
          </div>
        </div>
      </div>
    );
  }

  if (loading || !level) {
    return <div className="min-h-screen bg-teal-50 flex items-center justify-center"><Loader2 className="animate-spin text-teal-500 w-12 h-12" /></div>;
  }

  const gridStyle = {
      gridTemplateColumns: `repeat(${level.gridSize}, 1fr)`,
  };

  const rowStyle = {
      gridTemplateRows: `repeat(${level.gridSize}, 1fr)`,
  };

  const labels = ['A', 'B', 'C'].slice(0, level.gridSize);
  const rows = [1, 2, 3].slice(0, level.gridSize);

  // Dynamic Font Size for tiles based on grid density
  const fontSize = level.gridSize > 2 ? 'text-3xl sm:text-4xl' : 'text-4xl sm:text-5xl';

  return (
    <div className="flex flex-col h-screen bg-teal-50 overflow-hidden relative">
      {/* Header - Compact */}
      <div className="flex-none px-4 py-2 flex justify-between items-center bg-white/80 backdrop-blur-sm shadow-sm z-10 h-14">
        <button onClick={onBack} className="p-2 bg-white rounded-full text-teal-800 shadow-sm hover:bg-teal-100"><ArrowLeft size={20} /></button>
        <div className="flex items-center gap-4">
          {difficulty === 'ADVANCED' && <span className="bg-teal-600 text-white px-2 py-1 rounded text-xs">進階</span>}
          <div className="text-teal-800 font-bold">第 {round} / {TOTAL_ROUNDS} 題</div>
          <div className="flex items-center bg-teal-100 px-3 py-1 rounded-full text-teal-800 font-bold"><Trophy size={16} className="mr-2"/> {score}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-1 w-full h-full overflow-hidden">

        {/* Title: Hidden on small height screens (landscape phones) to save vertical space */}
        <div className="text-center shrink-0 hidden sm:block h-8">
            <h2 className="text-lg font-bold text-teal-900">還原圖片</h2>
        </div>

        {/* Main Content Area */}
        <div className="flex flex-row items-center justify-center gap-2 sm:gap-12 w-full h-full max-h-[85vh]">

            {/* Target Preview (Left) - Increased Size */}
            <div className="bg-white p-2 rounded-xl shadow-md border-2 border-teal-100 shrink-0 flex flex-col items-center justify-center">
                <div className="text-xs text-center text-gray-400 mb-1 font-bold">目標</div>
                <div className="grid gap-1 w-[28vmin] h-[28vmin] max-w-[180px] max-h-[180px] min-w-[100px] min-h-[100px]" style={gridStyle}>
                    {level.targetImage.map((item, idx) => (
                        <div key={idx} className="bg-gray-100 flex items-center justify-center text-3xl sm:text-4xl rounded">
                            {item}
                        </div>
                    ))}
                </div>
            </div>

            {/* Main Game Grid with Coordinates (Right) */}
            <div className="flex flex-col items-center shrink-0">
                {/* Column Labels (Top) */}
                <div className="flex pl-6 mb-1 w-full justify-around">
                    {labels.map((label) => (
                        <div key={label} className="flex-1 text-center font-bold text-teal-700 text-base sm:text-lg">
                            {label}
                        </div>
                    ))}
                </div>

                <div className="flex items-center">
                    {/* Row Labels (Left) - Use Grid to match alignment exactly */}
                    <div className="grid gap-1 w-6 pr-1 h-[55vmin] max-h-[350px] min-h-[200px]" style={rowStyle}>
                        {rows.map((r) => (
                            <div key={r} className="flex items-center justify-center font-bold text-teal-700 text-base sm:text-lg">
                                {r}
                            </div>
                        ))}
                    </div>

                    {/* The Interactive Grid */}
                    {/* Using vmin ensures it scales down on short landscape screens to avoid cropping */}
                    <div 
                        className={`grid gap-1 bg-white p-2 rounded-xl shadow-xl border-4 ${isRoundComplete ? 'border-green-400' : 'border-teal-200'} w-[55vmin] h-[55vmin] max-w-[350px] max-h-[350px] min-w-[200px] min-h-[200px] transition-all`} 
                        style={gridStyle}
                    >
                        {currentGrid.map((tile, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleTileClick(idx)}
                                disabled={isRoundComplete}
                                className={`
                                    rounded-lg flex items-center justify-center ${fontSize} transition-all duration-300
                                    ${selectedIdx === idx ? 'bg-yellow-100 ring-4 ring-yellow-300 scale-95 z-10' : 'bg-gray-50 hover:bg-gray-100'}
                                    ${isRoundComplete ? 'bg-green-50' : ''}
                                `}
                            >
                                {tile.content}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Feedback / Controls Footer */}
        <div className="h-14 flex items-center justify-center relative w-full shrink-0 mt-1">
            {isRoundComplete ? (
                <div className="flex items-center gap-4 animate-fade-in-up z-20">
                    <div className="bg-green-100 border-green-500 text-green-700 px-4 py-1.5 rounded-full font-bold shadow-md flex items-center gap-2 border-2 whitespace-nowrap">
                        <CheckCircle size={20} />
                        <span className="text-base">答對了！</span>
                    </div>
                    <button 
                        onClick={handleNext}
                        className="px-6 py-1.5 bg-teal-600 text-white rounded-full font-bold shadow-lg hover:bg-teal-700 flex items-center text-base"
                    >
                        下一題 <ArrowRight className="ml-2 w-4 h-4"/>
                    </button>
                </div>
            ) : (
                <p className="text-teal-600 text-sm animate-pulse bg-white/50 px-4 py-1 rounded-full">點擊兩個方塊交換位置</p>
            )}
        </div>

      </div>
    </div>
  );
};

