                levels.push({ sequence: seq.map(String), options: [String(start+3), String(start+4), String(start+2)], answer: String(start + 3) });
            } else {
                const a = shapes[i % shapes.length];
                const b = shapes[(i + 1) % shapes.length];
                const c = shapes[(i + 2) % shapes.length];
                const d = shapes[(i + 3) % shapes.length];
                levels.push({ sequence: [a, b, c, "?"], options: [b, c, d], answer: d });
            }
        } else {
             const type = i % 4;
            if (type === 0) {
                const a = shapes[i % shapes.length];
