                    answer: String(start + step*4) 
                });
            } else if (type === 2) {
                const start = (i % 3) + 1;
                levels.push({
                    sequence: [String(start), String(start*2), String(start*4), String(start*8), "?"],
                    options: [String(start*16), String(start*10), String(start*12)],
