const generateMarketData = (difficulty: 'NORMAL' | 'ADVANCED', count: number): MarketLevel[] => {
    const levels: MarketLevel[] = [];
    const itemsList = [
        {name: "蘋果", icon: "🍎"}, {name: "香蕉", icon: "🍌"}, {name: "麵包", icon: "🍞"}, {name: "牛奶", icon: "🥛"},
