const SOUND_TYPES = ['HIGH', 'LOW', 'RISE', 'FALL', 'ALARM', 'GAME', 'BOUNCE', 'MAGIC', 'TELEPHONE'] as const;

const SOUND_TARGETS: Record<string, {icon: string, label: string}[]> = {
    'HIGH': [{icon: "🐦", label: "小鳥"}, {icon: "🐭", label: "老鼠"}, {icon: "🔔", label: "鈴鐺"}],
    'LOW': [{icon: "🦁", label: "獅子"}, {icon: "🥁", label: "大鼓"}, {icon: "🚢", label: "大船"}],
    'RISE': [{icon: "🚀", label: "升空"}, {icon: "🎈", label: "氣球飛起"}, {icon: "📈", label: "上升"}],
    'FALL': [{icon: "📉", label: "下降"}, {icon: "🛝", label: "溜滑梯"}, {icon: "🍂", label: "落葉"}],
    'ALARM': [{icon: "⏰", label: "鬧鐘"}, {icon: "🚒", label: "消防車"}, {icon: "🚑", label: "救護車"}],
    'GAME': [{icon: "🎮", label: "電動玩具"}, {icon: "👾", label: "外星人"}, {icon: "🤖", label: "機器人"}],
    'BOUNCE': [{icon: "🏀", label: "拍球"}, {icon: "🦘", label: "袋鼠"}, {icon: "🐇", label: "兔子"}],
    'MAGIC': [{icon: "🪄", label: "魔法棒"}, {icon: "✨", label: "亮晶晶"}, {icon: "🧚", label: "仙子"}],
    'TELEPHONE': [{icon: "☎️", label: "電話"}, {icon: "📱", label: "手機"}, {icon: "📠", label: "傳真機"}]
};

const generateSoundLevels = (count: number): SoundLevel[] => {
    const levels: SoundLevel[] = [];
    for(let i=0; i<count; i++) {
        const type = SOUND_TYPES[i % SOUND_TYPES.length];
        const correctPool = SOUND_TARGETS[type];
        const correctItem = correctPool[i % correctPool.length];

        const distractors = [];
        while(distractors.length < 3) {
            const dtype = SOUND_TYPES[Math.floor(Math.random() * SOUND_TYPES.length)];
            if (dtype !== type) {
                const dpool = SOUND_TARGETS[dtype];
                const dItem = dpool[Math.floor(Math.random() * dpool.length)];
                if (!distractors.some(d => d.label === dItem.label)) {
                    distractors.push({ ...dItem, isCorrect: false });
                }
            }
        }

        levels.push({
            soundType: type,
            targetIcon: correctItem.icon,
            options: [
                { ...correctItem, isCorrect: true },
                ...distractors
            ]
        });
    }
    return levels;
};

