        ["🌲", "🌳", "🌴", "🌵", "🌷", "🌸", "🌹", "🌺", "🌻"] 
    ];

    if (difficulty === 'ADVANCED') {
        pools = pools.filter(p => p[0] !== "1️⃣");
    }

    for(let i=0; i<count; i++) {
        const pool = pools[i % pools.length];
        const shuffledPool = [...pool].sort(() => 0.5 - Math.random());
        const target = shuffledPool.slice(0, numTiles);
        levels.push({
            gridSize,
            targetImage: target,
            scrambled: [] 
        });
    }
    return levels;
};

