            const d1 = `${(hour % 12) + 1}:${minOption === 0 ? '00' : '30'}`;
            const d2 = `${hour}:${minOption === 0 ? '30' : '00'}`;
            levels.push({
                type: 'CLOCK',
                question: "現在是幾點？",
                clockTime: { hour: hour, minute: minOption },
                options: [timeStr, d1, d2],
                correctAnswer: timeStr
            });
        } else {
             // ADVANCED TIME LOGIC
             const type = i % 4;
            if (type === 0) { // Duration Calculation (Complex)
                const startH = Math.floor(Math.random() * 5) + 8; // 8 to 12
                const startM = Math.random() > 0.5 ? 10 : 20;
                const durH = 1;
                const durM = Math.random() > 0.5 ? 20 : 30;
                // Ex: 8:10 + 1hr 20min = 9:30. Dur = 80min.
                // Q: 8:10 到 9:30 經過多久？
                const endM = startM + durM;
                const endH = startH + durH;

                levels.push({
                    type: 'MATH',
                    question: `從 ${startH}:${startM} 到 ${endH}:${endM}，經過多久？`,
                    options: [`1小時${durM}分`, `1小時${durM-10}分`, `2小時`],
                    correctAnswer: `1小時${durM}分`
                });
            } else if (type === 1) { // Backwards Planning
                // Ex: Arrive at 12:00. Takes 30 mins. When leave? -> 11:30
                const arriveH = Math.floor(Math.random() * 5) + 12;
                const duration = 30;
                const leaveH = arriveH - 1;
                const leaveM = 30;

                levels.push({
                    type: 'MATH',
                    question: `要在 ${arriveH}:00 到達，車程 30 分鐘，幾點要出發？`,
                    options: [`${leaveH}:30`, `${arriveH}:30`, `${leaveH}:00`],
                    correctAnswer: `${leaveH}:30`
                });
            } else if (type === 2) { // Cross-hour Addition
                // Ex: 9:50 + 40 mins = 10:30
                const h = Math.floor(Math.random() * 5) + 8;
                const m = 50;
                const add = 40;
                const endH = h + 1;
                const endM = 30;

                levels.push({
                    type: 'MATH',
                    question: `現在 ${h}:${m}，再過 ${add} 分鐘是幾點？`,
                    options: [`${endH}:${endM}`, `${h}:${m+add}`, `${endH}:00`],
                    correctAnswer: `${endH}:${endM}`
                });
            } else { // 24H to 12H (Classic but tricky for some)
                const pm = Math.floor(Math.random() * 9) + 1; // 1 to 9
                const h24 = pm + 12; // 13 to 21
                levels.push({
                    type: 'MATH',
                    question: `24小時制的 ${h24}:00 是下午幾點？`,
                    options: [`下午 ${pm} 點`, `下午 ${pm+1} 點`, `上午 ${pm} 點`],
                    correctAnswer: `下午 ${pm} 點`
                });
            }
        }
    }
    return levels;
};

