                        type: 'MATH',
                        question: `從 ${startH}:${startM.toString().padStart(2, '0')} 到 ${endH}:${endM.toString().padStart(2, '0')}，經過多久？`,
                        options: [`${durH}小時${durM}分`, `${durH}小時${durM-10}分`, `${durH+1}小時`],
                        correctAnswer: `${durH}小時${durM}分`
                    };
                }

            } else if (type === 1) { // Backwards Planning
                const arriveH = Math.floor(Math.random() * 8) + 10; // 10 to 17
                const duration = [30, 45, 15, 20, 40][Math.floor(Math.random() * 5)];
                // Calculate leave time
                const totalMinArrive = arriveH * 60;
                const totalMinLeave = totalMinArrive - duration;
                const leaveH = Math.floor(totalMinLeave / 60);
                const leaveM = totalMinLeave % 60;

                newLevel = {
                    type: 'MATH',
                    question: `要在 ${arriveH}:00 到達，車程 ${duration} 分鐘，幾點要出發？`,
                    options: [
                        `${leaveH}:${leaveM.toString().padStart(2, '0')}`, 
                        `${leaveH}:${(leaveM+10)%60 === 0 ? '00': (leaveM+10)}`, 
                        `${arriveH}:${duration}`
                    ],
                    correctAnswer: `${leaveH}:${leaveM.toString().padStart(2, '0')}`
                };

            } else if (type === 2) { // Cross-hour Addition
                const h = Math.floor(Math.random() * 10) + 7;
                const m = [40, 45, 50, 55][Math.floor(Math.random() * 4)]; // High minutes
                const add = [20, 25, 30, 15][Math.floor(Math.random() * 4)]; // Add enough to cross hour

                const totalMin = m + add;
                const endH = h + Math.floor(totalMin / 60);
                const endM = totalMin % 60;

                newLevel = {
                    type: 'MATH',
                    question: `現在 ${h}:${m}，再過 ${add} 分鐘是幾點？`,
                    options: [
                        `${endH}:${endM.toString().padStart(2, '0')}`, 
                        `${h}:${(m+add) >= 60 ? (m+add)-60 : m+add}`, 
                        `${endH}:${(endM+10)%60 === 0 ? '00' : endM+10}`
                    ],
                    correctAnswer: `${endH}:${endM.toString().padStart(2, '0')}`
                };

            } else { // 24H to 12H (Classic)
                const pm = Math.floor(Math.random() * 11) + 1; // 1 to 11
                const h24 = pm + 12;
                newLevel = {
                    type: 'MATH',
                    question: `24小時制的 ${h24}:00 是下午幾點？`,
                    options: [`下午 ${pm} 點`, `下午 ${pm === 12 ? 1 : pm+1} 點`, `上午 ${pm} 點`],
                    correctAnswer: `下午 ${pm} 點`
                };
            }
        }

        // Uniqueness Check
        if (newLevel) {
            // For NORMAL mode, we might allow duplicates if clock time is same, but let's try to uniquify by question text + clock/answer
            const signature = difficulty === 'NORMAL' 
                ? `${newLevel.clockTime?.hour}:${newLevel.clockTime?.minute}`
                : newLevel.question;

            if (!usedQuestions.has(signature)) {
                usedQuestions.add(signature);
                levels.push(newLevel);
            }
        }
    }
    return levels;
};

