// Updated Time Levels with Harder Advanced Logic and GUARANTEED UNIQUENESS
const generateTimeLevels = (count: number, difficulty: 'NORMAL' | 'ADVANCED'): TimeLevel[] => {
    const levels: TimeLevel[] = [];
    // Set to track question strings to prevent duplicates
    const usedQuestions = new Set<string>();

    let attempts = 0;
    while (levels.length < count && attempts < 10000) {
        attempts++;
        let newLevel: TimeLevel | null = null;

        if (difficulty === 'NORMAL') {
            const hour = Math.floor(Math.random() * 12) + 1;
            const minOption = Math.random() > 0.5 ? 0 : 30;
            const timeStr = `${hour}:${minOption === 0 ? '00' : '30'}`;

            // Distractors: Distinct from answer
            const distractorSet = new Set<string>();
            distractorSet.add(timeStr);

            // Try adding d1
            const d1 = `${(hour % 12) + 1}:${minOption === 0 ? '00' : '30'}`;
            distractorSet.add(d1);

            // Try adding d2
            const d2 = `${hour}:${minOption === 0 ? '30' : '00'}`;
            distractorSet.add(d2);

            // If we have duplicates (e.g. 12+1 = 1, but random selected 1), fill up
            while(distractorSet.size < 3) {
                const rH = Math.floor(Math.random() * 12) + 1;
                const rM = Math.random() > 0.5 ? 0 : 30;
                distractorSet.add(`${rH}:${rM === 0 ? '00' : '30'}`);
            }

            const options = Array.from(distractorSet);

            newLevel = {
                type: 'CLOCK',
                question: "現在是幾點？",
                clockTime: { hour: hour, minute: minOption },
                options: options,
                correctAnswer: timeStr
            };
        } else {
             // ADVANCED TIME LOGIC
             const type = Math.floor(Math.random() * 4); // Use Random for mix

            if (type === 0) { // Duration Calculation (Complex)
                const startH = Math.floor(Math.random() * 10) + 6; // 6 AM to 3 PM
                const startM = Math.floor(Math.random() * 6) * 10; // 00, 10, 20...
                const durH = Math.floor(Math.random() * 2) + 1; // 1 or 2 hrs
                const durM = Math.floor(Math.random() * 6) * 10; // 00, 10...50

                let answer = "";
                let qStr = "";

                // Avoid simple cases
                if (durM === 0) {
                     // Force some minutes
                     const extra = Math.random() > 0.5 ? 15 : 45;
                     qStr = `從 ${startH}:${startM.toString().padStart(2, '0')} 到 ${startH+durH}:${(startM+extra)%60 === 0 ? '00' : (startM+extra)%60}，經過多久？`;
                     answer = `${durH}小時${extra}分`;
                } else {
                    const endMTotal = startM + durM;
                    const endH = startH + durH + Math.floor(endMTotal / 60);
                    const endM = endMTotal % 60;
                    qStr = `從 ${startH}:${startM.toString().padStart(2, '0')} 到 ${endH}:${endM.toString().padStart(2, '0')}，經過多久？`;
                    answer = `${durH}小時${durM}分`;
                }

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                // Smart distractors
                distractorSet.add(`${durH}小時${Math.max(0, durM-10)}分`); // Similar
                distractorSet.add(`${durH+1}小時`); // Different hour

                // Ensure unique
                while(distractorSet.size < 3) {
                    distractorSet.add(`${Math.floor(Math.random()*3)+1}小時${Math.floor(Math.random()*6)*10}分`);
                }

                newLevel = {
                    type: 'MATH',
                    question: qStr,
                    options: Array.from(distractorSet),
                    correctAnswer: answer
                };

            } else if (type === 1) { // Backwards Planning
                const arriveH = Math.floor(Math.random() * 8) + 10; // 10 to 17
                const duration = [30, 45, 15, 20, 40][Math.floor(Math.random() * 5)];
                // Calculate leave time
                const totalMinArrive = arriveH * 60;
                const totalMinLeave = totalMinArrive - duration;
                const leaveH = Math.floor(totalMinLeave / 60);
                const leaveM = totalMinLeave % 60;

                const answer = `${leaveH}:${leaveM.toString().padStart(2, '0')}`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${leaveH}:${(leaveM+10)%60 === 0 ? '00': (leaveM+10)}`);
                distractorSet.add(`${arriveH}:${duration}`); // Trick option

                while(distractorSet.size < 3) {
                     distractorSet.add(`${leaveH}:${Math.floor(Math.random()*6)*10}`);
                }

                newLevel = {
                    type: 'MATH',
                    question: `要在 ${arriveH}:00 到達，車程 ${duration} 分鐘，幾點要出發？`,
                    options: Array.from(distractorSet),
                    correctAnswer: answer
                };

            } else if (type === 2) { // Cross-hour Addition
                const h = Math.floor(Math.random() * 10) + 7;
                const m = [40, 45, 50, 55][Math.floor(Math.random() * 4)]; // High minutes
                const add = [20, 25, 30, 15][Math.floor(Math.random() * 4)]; // Add enough to cross hour

                const totalMin = m + add;
                const endH = h + Math.floor(totalMin / 60);
                const endM = totalMin % 60;

                const answer = `${endH}:${endM.toString().padStart(2, '0')}`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${h}:${(m+add) >= 60 ? (m+add)-60 : m+add}`); // Forget hour carry
                distractorSet.add(`${endH}:${(endM+10)%60 === 0 ? '00' : endM+10}`);

                while(distractorSet.size < 3) {
                    distractorSet.add(`${endH}:${Math.floor(Math.random()*6)*10}`);
                }

                newLevel = {
                    type: 'MATH',
                    question: `現在 ${h}:${m}，再過 ${add} 分鐘是幾點？`,
                    options: Array.from(distractorSet),
                    correctAnswer: answer
                };

            } else { // 24H to 12H (Classic)
                const pm = Math.floor(Math.random() * 11) + 1; // 1 to 11
                const h24 = pm + 12;
                const answer = `下午 ${pm} 點`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`下午 ${pm === 12 ? 1 : pm+1} 點`);
                distractorSet.add(`上午 ${pm} 點`);

                newLevel = {
                    type: 'MATH',
                    question: `24小時制的 ${h24}:00 是下午幾點？`,
                    options: Array.from(distractorSet),
                    correctAnswer: answer
                };
            }
        }

        // Uniqueness Check
        if (newLevel) {
            // For NORMAL mode, we might allow duplicates if clock time is same, but let's try to uniquify by question text + clock/answer
            const signature = difficulty === 'NORMAL' 
                ? `${newLevel.clockTime?.hour}:${newLevel.clockTime?.minute}`
                : newLevel.question;

            if (!usedQuestions.has(signature)) {
                usedQuestions.add(signature);
                levels.push(newLevel);
            }
        }
    }
    return levels;
};

