// Completely rewritten Pattern Logic (No Alphabet, Harder Advanced)
const generatePatterns = (count: number, difficulty: 'NORMAL' | 'ADVANCED'): PatternLevel[] => {
    const levels: PatternLevel[] = [];
    const usedSignatures = new Set<string>(); // To track unique (sequence + answer)

    // Expanded symbol sets
    const shapes = ["🔵", "🟩", "🔺", "🟨", "⭐", "🔶", "💜", "⬛", "🔷", "💠"];
    const rotations = ["⬆️", "➡️", "⬇️", "⬅️"]; // Clockwise
    const phases = ["🌑", "🌒", "🌓", "🌔", "🌕"];

    let attempts = 0;
    while (levels.length < count && attempts < 10000) {
        attempts++;
        let sequence: string[] = [];
        let answer = "";
        let options: string[] = [];
        let type = 0;

        if (difficulty === 'NORMAL') {
            type = Math.floor(Math.random() * 3);
            if (type === 0) { // ABAB
                const a = shapes[Math.floor(Math.random() * shapes.length)];
                let b = shapes[Math.floor(Math.random() * shapes.length)];
                while(b === a) b = shapes[Math.floor(Math.random() * shapes.length)];
                sequence = [a, b, a, "?"];
                answer = b;

                // Ensure unique options
                const distractorSet = new Set<string>();
                distractorSet.add(answer); // Always add answer first
                distractorSet.add(a);
                while(distractorSet.size < 3) {
                    const r = shapes[Math.floor(Math.random() * shapes.length)];
                    distractorSet.add(r);
                }
                options = Array.from(distractorSet);

            } else if (type === 1) { // 123 Number
                const start = Math.floor(Math.random() * 50);
                sequence = [String(start), String(start + 1), String(start + 2), "?"];
                answer = String(start + 3);
                // Unique numeric options
                options = [answer, String(start + 4), String(start + 5)];

            } else { // ABC Shape
                const startIdx = Math.floor(Math.random() * (shapes.length - 3));
                const a = shapes[startIdx];
                const b = shapes[startIdx+1];
                const c = shapes[startIdx+2];
                sequence = [a, b, c, "?"];
                answer = shapes[(startIdx+3) % shapes.length];
                // Options: b, c, answer. Ensure distinct.
                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(b);
                distractorSet.add(c);
                while(distractorSet.size < 3) {
                     distractorSet.add(shapes[Math.floor(Math.random() * shapes.length)]);
                }
                options = Array.from(distractorSet);
            }
        } else { // ADVANCED - Harder patterns, NO Alphabet
             type = Math.floor(Math.random() * 4);

             if (type === 0) { // Rotation / Direction (Clockwise)
                 const start = Math.floor(Math.random() * 4);
                 // e.g., Up, Right, Down, ? -> Left
                 sequence = [rotations[start], rotations[(start+1)%4], rotations[(start+2)%4], "?"];
                 answer = rotations[(start+3)%4];
                 // Options: answer + other directions. There are only 4 directions total.
                 const distractorSet = new Set<string>();
                 distractorSet.add(answer);
                 rotations.forEach(r => distractorSet.add(r));
                 // Pick 3 from the 4 available
                 options = Array.from(distractorSet).slice(0, 3);

             } else if (type === 1) { // Complex Math
                 const subType = Math.random();
                 let dist1, dist2;

                 if (subType < 0.33) { // Variable Addition (+2, +3, +4)
                     const start = Math.floor(Math.random() * 20);
                     sequence = [String(start), String(start+2), String(start+5), String(start+9), "?"];
                     answer = String(start+14); // +5
                     dist1 = String(start+13); // +4 error
                     dist2 = String(start+15); // +6 error
                 } else if (subType < 0.66) { // Geometric (*2 or *3)
                     const base = Math.random() > 0.5 ? 2 : 3;
                     const start = Math.floor(Math.random() * 3) + 1; 
                     sequence = [String(start), String(start*base), String(start*base*base), "?"];
                     answer = String(start*base*base*base);
                     dist1 = String(start*base*base + base); // Additive error
                     dist2 = String(start*base*base*2); // Wrong multiplier error
                 } else { // Subtraction large
                     const start = 100;
                     const minus = Math.floor(Math.random() * 5 + 5); // 5 to 10
                     sequence = [String(start), String(start-minus), String(start-minus*2), "?"];
                     answer = String(start-minus*3);
                     dist1 = String(start-minus*3 + 2);
                     dist2 = String(start-minus*3 - 2);
                 }
                 // Set ensures uniqueness
                 const distractorSet = new Set<string>();
                 distractorSet.add(answer);
                 distractorSet.add(dist1);
                 distractorSet.add(dist2);
                 // Fallback
                 while(distractorSet.size < 3) {
                     distractorSet.add(String(parseInt(answer) + Math.floor(Math.random() * 10) + 1));
                 }
                 options = Array.from(distractorSet);

             } else if (type === 2) { // Interleaved (A B A C A ?) -> D
                 // Harder interleaving: 1, 10, 2, 20, 3, ? -> 30
                 const a = Math.floor(Math.random() * 5) + 1;
                 sequence = [String(a), String(a*10), String(a+1), String((a+1)*10), String(a+2), "?"];
                 answer = String((a+2)*10);

                 const distractorSet = new Set<string>();
                 distractorSet.add(answer);
                 distractorSet.add(String(a+3)); // Just +1
                 distractorSet.add(String((a+1)*10 + 10)); // Wrong base
                 while(distractorSet.size < 3) {
                     distractorSet.add(String(Math.floor(Math.random() * 100)));
                 }
                 options = Array.from(distractorSet);

             } else { // Phases / Complex Symbols
                 const start = Math.floor(Math.random() * 2); 
                 // 🌑 🌒 🌓 ? -> 🌔
                 sequence = [phases[start], phases[start+1], phases[start+2], "?"];
                 answer = phases[start+3];

                 const distractorSet = new Set<string>();
                 distractorSet.add(answer);
                 distractorSet.add(phases[start]);
                 distractorSet.add(phases[start+4] || phases[0]);
                 while(distractorSet.size < 3) {
                     distractorSet.add(phases[Math.floor(Math.random() * phases.length)]);
                 }
                 options = Array.from(distractorSet);
             }
        }

        // Shuffle options
        options.sort(() => 0.5 - Math.random());
        // Double check size
        while(options.length < 3) {
             if (difficulty === 'NORMAL') options.push("?"); 
             else options.push(shapes[Math.floor(Math.random() * shapes.length)]);
             options = Array.from(new Set(options));
        }

        const signature = JSON.stringify({ s: sequence, a: answer });
        if (!usedSignatures.has(signature)) {
            usedSignatures.add(signature);
            levels.push({ sequence, options, answer });
        }
    }
    return levels;
};

