// Updated Time Levels with Harder Advanced Logic and GUARANTEED UNIQUENESS
const generateTimeLevels = (count: number, difficulty: 'NORMAL' | 'ADVANCED'): TimeLevel[] => {
    const levels: TimeLevel[] = [];
    // Set to track question strings to prevent duplicates
    const usedQuestions = new Set<string>();

    let attempts = 0;
    while (levels.length < count && attempts < 10000) {
        attempts++;
        let newLevel: TimeLevel | null = null;

        if (difficulty === 'NORMAL') {
            const hour = Math.floor(Math.random() * 12) + 1;
            const minOption = Math.random() > 0.5 ? 0 : 30;
            const timeStr = `${hour}:${minOption === 0 ? '00' : '30'}`;

            // Distractors: Distinct from answer
            const distractorSet = new Set<string>();
            distractorSet.add(timeStr);

            // Try adding d1
            const d1 = `${(hour % 12) + 1}:${minOption === 0 ? '00' : '30'}`;
            distractorSet.add(d1);

            // Try adding d2
            const d2 = `${hour}:${minOption === 0 ? '30' : '00'}`;
            distractorSet.add(d2);

            // If we have duplicates (e.g. 12+1 = 1, but random selected 1), fill up
            while(distractorSet.size < 3) {
                const rH = Math.floor(Math.random() * 12) + 1;
                const rM = Math.random() > 0.5 ? 0 : 30;
                distractorSet.add(`${rH}:${rM === 0 ? '00' : '30'}`);
            }

            const options = Array.from(distractorSet);

            newLevel = {
                type: 'CLOCK',
                question: "現在是幾點？",
                clockTime: { hour: hour, minute: minOption },
                options: options,
                correctAnswer: timeStr
            };
        } else {
             // ADVANCED TIME LOGIC - REAL LIFE SCENARIOS
             const type = Math.floor(Math.random() * 4); // Use Random for mix

            if (type === 0) { // Medical / Schedule (Intervals)
                const startH = Math.floor(Math.random() * 4) + 6; // 6 to 9 AM
                const interval = [4, 6, 8][Math.floor(Math.random() * 3)];
                const dose = 3; // Ask for 3rd dose
                // 1st: startH, 2nd: startH+interval, 3rd: startH+interval*2
                const answerH = startH + (interval * (dose - 1));
                const answer = `${answerH}:00`;

                const qStr = `醫生說藥每 ${interval} 小時吃一次，第一次是早上 ${startH}:00 吃，請問第三次吃藥是幾點？`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${startH + interval}:00`); // 2nd dose error
                distractorSet.add(`${answerH + interval}:00`); // 4th dose error
                distractorSet.add(`${answerH - 1}:00`); // Calculation error

                newLevel = {
                    type: 'MATH',
                    question: qStr,
                    options: Array.from(distractorSet).slice(0, 3),
                    correctAnswer: answer
                };

            } else if (type === 1) { // Travel / Commute (Deadline)
                const arriveH = Math.floor(Math.random() * 3) + 9; // 9, 10, 11 AM
                const arriveM = [0, 30][Math.floor(Math.random()*2)];
                const travelM = [45, 50, 70, 90][Math.floor(Math.random()*4)]; // Harder subtraction

                // Calculate leave time
                const totalArrive = arriveH * 60 + arriveM;
                const totalLeave = totalArrive - travelM;
                const leaveH = Math.floor(totalLeave / 60);
                const leaveM = totalLeave % 60;

                const answer = `${leaveH}:${leaveM.toString().padStart(2, '0')}`;

                const qStr = `要在 ${arriveH}:${arriveM.toString().padStart(2, '0')} 抵達醫院，車程 ${travelM} 分鐘，最晚幾點要出門？`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${leaveH}:${(leaveM+10)%60 === 0 ? '00': (leaveM+10)}`); // slightly off
                distractorSet.add(`${leaveH+1}:${leaveM.toString().padStart(2, '0')}`); // hour off

                newLevel = {
                    type: 'MATH',
                    question: qStr,
                    options: Array.from(distractorSet).slice(0, 3),
                    correctAnswer: answer
                };

            } else if (type === 2) { // Cooking / Timer (Elapsed)
                const nowH = Math.floor(Math.random() * 5) + 14; // 14:00 - 18:00
                const nowM = Math.floor(Math.random() * 6) * 10;
                const duration = [25, 35, 45, 90][Math.floor(Math.random() * 4)];

                const total = nowH * 60 + nowM + duration;
                const endH = Math.floor(total / 60);
                const endM = total % 60;

                const answer = `${endH}:${endM.toString().padStart(2, '0')}`;
                const qStr = `現在是 ${nowH}:${nowM.toString().padStart(2, '0')}，湯還要燉 ${duration} 分鐘，請問幾點可以好？`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${endH}:${(endM+10)%60 === 0 ? '00' : endM+10}`);
                distractorSet.add(`${nowH}:${(nowM+duration)%60 === 0 ? '00' : (nowM+duration)%60}`); // Forget hour carry logic often produces this

                newLevel = {
                    type: 'MATH',
                    question: qStr,
                    options: Array.from(distractorSet).slice(0, 3),
                    correctAnswer: answer
                };

            } else { // TV/Movie Schedule (Duration)
                const startH = Math.floor(Math.random() * 3) + 19; // 19, 20, 21
                const startM = [0, 15, 30][Math.floor(Math.random()*3)];
                const endH = startH + 2;
                const endM = (startM + 15) % 60; // 2h 15m duration approx

                const qStr = `電影從 ${startH}:${startM.toString().padStart(2, '0')} 演到 ${endH}:${endM.toString().padStart(2, '0')}，請問演了多久？`;

                // Calc duration
                const totalStart = startH * 60 + startM;
                const totalEnd = endH * 60 + endM;
                const diff = totalEnd - totalStart;
                const diffH = Math.floor(diff / 60);
                const diffM = diff % 60;

                const answer = `${diffH}小時${diffM}分`;

                const distractorSet = new Set<string>();
                distractorSet.add(answer);
                distractorSet.add(`${diffH}小時${diffM+15}分`);
                distractorSet.add(`${diffH-1}小時${diffM}分`);

                newLevel = {
                    type: 'MATH',
                    question: qStr,
                    options: Array.from(distractorSet).slice(0, 3),
                    correctAnswer: answer
                };
            }
        }

        // Uniqueness Check
        if (newLevel) {
            const signature = newLevel.question; // Strict string check for advanced
            if (!usedQuestions.has(signature)) {
                usedQuestions.add(signature);
                levels.push(newLevel);
            }
        }
    }
    return levels;
};

