  EMOTION = 'EMOTION',
  PATTERN = 'PATTERN',
  TIME = 'TIME',
  ODD_ONE = 'ODD_ONE',
  SOUND = 'SOUND',
  PUZZLE = 'PUZZLE',
  // Board Games
  GOMOKU = 'GOMOKU',
  DARK_CHESS = 'DARK_CHESS',
  CONNECT_FOUR = 'CONNECT_FOUR',
  OTHELLO = 'OTHELLO'
}

