import React, { useState, useEffect, useCallback } from 'react';
import { ArrowLeft, RefreshCw, Trophy } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const GRID_SIZE = 10;
const CELL_EMPTY = 0;
const CELL_PLAYER = 1; // Black
const CELL_AI = 2;     // White

const GomokuGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<number[][]>([]);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true);
  const [winner, setWinner] = useState<number | null>(null); // 0: null, 1: Player, 2: AI, 3: Draw
  const [winningLine, setWinningLine] = useState<{r:number, c:number}[]>([]);

  useEffect(() => {
    resetGame();
  }, []);

  const resetGame = () => {
    const newBoard = Array(GRID_SIZE).fill(0).map(() => Array(GRID_SIZE).fill(CELL_EMPTY));
    setBoard(newBoard);
    setIsPlayerTurn(true); // Player (Black) always starts first in this simplified version
    setWinner(null);
    setWinningLine([]);
  };

  const checkWin = (currentBoard: number[][], player: number) => {
    const directions = [
      [0, 1],  // Horizontal
      [1, 0],  // Vertical
      [1, 1],  // Diagonal \
      [1, -1]  // Diagonal /
    ];

    for (let r = 0; r < GRID_SIZE; r++) {
      for (let c = 0; c < GRID_SIZE; c++) {
        if (currentBoard[r][c] !== player) continue;

        for (const [dr, dc] of directions) {
          let count = 1;
          const line = [{r, c}];

          // Check forward
          for (let k = 1; k < 5; k++) {
            const nr = r + k * dr;
            const nc = c + k * dc;
            if (nr >= 0 && nr < GRID_SIZE && nc >= 0 && nc < GRID_SIZE && currentBoard[nr][nc] === player) {
              count++;
              line.push({r: nr, c: nc});
            } else {
              break;
            }
          }

          if (count === 5) return line;
        }
      }
    }
    return null;
  };

  const getAIMove = (currentBoard: number[][]) => {
    // Simple heuristic AI
    // 1. Check if AI can win immediately
    // 2. Check if Player is about to win (block)
    // 3. Pick best strategic spot (center preference + clustering)

    const emptyCells: {r: number, c: number, score: number}[] = [];

    // Helper to score a position
    const evaluatePos = (r: number, c: number, player: number) => {
      let score = 0;
      const directions = [[0, 1], [1, 0], [1, 1], [1, -1]];

      for (const [dr, dc] of directions) {
        let count = 0;
        let openEnds = 0;

        // Forward check
        for (let k = 1; k < 5; k++) {
            const nr = r + k * dr;
            const nc = c + k * dc;
            if (nr >= 0 && nr < GRID_SIZE && nc >= 0 && nc < GRID_SIZE) {
                if (currentBoard[nr][nc] === player) count++;
                else if (currentBoard[nr][nc] === CELL_EMPTY) { openEnds++; break; }
                else break; // Blocked
            } else break; // Edge
        }
        // Backward check
        for (let k = 1; k < 5; k++) {
            const nr = r - k * dr;
            const nc = c - k * dc;
            if (nr >= 0 && nr < GRID_SIZE && nc >= 0 && nc < GRID_SIZE) {
                if (currentBoard[nr][nc] === player) count++;
                else if (currentBoard[nr][nc] === CELL_EMPTY) { openEnds++; break; }
                else break;
            } else break;
        }

        if (count >= 4) score += 10000;
        else if (count === 3 && openEnds === 2) score += 1000;
        else if (count === 2 && openEnds === 2) score += 100;
        else if (count === 1 && openEnds === 2) score += 10;
      }
      return score;
    };

    for (let r = 0; r < GRID_SIZE; r++) {
      for (let c = 0; c < GRID_SIZE; c++) {
        if (currentBoard[r][c] === CELL_EMPTY) {
          // Attack score (AI)
          const attackScore = evaluatePos(r, c, CELL_AI);
          // Defense score (Block Player)
          const defenseScore = evaluatePos(r, c, CELL_PLAYER);

          // Difficulty tuning
          const defenseMultiplier = difficulty === 'ADVANCED' ? 1.2 : 0.8;

          let totalScore = attackScore + (defenseScore * defenseMultiplier);

          // Center bias
          const distFromCenter = Math.abs(r - 4.5) + Math.abs(c - 4.5);
          totalScore += (10 - distFromCenter);

          emptyCells.push({r, c, score: totalScore});
        }
      }
    }

    if (emptyCells.length === 0) return null;

    // Pick best move
    emptyCells.sort((a, b) => b.score - a.score);
    // Add some randomness to top 3 to feel less robotic
    const candidates = emptyCells.slice(0, 3);
    return candidates[Math.floor(Math.random() * candidates.length)];
  };

  const handleCellClick = (r: number, c: number) => {
    if (board[r][c] !== CELL_EMPTY || winner || !isPlayerTurn) return;

    const newBoard = board.map(row => [...row]);
    newBoard[r][c] = CELL_PLAYER;
    setBoard(newBoard);
    soundService.playGameSound('BOUNCE'); // Placing sound

    const winLine = checkWin(newBoard, CELL_PLAYER);
    if (winLine) {
      setWinningLine(winLine);
      setWinner(CELL_PLAYER);
      soundService.playWin();
    } else {
      setIsPlayerTurn(false);
    }
  };

  // AI Turn
  useEffect(() => {
    if (!isPlayerTurn && !winner) {
      const timer = setTimeout(() => {
        const move = getAIMove(board);
        if (move) {
          const newBoard = board.map(row => [...row]);
          newBoard[move.r][move.c] = CELL_AI;
          setBoard(newBoard);
          soundService.playGameSound('LOW'); // AI sound

          const winLine = checkWin(newBoard, CELL_AI);
          if (winLine) {
            setWinningLine(winLine);
            setWinner(CELL_AI);
            soundService.playWrong(); // Lose sound
          } else {
            // Check Draw
            if (newBoard.every(row => row.every(cell => cell !== CELL_EMPTY))) {
                setWinner(3);
            } else {
                setIsPlayerTurn(true);
            }
          }
        }
      }, 500); // 0.5s delay
      return () => clearTimeout(timer);
    }
  }, [isPlayerTurn, winner, board]);

  return (
    <div className="flex flex-col h-screen bg-stone-100 overflow-hidden">
      {/* Header */}
      <div className="flex-none p-4 flex justify-between items-center bg-white shadow-sm z-10">
        <button onClick={onBack} className="p-2 bg-gray-100 rounded-full text-gray-700 hover:bg-gray-200">
          <ArrowLeft size={20} />
        </button>
        <div className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <span className={`w-3 h-3 rounded-full ${isPlayerTurn ? 'bg-black animate-pulse' : 'bg-white border border-gray-400'}`}></span>
            {winner ? (winner === 1 ? "你贏了！" : winner === 2 ? "電腦贏了" : "平手") : (isPlayerTurn ? "你的回合" : "電腦思考中...")}
        </div>
        <button onClick={resetGame} className="p-2 bg-gray-100 rounded-full text-gray-700 hover:bg-gray-200">
          <RefreshCw size={20} />
        </button>
      </div>

      {/* Board */}
      <div className="flex-1 flex items-center justify-center p-4 bg-stone-200 overflow-auto">
        <div 
            className="bg-[#DEB887] p-2 sm:p-4 rounded shadow-2xl relative"
            style={{ width: 'min(90vw, 500px)', height: 'min(90vw, 500px)' }}
        >
            {/* Grid Lines */}
            <div className="absolute inset-2 sm:inset-4 pointer-events-none">
                {Array.from({ length: GRID_SIZE }).map((_, i) => (
                    <React.Fragment key={i}>
                        {/* Horizontal */}
                        <div className="absolute bg-black opacity-40 h-px w-full" style={{ top: `${(i / (GRID_SIZE - 1)) * 100}%` }}></div>
                        {/* Vertical */}
                        <div className="absolute bg-black opacity-40 w-px h-full" style={{ left: `${(i / (GRID_SIZE - 1)) * 100}%` }}></div>
                    </React.Fragment>
                ))}
            </div>

            {/* Cells */}
            <div 
                className="w-full h-full grid relative z-10"
                style={{ gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)`, gridTemplateRows: `repeat(${GRID_SIZE}, 1fr)` }}
            >
                {board.map((row, r) => row.map((cell, c) => {
                    const isWinningPiece = winningLine.some(pos => pos.r === r && pos.c === c);
                    return (
                        <div 
                            key={`${r}-${c}`} 
                            onClick={() => handleCellClick(r, c)}
                            className="flex items-center justify-center cursor-pointer"
                        >
                            {cell !== CELL_EMPTY && (
                                <div className={`
                                    w-[80%] h-[80%] rounded-full shadow-md transition-transform duration-200
                                    ${cell === CELL_PLAYER ? 'bg-black radial-gradient-black' : 'bg-white radial-gradient-white'}
                                    ${isWinningPiece ? 'ring-4 ring-green-500 scale-110' : ''}
                                `}></div>
                            )}
                            {/* Hover effect for empty cells */}
                            {cell === CELL_EMPTY && isPlayerTurn && !winner && (
                                <div className="w-[40%] h-[40%] rounded-full bg-black opacity-0 hover:opacity-20 transition-opacity"></div>
                            )}
                        </div>
                    );
                }))}
            </div>
        </div>
      </div>

      {winner === 1 && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 pointer-events-none">
            <div className="bg-white p-8 rounded-3xl animate-bounce-short text-center shadow-2xl pointer-events-auto">
                <Trophy className="w-20 h-20 text-yellow-500 mx-auto mb-4"/>
                <h2 className="text-3xl font-bold mb-4">恭喜獲勝！</h2>
                <button onClick={resetGame} className="px-6 py-3 bg-stone-800 text-white rounded-xl font-bold">再來一局</button>
            </div>
        </div>
      )}
    </div>
  );
};

export default GomokuGame;

