const ConnectFourGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<number[][]>([]);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true);
  const [winner, setWinner] = useState<number | null>(null);
  const [winningCells, setWinningCells] = useState<{r:number, c:number}[]>([]);

  useEffect(() => {
    resetGame();
  }, []);

  const resetGame = () => {
    const newBoard = Array(ROWS).fill(0).map(() => Array(COLS).fill(EMPTY));
    setBoard(newBoard);
    setIsPlayerTurn(true);
    setWinner(null);
    setWinningCells([]);
  };

  // Check 4 directions
  const checkWin = (b: number[][], player: number) => {
    // Horizontal
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r][c+1] === player && b[r][c+2] === player && b[r][c+3] === player) {
          return [{r,c}, {r,c:c+1}, {r,c:c+2}, {r,c:c+3}];
        }
      }
    }
    // Vertical
    for (let r = 0; r < ROWS - 3; r++) {
      for (let c = 0; c < COLS; c++) {
        if (b[r][c] === player && b[r+1][c] === player && b[r+2][c] === player && b[r+3][c] === player) {
          return [{r,c}, {r:r+1,c}, {r:r+2,c}, {r:r+3,c}];
        }
      }
    }
    // Diagonal \
    for (let r = 0; r < ROWS - 3; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r+1][c+1] === player && b[r+2][c+2] === player && b[r+3][c+3] === player) {
          return [{r,c}, {r:r+1,c:c+1}, {r:r+2,c:c+2}, {r:r+3,c:c+3}];
        }
      }
    }
    // Diagonal /
    for (let r = 3; r < ROWS; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r-1][c+1] === player && b[r-2][c+2] === player && b[r-3][c+3] === player) {
          return [{r,c}, {r:r-1,c:c+1}, {r:r-2,c:c+2}, {r:r-3,c:c+3}];
        }
      }
    }
    return null;
  };

  const getValidRow = (b: number[][], col: number) => {
    for (let r = ROWS - 1; r >= 0; r--) {
      if (b[r][col] === EMPTY) return r;
    }
    return -1;
  };

  const handleColumnClick = (col: number) => {
    if (!isPlayerTurn || winner) return;

    const r = getValidRow(board, col);
    if (r === -1) return; // Column full

    const newBoard = board.map(row => [...row]);
    newBoard[r][col] = PLAYER;
    setBoard(newBoard);
    soundService.playGameSound('FALL');

    const win = checkWin(newBoard, PLAYER);
    if (win) {
      setWinner(PLAYER);
      setWinningCells(win);
      soundService.playWin();
    } else {
      setIsPlayerTurn(false);
    }
  };

  // AI
  useEffect(() => {
    if (!isPlayerTurn && !winner) {
      const timer = setTimeout(() => {
        // Simple AI: 
        // 1. Can I win? 
        // 2. Can Player win? (Block) 
        // 3. Random valid

        let bestCol = -1;

        // Check for immediate win
        for (let c = 0; c < COLS; c++) {
            const r = getValidRow(board, c);
            if (r !== -1) {
                const tempBoard = board.map(row => [...row]);
                tempBoard[r][c] = AI;
                if (checkWin(tempBoard, AI)) {
                    bestCol = c;
                    break;
                }
            }
        }

        // Block player
        if (bestCol === -1) {
            for (let c = 0; c < COLS; c++) {
                const r = getValidRow(board, c);
                if (r !== -1) {
                    const tempBoard = board.map(row => [...row]);
                    tempBoard[r][c] = PLAYER;
                    if (checkWin(tempBoard, PLAYER)) {
                        bestCol = c;
                        break;
                    }
                }
            }
        }

        // Random center bias
        if (bestCol === -1) {
            const validCols = [];
            for (let c = 0; c < COLS; c++) {
                if (getValidRow(board, c) !== -1) validCols.push(c);
            }
            if (validCols.length > 0) {
                // Bias towards center (3)
                if (validCols.includes(3) && Math.random() > 0.3) bestCol = 3;
                else bestCol = validCols[Math.floor(Math.random() * validCols.length)];
            }
        }

        if (bestCol !== -1) {
            const r = getValidRow(board, bestCol);
            const newBoard = board.map(row => [...row]);
            newBoard[r][bestCol] = AI;
            setBoard(newBoard);
            soundService.playGameSound('LOW');

            const win = checkWin(newBoard, AI);
            if (win) {
                setWinner(AI);
                setWinningCells(win);
                soundService.playWrong();
            } else if (newBoard.every(row => row.every(c => c !== EMPTY))) {
                setWinner(3); // Draw
            } else {
                setIsPlayerTurn(true);
            }
        }

      }, 700);
      return () => clearTimeout(timer);
    }
  }, [isPlayerTurn, winner, board]);

  return (
    <div className="flex flex-col h-screen bg-blue-50 overflow-hidden">
        <div className="flex-none p-4 flex justify-between items-center bg-white shadow-sm z-10">
            <button onClick={onBack} className="p-2 bg-gray-100 rounded-full text-blue-800"><ArrowLeft size={20} /></button>
            <h2 className="text-xl font-bold text-blue-900">{winner ? (winner === 1 ? "你贏了！" : "電腦贏了") : "四子棋"}</h2>
            <button onClick={resetGame} className="p-2 bg-gray-100 rounded-full text-blue-800"><RefreshCw size={20} /></button>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-4">
            <div className="bg-blue-600 p-2 sm:p-4 rounded-b-xl rounded-t-sm shadow-2xl relative inline-block">

                {/* Column Click Targets (Top indicators) */}
                <div className="absolute -top-8 sm:-top-10 left-0 w-full flex justify-around px-2 sm:px-4">
                    {Array.from({length: COLS}).map((_, c) => (
                        <button 
                            key={c}
                            onClick={() => handleColumnClick(c)}
                            disabled={!isPlayerTurn || winner !== null}
                            className="w-8 h-8 sm:w-12 sm:h-12 flex items-center justify-center text-blue-400 hover:text-blue-600 hover:bg-blue-100 rounded-full transition-colors disabled:opacity-0"
                        >
                            <ArrowDown size={24} />
                        </button>
                    ))}
                </div>

                <div className="grid grid-cols-7 gap-2 sm:gap-3 bg-blue-700 p-2 sm:p-3 rounded-lg border-4 border-blue-800">
                    {board.map((row, r) => (
                        row.map((cell, c) => {
                            const isWin = winningCells.some(w => w.r === r && w.c === c);
                            return (
                                <div 
                                    key={`${r}-${c}`} 
                                    className={`
                                        w-8 h-8 sm:w-12 sm:h-12 rounded-full shadow-inner border border-black/10
                                        ${cell === EMPTY ? 'bg-blue-900/30' : cell === PLAYER ? 'bg-red-500' : 'bg-yellow-400'}
                                        ${isWin ? 'ring-4 ring-white animate-pulse' : ''}
                                    `}
                                />
                            );
                        })
                    ))}
                </div>

                {/* Legs */}
                <div className="absolute -bottom-8 left-4 w-4 h-8 bg-blue-800"></div>
                <div className="absolute -bottom-8 right-4 w-4 h-8 bg-blue-800"></div>
            </div>
        </div>
    </div>
  );
};

