                    {/* The Board - Horizontal 8x4 */}
                    <div className="bg-[#DEB887] p-1.5 sm:p-2 rounded shadow-xl border-4 border-[#8B4513] flex-1">
                        <div 
                            className="grid gap-1 sm:gap-2 w-full h-full"
                            style={{ 
                                gridTemplateColumns: `repeat(8, 1fr)`, 
                                aspectRatio: '2/1' 
                            }}
                        >
                            {grid.map((piece, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => handleTileClick(idx)}
                                    className={`
                                        rounded-full border-2 sm:border-4 shadow-sm flex items-center justify-center relative transition-transform
                                        text-xl sm:text-2xl md:text-3xl font-bold aspect-square
                                        ${!piece ? 'invisible' : ''}
                                        ${piece && !piece.revealed ? 'bg-[#8B4513] border-[#5C3317]' : ''}
                                        ${piece && piece.revealed ? 'bg-[#f7e7ce]' : ''}
                                        ${piece && piece.revealed && piece.isRed ? 'text-red-600 border-red-800' : 'text-black border-black'}
                                        ${selectedIdx === idx ? 'ring-4 ring-yellow-400 scale-110 z-10' : ''}
                                    `}
                                >
                                    {piece && piece.revealed && (
                                        <div className="rounded-full border border-dashed border-current w-[85%] h-[85%] flex items-center justify-center">
                                            {piece.text}
                                        </div>
                                    )}
                                    {piece && !piece.revealed && (
                                        <div className="opacity-20 text-white text-[10px] sm:text-xs">?</div>
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
