}

const ROWS = 6;
const COLS = 7;
const EMPTY = 0;
const PLAYER = 1; // Red
const AI = 2;     // Yellow

const COL_LABELS = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];

const ConnectFourGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<number[][]>([]);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true);
  const [winner, setWinner] = useState<number | null>(null);
  const [winningCells, setWinningCells] = useState<{r:number, c:number}[]>([]);
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');

  useEffect(() => {
    resetGame();
  }, []);

  useEffect(() => {
      resetGame();
  }, [gameMode]);

  const resetGame = () => {
    const newBoard = Array(ROWS).fill(0).map(() => Array(COLS).fill(EMPTY));
    setBoard(newBoard);
    setIsPlayerTurn(true);
    setWinner(null);
    setWinningCells([]);
  };

  const checkWin = (b: number[][], player: number) => {
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r][c+1] === player && b[r][c+2] === player && b[r][c+3] === player) return [{r,c}, {r,c:c+1}, {r,c:c+2}, {r,c:c+3}];
      }
    }
    for (let r = 0; r < ROWS - 3; r++) {
      for (let c = 0; c < COLS; c++) {
        if (b[r][c] === player && b[r+1][c] === player && b[r+2][c] === player && b[r+3][c] === player) return [{r,c}, {r:r+1,c}, {r:r+2,c}, {r:r+3,c}];
      }
    }
    for (let r = 0; r < ROWS - 3; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r+1][c+1] === player && b[r+2][c+2] === player && b[r+3][c+3] === player) return [{r,c}, {r:r+1,c:c+1}, {r:r+2,c:c+2}, {r:r+3,c:c+3}];
      }
    }
    for (let r = 3; r < ROWS; r++) {
      for (let c = 0; c < COLS - 3; c++) {
        if (b[r][c] === player && b[r-1][c+1] === player && b[r-2][c+2] === player && b[r-3][c+3] === player) return [{r,c}, {r:r-1,c:c+1}, {r:r-2,c:c+2}, {r:r-3,c:c+3}];
      }
    }
    return null;
  };

  const getValidRow = (b: number[][], col: number) => {
    for (let r = ROWS - 1; r >= 0; r--) {
      if (b[r][col] === EMPTY) return r;
    }
    return -1;
  };

  const handleColumnClick = (col: number) => {
    if (winner) return;
    if (gameMode === 'PVE' && !isPlayerTurn) return;

    const currentPlayer = isPlayerTurn ? PLAYER : AI;
    const r = getValidRow(board, col);
    if (r === -1) return;

    const newBoard = board.map(row => [...row]);
    newBoard[r][col] = currentPlayer;
    setBoard(newBoard);
    soundService.playGameSound('FALL');

    const win = checkWin(newBoard, currentPlayer);
    if (win) {
      setWinner(currentPlayer);
      setWinningCells(win);
      soundService.playWin();
    } else {
      setIsPlayerTurn(!isPlayerTurn);
    }
  };

  useEffect(() => {
    if (gameMode === 'PVE' && !isPlayerTurn && !winner) {
      const timer = setTimeout(() => {
        let bestCol = -1;
        // 1. Win
        for (let c = 0; c < COLS; c++) {
            const r = getValidRow(board, c);
            if (r !== -1) {
                const tempBoard = board.map(row => [...row]);
                tempBoard[r][c] = AI;
                if (checkWin(tempBoard, AI)) { bestCol = c; break; }
            }
        }
        // 2. Block
        if (bestCol === -1) {
            for (let c = 0; c < COLS; c++) {
                const r = getValidRow(board, c);
                if (r !== -1) {
                    const tempBoard = board.map(row => [...row]);
                    tempBoard[r][c] = PLAYER;
                    if (checkWin(tempBoard, PLAYER)) { bestCol = c; break; }
                }
            }
        }
        // 3. Random
        if (bestCol === -1) {
            const validCols = [];
            for (let c = 0; c < COLS; c++) { if (getValidRow(board, c) !== -1) validCols.push(c); }
            if (validCols.length > 0) {
                if (validCols.includes(3) && Math.random() > 0.3) bestCol = 3;
                else bestCol = validCols[Math.floor(Math.random() * validCols.length)];
            }
        }

        if (bestCol !== -1) {
            const r = getValidRow(board, bestCol);
            const newBoard = board.map(row => [...row]);
            newBoard[r][bestCol] = AI;
            setBoard(newBoard);
            soundService.playGameSound('LOW');
            const win = checkWin(newBoard, AI);
            if (win) {
                setWinner(AI);
                setWinningCells(win);
                soundService.playWrong();
            } else if (newBoard.every(row => row.every(c => c !== EMPTY))) {
                setWinner(3);
            } else {
                setIsPlayerTurn(true);
            }
        }
      }, 700);
      return () => clearTimeout(timer);
    }
  }, [isPlayerTurn, winner, board, gameMode]);

  return (
    <div className="flex flex-col h-[100dvh] bg-blue-50 overflow-hidden">
        {/* Compact Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-12 sm:h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-blue-800"><ArrowLeft size={18} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 rounded-full text-xs sm:text-sm font-bold text-blue-900 border border-blue-200"
            >
                {gameMode === 'PVE' ? <User size={14} /> : <Users size={14} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-blue-800"><RefreshCw size={18} /></button>
        </div>

        {/* Status */}
        <div className="flex-none text-center py-1 font-bold text-blue-900 text-sm sm:text-base">
            {winner ? (winner === 1 ? "紅方獲勝！" : "黃方獲勝！") : (isPlayerTurn ? "紅方回合" : "黃方回合")}
        </div>

        {/* Main Board */}
        <div className="flex-1 flex flex-col items-center justify-center p-2 overflow-hidden w-full">
            {/* Scaled Wrapper: Constrain by height in landscape (vh) or width in portrait (vw) */}
            <div className="relative bg-blue-600 rounded-b-xl rounded-t-sm shadow-2xl p-2 sm:p-3" style={{ height: 'min(70vh, 100vw)', aspectRatio: '7/6' }}>

                {/* Labels Top */}
                <div className="absolute -top-6 left-0 w-full flex justify-around px-2">
                    {COL_LABELS.map((label, c) => (
                        <div key={c} className="w-full text-center font-bold text-blue-900 text-xs sm:text-sm">{label}</div>
                    ))}
                </div>

                {/* Grid */}
                <div className="grid grid-cols-7 gap-1.5 sm:gap-2 bg-blue-700 p-2 rounded-lg border-4 border-blue-800 h-full w-full">
                    {board.map((row, r) => (
                        row.map((cell, c) => {
                            const isWin = winningCells.some(w => w.r === r && w.c === c);
                            // Determine if column is interactive
                            const isColumnFull = board[0][c] !== EMPTY;
                            const isInteractable = !winner && (gameMode === 'PVP' || isPlayerTurn) && !isColumnFull;

                            return (
                                <div 
                                    key={`${r}-${c}`} 
                                    onClick={() => handleColumnClick(c)}
                                    className={`
                                        w-full h-full rounded-full shadow-inner border border-black/10 transition-colors duration-300
                                        ${cell === EMPTY ? 'bg-blue-900/30' : cell === PLAYER ? 'bg-red-500' : 'bg-yellow-400'}
                                        ${isWin ? 'ring-4 ring-white animate-pulse' : ''}
                                        ${isInteractable ? 'cursor-pointer hover:bg-blue-800/40' : ''}
                                    `}
                                />
                            );
                        })
                    ))}
                </div>

                {/* Legs */}
                <div className="absolute -bottom-4 left-4 w-3 h-4 bg-blue-800 rounded-b"></div>
                <div className="absolute -bottom-4 right-4 w-3 h-4 bg-blue-800 rounded-b"></div>
            </div>
        </div>
    </div>
  );
};

export default ConnectFourGame;

export enum GameState {
  MENU = 'MENU',
  SORTING = 'SORTING',
  MEMORY = 'MEMORY',
  BREATHING = 'BREATHING',
  SENTENCE = 'SENTENCE',
  FIND = 'FIND',
  MARKET = 'MARKET',
  STEPS = 'STEPS',
  SHADOW = 'SHADOW',
  STROOP = 'STROOP',
  DOTS = 'DOTS',
  EMOTION = 'EMOTION',
  PATTERN = 'PATTERN',
  TIME = 'TIME',
  ODD_ONE = 'ODD_ONE',
  SOUND = 'SOUND',
  PUZZLE = 'PUZZLE',
  // Board Games
  GOMOKU = 'GOMOKU',
  DARK_CHESS = 'DARK_CHESS',
  CONNECT_FOUR = 'CONNECT_FOUR',
  OTHELLO = 'OTHELLO',
  DOTS_BOXES = 'DOTS_BOXES',
  MANCALA = 'MANCALA',
  CHECKERS = 'CHECKERS',
  GOBBLET = 'GOBBLET'
}

export type Difficulty = 'NORMAL' | 'ADVANCED';

export interface SortingItem {
  id: string;
  name: string;
  category: 'A' | 'B';
}

export interface SortingLevel {
  categoryA: string;
  categoryB: string;
  items: SortingItem[];
}

export interface MemoryCard {
  id: number;
  content: string; // Emoji or Icon name
  isFlipped: boolean;
  isMatched: boolean;
}

export interface SentenceLevel {
  original: string;
  scrambled: { id: string, text: string }[];
}

export interface FindLevel {
  target: string;
  distractor: string;
  gridSize: number; // e.g. 5 for 5x5
  targetPosition: number; // index
}

// --- NEW GAMES TYPES ---

export interface MarketItem {
  name: string;
  icon: string;
  price: number;
}

export interface MarketLevel {
  items: MarketItem[];
  question: string;
  options: number[]; // 3 numeric options
  correctAnswer: number;
}

export interface StepItem {
  id: string;
  text: string;
  order: number; // Correct order (1, 2, 3...)
}

export interface StepsLevel {
  title: string;
  steps: StepItem[]; // Scrambled when delivered
}

export interface ShadowLevel {
  target: string; // The correct emoji
  options: string[]; // List of emojis (one is target, others are distractors)
  correctIndex: number;
}

// 1. Stroop (Color Trap)
export interface StroopLevel {
  text: string;        // The word displayed (e.g., "紅")
  colorCode: string;   // The css color of the word (e.g., "text-green-500")
  colorName: string;   // The semantic name of the colorCode (e.g., "綠") -> Correct Answer
  options: string[];   // Options displayed to user (e.g., ["紅", "綠", "藍"])
}

// 2. Dots (Spatial Working Memory)
export interface DotLevel {
  gridSize: number;    // 3 for 3x3, 4 for 4x4
  activeIndices: number[]; // Indices of dots to memorize
  duration: number;    // How long to show the dots (ms)
}

// 3. Emotion (Social Cognition)
export interface EmotionLevel {
  question: string;     // Scenario text or "How does he feel?"
  emoji?: string;       // Optional central image/emoji
  options: string[];    // Text options (e.g., "開心", "生氣")
  correctAnswer: string; 
}

// 4. Pattern (Logic)
export interface PatternLevel {
  sequence: string[]; // e.g. ["A", "B", "A", "?"]
  options: string[];  // e.g. ["A", "B", "C"]
  answer: string;
}

// 5. Time (Reality Orientation)
export interface TimeLevel {
  type: 'CLOCK' | 'MATH';
  question: string;
  clockTime?: { hour: number, minute: number }; // For visual clock
  options: string[];
  correctAnswer: string;
}

// 6. Odd One Out (Semantic)
export interface OddOneLevel {
  items: { text: string, icon: string }[];
  correctIndex: number; // The index of the odd one
  reason?: string; // Optional explanation
}

// 7. Sound Match (Auditory Attention)
export interface SoundLevel {
  soundType: 'HIGH' | 'LOW' | 'RISE' | 'FALL' | 'ALARM' | 'GAME' | 'BOUNCE' | 'MAGIC' | 'TELEPHONE';
  targetIcon: string;
  options: { icon: string, label: string, isCorrect: boolean }[];
}

// 8. Puzzle (Visual Spatial)
export interface PuzzleLevel {
  gridSize: number; // 2 or 3
  targetImage: string[]; // Array of icons/colors in correct order
  scrambled: { id: number, content: string }[];
}

