import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const ROWS = 4;
const COLS = 4;

const DotsAndBoxesGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  // Horizontal lines: (ROWS + 1) * COLS
  // Vertical lines: ROWS * (COLS + 1)
  const [hLines, setHLines] = useState<boolean[][]>([]);
  const [vLines, setVLines] = useState<boolean[][]>([]);
  // Squares owned by player: 0 = none, 1 = P1, 2 = P2
  const [squares, setSquares] = useState<number[][]>([]);
  const [turn, setTurn] = useState(1); // 1 = P1 (Red), 2 = P2 (Blue)
  const [scores, setScores] = useState({ p1: 0, p2: 0 });
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');
  const [winner, setWinner] = useState<number | null>(null);

  useEffect(() => {
    resetGame();
  }, [gameMode]);

  const resetGame = () => {
    setHLines(Array(ROWS + 1).fill(false).map(() => Array(COLS).fill(false)));
    setVLines(Array(ROWS).fill(false).map(() => Array(COLS + 1).fill(false)));
    setSquares(Array(ROWS).fill(0).map(() => Array(COLS).fill(0)));
    setTurn(1);
    setScores({ p1: 0, p2: 0 });
    setWinner(null);
  };

  const checkBoxCompletion = (r: number, c: number, currentHLines: boolean[][], currentVLines: boolean[][]) => {
    const top = currentHLines[r][c];
    const bottom = currentHLines[r + 1][c];
    const left = currentVLines[r][c];
    const right = currentVLines[r][c + 1];
    return top && bottom && left && right;
  };

  const handleLineClick = (type: 'h' | 'v', r: number, c: number) => {
    if (winner) return;
    if (gameMode === 'PVE' && turn === 2) return; // AI turn block

    const isH = type === 'h';
    if (isH && hLines[r][c]) return;
    if (!isH && vLines[r][c]) return;

    makeMove(type, r, c);
  };

  const makeMove = (type: 'h' | 'v', r: number, c: number) => {
    let pointScored = false;
    const nextHLines = hLines.map(row => [...row]);
    const nextVLines = vLines.map(row => [...row]);
    const nextSquares = squares.map(row => [...row]);

    if (type === 'h') nextHLines[r][c] = true;
    else nextVLines[r][c] = true;

    // Check affected squares
    // If H line: check square above (r-1, c) and below (r, c)
    // If V line: check square left (r, c-1) and right (r, c)

    if (type === 'h') {
        if (r > 0 && checkBoxCompletion(r - 1, c, nextHLines, nextVLines)) {
            nextSquares[r - 1][c] = turn;
            pointScored = true;
        }
        if (r < ROWS && checkBoxCompletion(r, c, nextHLines, nextVLines)) {
            nextSquares[r][c] = turn;
            pointScored = true;
        }
    } else {
        if (c > 0 && checkBoxCompletion(r, c - 1, nextHLines, nextVLines)) {
            nextSquares[r][c - 1] = turn;
            pointScored = true;
        }
        if (c < COLS && checkBoxCompletion(r, c, nextHLines, nextVLines)) {
            nextSquares[r][c] = turn;
            pointScored = true;
        }
    }

    setHLines(nextHLines);
    setVLines(nextVLines);
    setSquares(nextSquares);
    soundService.playGameSound('BOUNCE');

    if (pointScored) {
        setScores(prev => ({ ...prev, [turn === 1 ? 'p1' : 'p2']: prev[turn === 1 ? 'p1' : 'p2'] + 1 })); // Incorrect logic fix below
        // Fix score update logic: need to count explicitly or add pointScored count (could be 2)
        let points = 0;
        if (type === 'h') {
            if (r > 0 && checkBoxCompletion(r - 1, c, nextHLines, nextVLines)) points++;
            if (r < ROWS && checkBoxCompletion(r, c, nextHLines, nextVLines)) points++;
        } else {
            if (c > 0 && checkBoxCompletion(r, c - 1, nextHLines, nextVLines)) points++;
            if (c < COLS && checkBoxCompletion(r, c, nextHLines, nextVLines)) points++;
        }

        // Re-set scores based on total squares to be safe
        let p1s = 0, p2s = 0;
        nextSquares.forEach(row => row.forEach(s => {
            if (s === 1) p1s++;
            else if (s === 2) p2s++;
        }));
        setScores({ p1: p1s, p2: p2s });
        soundService.playCorrect();

        if (p1s + p2s === ROWS * COLS) {
            setWinner(p1s > p2s ? 1 : p2s > p1s ? 2 : 3); // 3 draw
            soundService.playWin();
        }
        // Turn does NOT change if point scored
    } else {
        setTurn(prev => prev === 1 ? 2 : 1);
    }
  };

  // AI Logic
  useEffect(() => {
    if (gameMode === 'PVE' && turn === 2 && !winner) {
      const timer = setTimeout(() => {
        // AI Strategy: 
        // 1. Find move that completes a box.
        // 2. Find move that does NOT give away a box (randomly among safe moves).
        // 3. If no safe moves, pick random.

        const possibleMoves: {type: 'h'|'v', r: number, c: number, completes: number, risky: boolean}[] = [];

        // Helper to check if a line completes a box
        const checkCompletes = (type: 'h'|'v', r: number, c: number) => {
            let count = 0;
            // Temporarily set line
            const tempH = hLines.map(row => [...row]);
            const tempV = vLines.map(row => [...row]);
            if(type==='h') tempH[r][c] = true; else tempV[r][c] = true;

            if (type === 'h') {
                if (r > 0 && checkBoxCompletion(r-1, c, tempH, tempV)) count++;
                if (r < ROWS && checkBoxCompletion(r, c, tempH, tempV)) count++;
            } else {
                if (c > 0 && checkBoxCompletion(r, c-1, tempH, tempV)) count++;
                if (c < COLS && checkBoxCompletion(r, c, tempH, tempV)) count++;
            }
            return count;
        };

        // Helper to check if a line sets up opponent (makes a box have 3 sides)
        const checkRisky = (type: 'h'|'v', r: number, c: number) => {
             // Temporarily set line
             const tempH = hLines.map(row => [...row]);
             const tempV = vLines.map(row => [...row]);
             if(type==='h') tempH[r][c] = true; else tempV[r][c] = true;

             // Check adjacent squares. If any square has exactly 3 lines now, it's risky (opponent can take it).
             const checkSquare = (sr: number, sc: number) => {
                 if (sr<0 || sr>=ROWS || sc<0 || sc>=COLS) return false;
                 if (squares[sr][sc] !== 0) return false; // Already taken
                 let sides = 0;
                 if (tempH[sr][sc]) sides++;
                 if (tempH[sr+1][sc]) sides++;
                 if (tempV[sr][sc]) sides++;
                 if (tempV[sr][sc+1]) sides++;
                 return sides === 3; // Setting up 3rd side is risky
             }

             if (type === 'h') {
                 if (checkSquare(r-1, c)) return true;
                 if (checkSquare(r, c)) return true;
             } else {
                 if (checkSquare(r, c-1)) return true;
                 if (checkSquare(r, c)) return true;
             }
             return false;
        };

        // Gather all moves
        for(let r=0; r<=ROWS; r++) {
            for(let c=0; c<COLS; c++) {
                if(!hLines[r][c]) possibleMoves.push({type: 'h', r, c, completes: checkCompletes('h', r, c), risky: false});
            }
        }
        for(let r=0; r<ROWS; r++) {
            for(let c=0; c<=COLS; c++) {
                if(!vLines[r][c]) possibleMoves.push({type: 'v', r, c, completes: checkCompletes('v', r, c), risky: false});
            }
        }

        // Calculate risky for remaining
        possibleMoves.forEach(m => {
            if (m.completes === 0) {
                m.risky = checkRisky(m.type, m.r, m.c);
            }
        });

        // Pick best move
        let bestMove = null;

        // 1. Take boxes
        const scorers = possibleMoves.filter(m => m.completes > 0);
        if (scorers.length > 0) {
            // Prioritize moves that give another free turn? (completes > 0 always gives free turn)
            bestMove = scorers[Math.floor(Math.random() * scorers.length)];
        } else {
            // 2. Safe moves
            const safeMoves = possibleMoves.filter(m => !m.risky);
            if (safeMoves.length > 0) {
                bestMove = safeMoves[Math.floor(Math.random() * safeMoves.length)];
            } else {
                // 3. Must sacrifice (minimize damage logic could go here, but random for now)
                bestMove = possibleMoves[Math.floor(Math.random() * possibleMoves.length)];
            }
        }

        if (bestMove) {
            makeMove(bestMove.type, bestMove.r, bestMove.c);
        }

      }, 600);
      return () => clearTimeout(timer);
    }
  }, [turn, hLines, vLines, squares, gameMode]);

  return (
    <div className="flex flex-col h-[100dvh] bg-rose-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-2 bg-gray-100 rounded-full text-rose-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-rose-50 rounded-full text-sm font-bold text-rose-900 border border-rose-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-2 bg-gray-100 rounded-full text-rose-800"><RefreshCw size={20} /></button>
        </div>

        {/* Score Board */}
        <div className="flex justify-center gap-8 py-2 bg-rose-100 border-b border-rose-200">
            <div className={`flex flex-col items-center p-2 rounded-lg transition-all ${turn === 1 ? 'bg-white shadow-md scale-110 border-2 border-red-400' : 'opacity-70'}`}>
                <div className="text-xs text-gray-500 font-bold mb-1">{gameMode === 'PVP' ? '紅方' : '你'}</div>
                <div className="text-2xl font-black text-red-500">{scores.p1}</div>
            </div>
            <div className={`flex flex-col items-center p-2 rounded-lg transition-all ${turn === 2 ? 'bg-white shadow-md scale-110 border-2 border-blue-400' : 'opacity-70'}`}>
                <div className="text-xs text-gray-500 font-bold mb-1">{gameMode === 'PVP' ? '藍方' : '電腦'}</div>
                <div className="text-2xl font-black text-blue-500">{scores.p2}</div>
            </div>
        </div>

        {/* Game Board */}
        <div className="flex-1 flex flex-col items-center justify-center p-4 bg-rose-50 overflow-hidden">
            <div className="bg-white p-4 rounded-xl shadow-2xl border-4 border-rose-200" style={{ width: 'min(90vw, 55vh)', height: 'min(90vw, 55vh)' }}>
                <div className="relative w-full h-full">

                    {/* Render Squares (Backgrounds) */}
                    <div className="absolute inset-0 grid" style={{ gridTemplateColumns: `repeat(${COLS}, 1fr)`, gridTemplateRows: `repeat(${ROWS}, 1fr)` }}>
                        {squares.map((row, r) => row.map((owner, c) => (
                            <div key={`sq-${r}-${c}`} className={`flex items-center justify-center m-1 rounded-lg transition-colors duration-500 ${owner === 1 ? 'bg-red-200' : owner === 2 ? 'bg-blue-200' : 'bg-transparent'}`}>
                                {owner !== 0 && (owner === 1 ? <div className="text-red-500 font-bold text-xl">紅</div> : <div className="text-blue-500 font-bold text-xl">藍</div>)}
                            </div>
                        )))}
                    </div>

                    {/* Render Dots */}
                    <div className="absolute inset-0 flex flex-col justify-between pointer-events-none z-20">
                        {Array.from({length: ROWS + 1}).map((_, r) => (
                            <div key={`dr-${r}`} className="flex justify-between">
                                {Array.from({length: COLS + 1}).map((_, c) => (
                                    <div key={`d-${r}-${c}`} className="w-3 h-3 sm:w-4 sm:h-4 bg-gray-800 rounded-full -m-1.5 sm:-m-2"></div>
                                ))}
                            </div>
                        ))}
                    </div>

                    {/* Hit Areas - Horizontal */}
                    <div className="absolute inset-0 flex flex-col justify-between z-10">
                        {hLines.map((row, r) => (
                            <div key={`hr-${r}`} className="flex h-0 relative">
                                {row.map((active, c) => (
                                    <div 
                                        key={`h-${r}-${c}`} 
                                        onClick={() => handleLineClick('h', r, c)}
                                        className="flex-1 h-6 sm:h-8 -mt-3 sm:-mt-4 cursor-pointer group flex items-center justify-center relative"
                                    >
                                        {/* Visible Line */}
                                        <div className={`h-1.5 sm:h-2 w-full rounded-full transition-colors duration-200 ${active ? (turn === 1 && squares.flat().filter(s=>s===1).length > scores.p1 ? 'bg-gray-800' : 'bg-gray-800') : 'bg-gray-100 group-hover:bg-gray-300'}`}></div>
                                        {active && <div className={`absolute inset-0 h-1.5 sm:h-2 top-1/2 -translate-y-1/2 ${'bg-gray-800'}`}></div>}
                                    </div>
                                ))}
                            </div>
                        ))}
                    </div>

                    {/* Hit Areas - Vertical */}
                    <div className="absolute inset-0 flex flex-row justify-between z-10 pointer-events-none">
                        {Array.from({length: COLS + 1}).map((_, c) => (
                            <div key={`vc-${c}`} className="flex flex-col w-0 relative pointer-events-auto">
                                {vLines.map((row, r) => (
                                    <div 
                                        key={`v-${r}-${c}`}
                                        onClick={() => handleLineClick('v', r, c)}
                                        className="flex-1 w-6 sm:w-8 -ml-3 sm:-ml-4 cursor-pointer group flex flex-col items-center justify-center"
                                    >
                                        <div className={`w-1.5 sm:w-2 h-full rounded-full transition-colors duration-200 ${row[c] ? 'bg-gray-800' : 'bg-gray-100 group-hover:bg-gray-300'}`}></div>
                                    </div>
                                ))}
                            </div>
                        ))}
                    </div>

                </div>
            </div>
            <div className="mt-4 text-rose-800 font-bold text-sm">
                點擊點與點之間的線條來連線
            </div>
        </div>

        {winner && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50">
                <div className="bg-white p-8 rounded-2xl text-center animate-bounce-short shadow-2xl border-4 border-rose-200">
