                        {winner === 1 ? "紅方獲勝！" : winner === 2 ? "藍方獲勝！" : "平手"}
                    </h2>
                    <p className="text-gray-500 mb-6">{scores.p1} : {scores.p2}</p>
                    <button onClick={resetGame} className="px-6 py-2 bg-rose-600 text-white rounded-lg font-bold">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

