import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User, Gem } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

// 0-5: Player 1 Pits
// 6: Player 1 Store
// 7-12: Player 2 Pits (Top, reversed visually)
// 13: Player 2 Store
const TOTAL_PITS = 14;
const P1_STORE = 6;
const P2_STORE = 13;

const MancalaGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<number[]>([]);
  const [turn, setTurn] = useState(1); // 1 = P1 (Bottom), 2 = P2 (Top)
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');
  const [winner, setWinner] = useState<number | null>(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    resetGame();
  }, [gameMode]);

  const resetGame = () => {
    // Initial seeds: 4 per pit, 0 in stores
    const newBoard = Array(TOTAL_PITS).fill(4);
    newBoard[P1_STORE] = 0;
    newBoard[P2_STORE] = 0;
    setBoard(newBoard);
    setTurn(1);
    setWinner(null);
    setMessage(gameMode === 'PVE' ? "請點擊下方你的洞" : "紅方回合 (下方)");
  };

  const checkEndGame = (currentBoard: number[]) => {
      const p1Empty = currentBoard.slice(0, 6).every(seeds => seeds === 0);
      const p2Empty = currentBoard.slice(7, 13).every(seeds => seeds === 0);

      if (p1Empty || p2Empty) {
          // Capture remainders
          const finalBoard = [...currentBoard];
          let p1Rem = 0;
          for(let i=0; i<6; i++) { p1Rem += finalBoard[i]; finalBoard[i] = 0; }
          let p2Rem = 0;
          for(let i=7; i<13; i++) { p2Rem += finalBoard[i]; finalBoard[i] = 0; }

          finalBoard[P1_STORE] += p1Rem;
          finalBoard[P2_STORE] += p2Rem;
          setBoard(finalBoard);

          if (finalBoard[P1_STORE] > finalBoard[P2_STORE]) setWinner(1);
          else if (finalBoard[P2_STORE] > finalBoard[P1_STORE]) setWinner(2);
          else setWinner(3); // Draw

          soundService.playWin();
          return true;
      }
      return false;
  };

  const handlePitClick = (index: number) => {
      if (winner) return;
      if (gameMode === 'PVE' && turn === 2) return;

      // Validate move
      if (turn === 1 && (index < 0 || index > 5)) return;
      if (turn === 2 && (index < 7 || index > 12)) return;
      if (board[index] === 0) return;

      move(index);
  };

  const move = (startIndex: number) => {
      let newBoard = [...board];
      let seeds = newBoard[startIndex];
      newBoard[startIndex] = 0;
      soundService.playGameSound('RISE');

      let currentIndex = startIndex;
      while (seeds > 0) {
          currentIndex = (currentIndex + 1) % TOTAL_PITS;
          // Skip opponent's store
          if (turn === 1 && currentIndex === P2_STORE) continue;
          if (turn === 2 && currentIndex === P1_STORE) continue;

          newBoard[currentIndex]++;
          seeds--;
      }

      // Rules check
      const lastIndex = currentIndex;
      let nextTurn = turn === 1 ? 2 : 1;
      let extraTurn = false;

      // 1. Land in own store -> Free turn
      if ((turn === 1 && lastIndex === P1_STORE) || (turn === 2 && lastIndex === P2_STORE)) {
          nextTurn = turn;
          extraTurn = true;
          setMessage(turn === 1 ? "再一次！ (紅方)" : (gameMode === 'PVE' ? "電腦再一次" : "再一次！ (藍方)"));
          soundService.playGameSound('HIGH');
      } 
      // 2. Capture: Land in empty own pit across from non-empty opponent pit
      else if (
          newBoard[lastIndex] === 1 && 
          ((turn === 1 && lastIndex >= 0 && lastIndex <= 5) || (turn === 2 && lastIndex >= 7 && lastIndex <= 12))
      ) {
          const oppositeIndex = 12 - lastIndex;
          if (newBoard[oppositeIndex] > 0) {
              const captured = newBoard[oppositeIndex] + 1;
              newBoard[oppositeIndex] = 0;
              newBoard[lastIndex] = 0;
              newBoard[turn === 1 ? P1_STORE : P2_STORE] += captured;
              soundService.playGameSound('BOUNCE');
          }
      }

      setBoard(newBoard);

      if (!checkEndGame(newBoard)) {
          if (!extraTurn) {
              setTurn(nextTurn);
              setMessage(nextTurn === 1 ? (gameMode === 'PVE' ? "換你 (紅方)" : "紅方回合") : (gameMode === 'PVE' ? "電腦思考中..." : "藍方回合"));
          }
      }
  };

  // AI
  useEffect(() => {
      if (gameMode === 'PVE' && turn === 2 && !winner) {
          const timer = setTimeout(() => {
              // Heuristic:
              // 1. Prioritize free turns
              // 2. Prioritize captures
              // 3. Pick right-most pit (to clear side) or random

              const validMoves = [];
              for(let i=7; i<=12; i++) if (board[i] > 0) validMoves.push(i);

              if (validMoves.length === 0) return; // Should be handled by game over check, but safety

              let bestMove = validMoves[0];
              let bestScore = -1;

              for (const m of validMoves) {
                  let score = 0;
                  // Lookahead simulation (simple)
                  let seeds = board[m];
                  let endPos = (m + seeds) % 14; 
                  // Correction for skipping P1 Store roughly
                  // Simplification: if endPos lands on 13 (P2 Store), +50

                  // Accurate calculation for landing position needed for heuristic?
                  // Let's just do simple math
                  let steps = seeds;
                  let curr = m;
                  while(steps > 0) {
                      curr = (curr + 1) % 14;
                      if (curr !== P1_STORE) steps--;
                  }

                  if (curr === P2_STORE) score += 50; // Free turn
                  if (board[curr] === 0 && curr >= 7 && curr <= 12 && board[12-curr] > 0) score += 20 + board[12-curr]; // Capture

                  score += Math.random() * 5; // Randomness

                  if (score > bestScore) {
                      bestScore = score;
                      bestMove = m;
                  }
              }

              move(bestMove);

          }, 800);
          return () => clearTimeout(timer);
      }
  }, [turn, board, winner, gameMode]);

  const Pit = ({ idx, isStore = false, owner = 0 }: { idx: number, isStore?: boolean, owner?: number }) => {
      const seeds = board[idx] || 0;
      // Visual seeds: randomly jittered dots
      return (
          <button 
            disabled={isStore || winner !== null || (gameMode === 'PVE' && owner === 2)}
            onClick={() => !isStore && handlePitClick(idx)}
            className={`
                relative flex items-center justify-center rounded-full border-4 shadow-inner
                ${isStore ? 'w-20 h-40 sm:w-28 sm:h-56 bg-amber-200 border-amber-400' : 'w-14 h-14 sm:w-20 sm:h-20 bg-amber-100 border-amber-300'}
                ${!isStore && ((owner === 1 && turn === 1) || (owner === 2 && turn === 2)) ? 'ring-4 ring-yellow-400 cursor-pointer hover:bg-amber-50' : ''}
            `}
          >
              <div className="flex flex-wrap justify-center content-center gap-1 p-2 w-full h-full overflow-hidden">
                  {Array.from({length: Math.min(seeds, 15)}).map((_, i) => (
                      <div key={i} className={`rounded-full shadow-sm ${i % 3 === 0 ? 'bg-blue-500' : i % 3 === 1 ? 'bg-red-500' : 'bg-green-500'} ${isStore ? 'w-4 h-4' : 'w-3 h-3'}`}></div>
                  ))}
                  {seeds > 15 && <span className="text-xs font-bold">+{seeds-15}</span>}
              </div>
              {/* Count Badge */}
              <div className="absolute -bottom-2 bg-white px-2 py-0.5 rounded-full text-xs font-bold border border-gray-300 shadow">
                  {seeds}
              </div>
          </button>
      )
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-cyan-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-cyan-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-cyan-50 rounded-full text-sm font-bold text-cyan-900 border border-cyan-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-cyan-800"><RefreshCw size={20} /></button>
        </div>

        {/* Message */}
        <div className="flex-none text-center py-2 bg-cyan-100 text-cyan-900 font-bold">
            {winner ? (winner === 1 ? "紅方獲勝！" : winner === 2 ? "藍方獲勝！" : "平手") : message}
        </div>

        {/* Board */}
        <div className="flex-1 flex items-center justify-center p-2 sm:p-8 bg-cyan-50 overflow-hidden">
            <div className="bg-[#DEB887] p-4 sm:p-8 rounded-[4rem] shadow-2xl border-8 border-[#8B4513] relative flex items-center gap-2 sm:gap-4">

                {/* P2 Store (Left) */}
                <Pit idx={13} isStore owner={2} />

                {/* Rows Container */}
                <div className="flex flex-col gap-4 sm:gap-8">
                    {/* Top Row (P2) - Indices 12 down to 7 */}
                    <div className="flex gap-2 sm:gap-4">
                        {[12, 11, 10, 9, 8, 7].map(i => <Pit key={i} idx={i} owner={2} />)}
                    </div>
                    {/* Bottom Row (P1) - Indices 0 to 5 */}
                    <div className="flex gap-2 sm:gap-4">
                        {[0, 1, 2, 3, 4, 5].map(i => <Pit key={i} idx={i} owner={1} />)}
                    </div>
                </div>

                {/* P1 Store (Right) */}
                <Pit idx={6} isStore owner={1} />

                {/* Labels */}
                <div className="absolute top-2 left-1/2 -translate-x-1/2 text-[#8B4513] font-bold text-xs sm:text-sm opacity-50">藍方 (電腦/P2)</div>
                <div className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[#8B4513] font-bold text-xs sm:text-sm opacity-50">紅方 (你/P1)</div>
            </div>
        </div>

        {winner && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50">
                <div className="bg-white p-8 rounded-2xl text-center animate-bounce-short shadow-2xl border-4 border-cyan-200">
                    <Trophy className="w-16 h-16 mx-auto mb-4 text-yellow-500"/>
                    <h2 className="text-2xl font-bold mb-2">
                        {winner === 1 ? "紅方獲勝！" : winner === 2 ? "藍方獲勝！" : "平手"}
                    </h2>
                    <p className="text-gray-500 mb-6">比分 {board[6]} : {board[13]}</p>
                    <button onClick={resetGame} className="px-6 py-2 bg-cyan-600 text-white rounded-lg font-bold">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

export default MancalaGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User, Crown } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

const SIZE = 8;
const EMPTY = 0;
// Player 1 (Red/Black) moves DOWN (index increases)
// Player 2 (White) moves UP (index decreases)
interface Piece {
    player: 1 | 2;
    isKing: boolean;
}

const CheckersGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<(Piece | null)[][]>([]);
  const [turn, setTurn] = useState<1 | 2>(1); // 1 = Red, 2 = White
  const [selectedPos, setSelectedPos] = useState<{r: number, c: number} | null>(null);
  const [validMoves, setValidMoves] = useState<{r: number, c: number, isJump: boolean}[]>([]);
  const [winner, setWinner] = useState<number | null>(null);
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');

  useEffect(() => { resetGame(); }, [gameMode]);

  const resetGame = () => {
    const newBoard = Array(SIZE).fill(null).map(() => Array(SIZE).fill(null));
    for (let r = 0; r < SIZE; r++) {
        for (let c = 0; c < SIZE; c++) {
            if ((r + c) % 2 === 1) {
                if (r < 3) newBoard[r][c] = { player: 1, isKing: false }; // P1 Top (Red) moves down
                if (r > 4) newBoard[r][c] = { player: 2, isKing: false }; // P2 Bottom (White) moves up
            }
        }
    }
    setBoard(newBoard);
    setTurn(2); // White usually starts, let's say P2 (Bottom/White) starts for better UI logic (player at bottom)
    setWinner(null);
    setSelectedPos(null);
    setValidMoves([]);
  };

  const isValidPos = (r: number, c: number) => r >= 0 && r < SIZE && c >= 0 && c < SIZE;

  const getMoves = (b: (Piece|null)[][], r: number, c: number, p: Piece) => {
      const moves: {r: number, c: number, isJump: boolean, jumpR?: number, jumpC?: number}[] = [];
      const directions = [];

      // P1 (Red) moves Down (+r), P2 (White) moves Up (-r)
      // Kings move both
      if (p.player === 1 || p.isKing) directions.push([1, -1], [1, 1]);
      if (p.player === 2 || p.isKing) directions.push([-1, -1], [-1, 1]);

      for (const [dr, dc] of directions) {
          // Normal Move
          if (isValidPos(r + dr, c + dc) && b[r + dr][c + dc] === null) {
              moves.push({ r: r + dr, c: c + dc, isJump: false });
          }
          // Jump Move
          if (isValidPos(r + dr * 2, c + dc * 2)) {
              const midR = r + dr, midC = c + dc;
              const midP = b[midR][midC];
              const landP = b[r + dr * 2][c + dc * 2];
              if (midP && midP.player !== p.player && landP === null) {
                  moves.push({ r: r + dr * 2, c: c + dc * 2, isJump: true, jumpR: midR, jumpC: midC });
              }
          }
      }
      return moves;
  };

  const handleSquareClick = (r: number, c: number) => {
      if (winner) return;
      if (gameMode === 'PVE' && turn === 1) return; // P1 is AI (Red/Top)

      const clickedPiece = board[r][c];

      // Select Piece
      if (clickedPiece && clickedPiece.player === turn) {
          setSelectedPos({r, c});
          const moves = getMoves(board, r, c, clickedPiece);
          // Optional rule: Mandatory jumps? For OT simplicity, let's make it flexible or just show options.
          // Let's prioritize jumps visually but allow moves.
          setValidMoves(moves);
          return;
      }

      // Move to empty
      if (!clickedPiece && selectedPos) {
          const move = validMoves.find(m => m.r === r && m.c === c);
          if (move) {
              executeMove(selectedPos.r, selectedPos.c, move);
          }
      }
  };

  const executeMove = (fromR: number, fromC: number, move: any) => {
      const newBoard = board.map(row => row.map(p => p ? {...p} : null));
      const piece = newBoard[fromR][fromC]!;

      // Move
      newBoard[move.r][move.c] = piece;
      newBoard[fromR][fromC] = null;

      // Capture
      if (move.isJump) {
          newBoard[move.jumpR][move.jumpC] = null;
          soundService.playGameSound('FALL');
      } else {
          soundService.playGameSound('BOUNCE');
      }

      // King Promotion
      if ((piece.player === 1 && move.r === SIZE - 1) || (piece.player === 2 && move.r === 0)) {
          piece.isKing = true;
          soundService.playGameSound('HIGH');
      }

      setBoard(newBoard);
      setSelectedPos(null);
      setValidMoves([]);

      // Check Win
      const p1Count = newBoard.flat().filter(p => p?.player === 1).length;
      const p2Count = newBoard.flat().filter(p => p?.player === 2).length;
      if (p1Count === 0) setWinner(2);
      else if (p2Count === 0) setWinner(1);
      else setTurn(turn === 1 ? 2 : 1);
  };

  // AI
  useEffect(() => {
      if (gameMode === 'PVE' && turn === 1 && !winner) {
          const timer = setTimeout(() => {
              const allMoves: any[] = [];
              for(let r=0; r<SIZE; r++){
                  for(let c=0; c<SIZE; c++){
                      const p = board[r][c];
                      if (p && p.player === 1) {
                          const ms = getMoves(board, r, c, p);
                          ms.forEach(m => allMoves.push({fromR: r, fromC: c, ...m}));
                      }
                  }
              }

              if (allMoves.length === 0) {
                  setWinner(2); // AI can't move
                  return;
              }

              // Priority: Jumps -> Promotion -> Random
              const jumps = allMoves.filter(m => m.isJump);
              const promotes = allMoves.filter(m => m.r === SIZE - 1);

              let bestMove;
              if (jumps.length > 0) bestMove = jumps[Math.floor(Math.random() * jumps.length)];
              else if (promotes.length > 0) bestMove = promotes[Math.floor(Math.random() * promotes.length)];
              else bestMove = allMoves[Math.floor(Math.random() * allMoves.length)];

              executeMove(bestMove.fromR, bestMove.fromC, bestMove);

          }, 800);
          return () => clearTimeout(timer);
      }
  }, [turn, board, winner, gameMode]);

  return (
    <div className="flex flex-col h-[100dvh] bg-slate-100 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-slate-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full text-sm font-bold text-slate-900 border border-slate-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-slate-800"><RefreshCw size={20} /></button>
        </div>

        <div className="flex-none text-center py-2 bg-slate-200 font-bold text-slate-700">
            {winner ? (winner === 1 ? "紅方獲勝" : "白方獲勝") : (turn === 1 ? (gameMode==='PVE'?"電腦(紅)回合":"紅方回合") : "白方(你)回合")}
        </div>

        {/* Board */}
        <div className="flex-1 flex flex-col items-center justify-center p-2 bg-slate-100">
            <div className="bg-[#4a3b2a] p-2 rounded shadow-2xl" style={{ width: 'min(90vw, 60vh)', height: 'min(90vw, 60vh)' }}>
                <div className="w-full h-full grid grid-cols-8 grid-rows-8 border-4 border-[#3d2b1f]">
                    {board.map((row, r) => row.map((p, c) => {
                        const isDark = (r + c) % 2 === 1;
                        const isSelected = selectedPos?.r === r && selectedPos?.c === c;
                        const isValidMove = validMoves.some(m => m.r === r && m.c === c);
                        const isJumpTarget = validMoves.some(m => m.r === r && m.c === c && m.isJump);

                        return (
                            <div 
                                key={`${r}-${c}`}
                                onClick={() => handleSquareClick(r, c)}
                                className={`
                                    relative flex items-center justify-center
                                    ${isDark ? 'bg-[#8B4513]' : 'bg-[#DEB887]'}
                                    ${isValidMove ? 'cursor-pointer' : ''}
                                `}
                            >
                                {isValidMove && (
                                    <div className={`absolute w-4 h-4 rounded-full ${isJumpTarget ? 'bg-red-500 animate-pulse' : 'bg-green-500/50'}`}></div>
                                )}
                                {p && (
                                    <div className={`
                                        w-[80%] h-[80%] rounded-full shadow-md border-4 flex items-center justify-center transition-transform
                                        ${p.player === 1 ? 'bg-red-700 border-red-900' : 'bg-slate-200 border-slate-400'}
                                        ${isSelected ? 'scale-110 ring-2 ring-yellow-400' : ''}
                                    `}>
                                        {p.isKing && <Crown size={16} className={p.player === 1 ? 'text-red-200' : 'text-slate-600'} />}
                                    </div>
                                )}
                            </div>
                        );
                    }))}
                </div>
            </div>
        </div>

        {winner && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50">
                <div className="bg-white p-8 rounded-2xl text-center animate-bounce-short shadow-2xl">
                    <Trophy className="w-16 h-16 mx-auto mb-4 text-yellow-500"/>
                    <h2 className="text-2xl font-bold mb-6">
                        {winner === 1 ? "紅方獲勝！" : "白方獲勝！"}
                    </h2>
                    <button onClick={resetGame} className="px-6 py-2 bg-slate-800 text-white rounded-lg font-bold">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

export default CheckersGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User, Crown } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

// 0 = small, 1 = medium, 2 = large
type Size = 0 | 1 | 2;
interface Piece {
    player: 1 | 2;
    size: Size;
    id: string; // Unique ID to track animation or key
}

const GobbletGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  // Board is 3x3 array of stacks. Each cell contains a list of pieces, last one is visible.
  const [board, setBoard] = useState<Piece[][]>(Array(9).fill([]));
  // Inventory: 2 of each size per player. [Small, Small, Medium, Medium, Large, Large]
  const [p1Inv, setP1Inv] = useState<Piece[]>([]);
  const [p2Inv, setP2Inv] = useState<Piece[]>([]);

  const [turn, setTurn] = useState<1 | 2>(1); // 1 = Blue (P1), 2 = Orange (P2/AI)
  const [selectedPiece, setSelectedPiece] = useState<{source: 'board'|'inv', index: number} | null>(null);
  const [winner, setWinner] = useState<number | null>(null);
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');

  useEffect(() => { resetGame(); }, [gameMode]);

  const initPieces = (p: 1 | 2) => [
      {player: p, size: 0, id: `${p}-s1`}, {player: p, size: 0, id: `${p}-s2`},
      {player: p, size: 1, id: `${p}-m1`}, {player: p, size: 1, id: `${p}-m2`},
      {player: p, size: 2, id: `${p}-l1`}, {player: p, size: 2, id: `${p}-l2`}
  ] as Piece[];

  const resetGame = () => {
      setBoard(Array(9).fill([]));
      setP1Inv(initPieces(1));
      setP2Inv(initPieces(2));
      setTurn(1);
      setWinner(null);
      setSelectedPiece(null);
  };

  const checkWin = (b: Piece[][]) => {
      const topPieces = b.map(stack => stack.length > 0 ? stack[stack.length-1] : null);
      const lines = [
          [0,1,2], [3,4,5], [6,7,8], // Rows
          [0,3,6], [1,4,7], [2,5,8], // Cols
          [0,4,8], [2,4,6] // Diagonals
      ];

      for(const line of lines) {
          const p0 = topPieces[line[0]];
          const p1 = topPieces[line[1]];
          const p2 = topPieces[line[2]];
          if (p0 && p1 && p2 && p0.player === p1.player && p1.player === p2.player) {
              return p0.player;
          }
      }
      return null;
  };

  const canPlace = (boardIdx: number, piece: Piece) => {
      const stack = board[boardIdx];
      if (stack.length === 0) return true;
      const top = stack[stack.length - 1];
      return piece.size > top.size;
  };

  const handleInvClick = (player: 1 | 2, idx: number) => {
      if (winner) return;
      if (turn !== player) return;
      if (gameMode === 'PVE' && player === 2) return;

      // Select from inventory
      if (selectedPiece?.source === 'inv' && selectedPiece.index === idx) {
          setSelectedPiece(null);
      } else {
          setSelectedPiece({ source: 'inv', index: idx });
          soundService.playGameSound('LOW');
      }
  };

  const handleBoardClick = (idx: number) => {
      if (winner) return;
      if (gameMode === 'PVE' && turn === 2) return;

      // 1. If trying to select a piece ON the board to move it
      const stack = board[idx];
      const top = stack.length > 0 ? stack[stack.length-1] : null;

      if (!selectedPiece) {
          if (top && top.player === turn) {
              setSelectedPiece({ source: 'board', index: idx });
              soundService.playGameSound('LOW');
          }
          return;
      }

      // 2. If placing a selected piece
      let pieceToMove: Piece | null = null;
      if (selectedPiece.source === 'inv') {
          const inv = turn === 1 ? p1Inv : p2Inv;
          pieceToMove = inv[selectedPiece.index];
      } else {
          // Moving from board
          // Cannot move to same spot
          if (selectedPiece.index === idx) {
              setSelectedPiece(null);
              return;
          }
          pieceToMove = board[selectedPiece.index][board[selectedPiece.index].length - 1];
      }

      if (canPlace(idx, pieceToMove)) {
          executeMove(selectedPiece, idx);
      } else {
          soundService.playWrong();
          // Invalid move feedback could go here
      }
  };

  const executeMove = (from: {source: 'board'|'inv', index: number}, toIdx: number) => {
      const newBoard = board.map(s => [...s]);
      let piece: Piece;

      // Remove from source
      if (from.source === 'inv') {
          if (turn === 1) {
              piece = p1Inv[from.index];
              const newInv = [...p1Inv];
              newInv.splice(from.index, 1);
              setP1Inv(newInv);
          } else {
              piece = p2Inv[from.index];
              const newInv = [...p2Inv];
              newInv.splice(from.index, 1);
              setP2Inv(newInv);
          }
      } else {
          piece = newBoard[from.index].pop()!;
      }

      // Add to dest
      newBoard[toIdx].push(piece);
      setBoard(newBoard);
      setSelectedPiece(null);
      soundService.playGameSound('BOUNCE');

      // Check Win
      const w = checkWin(newBoard);
      if (w) {
          setWinner(w);
          soundService.playWin();
      } else {
          setTurn(turn === 1 ? 2 : 1);
      }
  };

  // AI
  useEffect(() => {
      if (gameMode === 'PVE' && turn === 2 && !winner) {
          const timer = setTimeout(() => {
              // AI Logic:
              // 1. Can win?
              // 2. Must block?
              // 3. Random valid move

              // Get all possible moves for AI
              const moves: {source: 'inv'|'board', index: number, target: number, piece: Piece}[] = [];

              // Inventory moves
              p2Inv.forEach((p, i) => {
                  for(let b=0; b<9; b++) {
                      if (canPlace(b, p)) moves.push({source: 'inv', index: i, target: b, piece: p});
                  }
              });

              // Board moves (simplified: AI rarely moves existing pieces to avoid complexity, but allowed)
              board.forEach((stack, i) => {
                  if (stack.length > 0 && stack[stack.length-1].player === 2) {
                      const p = stack[stack.length-1];
                      for(let b=0; b<9; b++) {
                          if (b !== i && canPlace(b, p)) moves.push({source: 'board', index: i, target: b, piece: p});
                      }
                  }
              });

              // Scoring
              let bestMove = null;
              // Simple random for now, could act smarter
              if (moves.length > 0) {
                  // Filter for winning moves
                  for(const m of moves) {
                      // Simulate
                      const tempBoard = board.map(s => [...s]);
                      if (m.source==='board') tempBoard[m.index].pop();
                      tempBoard[m.target].push(m.piece);
                      if (checkWin(tempBoard) === 2) {
                          bestMove = m;
                          break;
                      }
                  }

                  if (!bestMove) {
                      // Random
                      bestMove = moves[Math.floor(Math.random() * moves.length)];
                  }

                  executeMove({source: bestMove.source, index: bestMove.index}, bestMove.target);
              }

          }, 800);
          return () => clearTimeout(timer);
      }
  }, [turn, board, winner, gameMode]);

  const PieceRender = ({ p }: { p: Piece }) => {
      const sizeClass = p.size === 0 ? 'w-8 h-8 sm:w-10 sm:h-10' : p.size === 1 ? 'w-12 h-12 sm:w-16 sm:h-16' : 'w-16 h-16 sm:w-20 sm:h-20';
      const colorClass = p.player === 1 ? 'bg-blue-500 border-blue-700 text-white' : 'bg-orange-500 border-orange-700 text-white';
      return (
          <div className={`${sizeClass} ${colorClass} rounded-full border-b-4 flex items-center justify-center shadow-lg font-black text-xs sm:text-base z-10 transition-all`}>
              {p.size === 0 ? 'S' : p.size === 1 ? 'M' : 'L'}
          </div>
      );
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-orange-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-orange-50 rounded-full text-sm font-bold text-orange-900 border border-orange-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><RefreshCw size={20} /></button>
        </div>

        <div className="flex-none text-center py-1 font-bold text-orange-800">
            {winner ? (winner === 1 ? "藍方獲勝！" : "橘方獲勝！") : (turn === 1 ? "藍方回合 (你)" : (gameMode==='PVE'?"電腦思考中...":"橘方回合"))}
        </div>

        {/* Game Area */}
        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 gap-4 overflow-hidden">

            {/* Inventory P1 (Blue) */}
            <div className={`flex flex-row sm:flex-col gap-2 p-2 rounded-xl bg-blue-100/50 ${turn === 1 ? 'ring-2 ring-blue-400' : 'opacity-70'}`}>
                {p1Inv.map((p, i) => (
                    <button 
                        key={p.id} 
                        onClick={() => handleInvClick(1, i)}
                        className={`transition-transform ${selectedPiece?.source === 'inv' && selectedPiece.index === i && turn===1 ? 'scale-110 ring-2 ring-yellow-400 rounded-full' : ''}`}
                    >
                        <PieceRender p={p} />
                    </button>
                ))}
                {p1Inv.length === 0 && <div className="w-12 h-12 rounded-full border-2 border-dashed border-blue-300"></div>}
            </div>

            {/* Board */}
            <div className="bg-white p-2 rounded-xl shadow-2xl border-4 border-orange-200 aspect-square h-[min(80vw,50vh)] w-[min(80vw,50vh)] grid grid-cols-3 grid-rows-3 gap-2">
                {board.map((stack, i) => {
                    const top = stack.length > 0 ? stack[stack.length-1] : null;
                    const isTarget = selectedPiece && canPlace(i, selectedPiece.source==='inv' ? (turn===1?p1Inv:p2Inv)[selectedPiece.index] : board[selectedPiece.index][board[selectedPiece.index].length-1]);
                    const isSource = selectedPiece?.source === 'board' && selectedPiece.index === i;

                    return (
                        <button 
                            key={i}
                            onClick={() => handleBoardClick(i)}
                            className={`
                                relative bg-orange-50 rounded-lg flex items-center justify-center border-2 border-orange-100
                                ${isTarget ? 'bg-green-100 border-green-300 animate-pulse' : ''}
                                ${isSource ? 'ring-4 ring-yellow-400 z-20' : ''}
                            `}
                        >
                            {/* Render underlying pieces faintly? No, just top piece in Gobblet */}
                            {top && <PieceRender p={top} />}
                        </button>
                    )
                })}
            </div>

            {/* Inventory P2 (Orange) */}
            <div className={`flex flex-row sm:flex-col gap-2 p-2 rounded-xl bg-orange-100/50 ${turn === 2 ? 'ring-2 ring-orange-400' : 'opacity-70'}`}>
                {p2Inv.map((p, i) => (
                    <button 
                        key={p.id} 
                        onClick={() => handleInvClick(2, i)}
                        disabled={gameMode === 'PVE'}
                        className={`transition-transform ${selectedPiece?.source === 'inv' && selectedPiece.index === i && turn===2 ? 'scale-110 ring-2 ring-yellow-400 rounded-full' : ''}`}
                    >
                        <PieceRender p={p} />
                    </button>
                ))}
                {p2Inv.length === 0 && <div className="w-12 h-12 rounded-full border-2 border-dashed border-orange-300"></div>}
            </div>

        </div>

        {winner && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50">
                <div className="bg-white p-8 rounded-2xl text-center animate-bounce-short shadow-2xl border-4 border-orange-200">
                    <Trophy className="w-16 h-16 mx-auto mb-4 text-yellow-500"/>
                    <h2 className="text-2xl font-bold mb-6">
                        {winner === 1 ? "藍方獲勝！" : "橘方獲勝！"}
                    </h2>
                    <button onClick={resetGame} className="px-6 py-2 bg-orange-600 text-white rounded-lg font-bold">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

export default GobbletGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User, Gem } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

// 0-5: Player 1 Pits
// 6: Player 1 Store
// 7-12: Player 2 Pits (Top, reversed visually)
// 13: Player 2 Store
const TOTAL_PITS = 14;
const P1_STORE = 6;
const P2_STORE = 13;

const MancalaGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  const [board, setBoard] = useState<number[]>([]);
  const [turn, setTurn] = useState(1); // 1 = P1 (Bottom), 2 = P2 (Top)
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');
  const [winner, setWinner] = useState<number | null>(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    resetGame();
  }, [gameMode]);

  const resetGame = () => {
    // Initial seeds: 4 per pit, 0 in stores
    const newBoard = Array(TOTAL_PITS).fill(4);
    newBoard[P1_STORE] = 0;
    newBoard[P2_STORE] = 0;
    setBoard(newBoard);
    setTurn(1);
    setWinner(null);
    setMessage(gameMode === 'PVE' ? "請點擊下方你的洞" : "紅方回合 (下方)");
  };

  const checkEndGame = (currentBoard: number[]) => {
      const p1Empty = currentBoard.slice(0, 6).every(seeds => seeds === 0);
      const p2Empty = currentBoard.slice(7, 13).every(seeds => seeds === 0);

      if (p1Empty || p2Empty) {
          // Capture remainders
          const finalBoard = [...currentBoard];
          let p1Rem = 0;
          for(let i=0; i<6; i++) { p1Rem += finalBoard[i]; finalBoard[i] = 0; }
          let p2Rem = 0;
          for(let i=7; i<13; i++) { p2Rem += finalBoard[i]; finalBoard[i] = 0; }

          finalBoard[P1_STORE] += p1Rem;
          finalBoard[P2_STORE] += p2Rem;
          setBoard(finalBoard);

          if (finalBoard[P1_STORE] > finalBoard[P2_STORE]) setWinner(1);
          else if (finalBoard[P2_STORE] > finalBoard[P1_STORE]) setWinner(2);
          else setWinner(3); // Draw

          soundService.playWin();
          return true;
      }
      return false;
  };

  const handlePitClick = (index: number) => {
      if (winner) return;
      if (gameMode === 'PVE' && turn === 2) return;

      // Validate move
      if (turn === 1 && (index < 0 || index > 5)) return;
      if (turn === 2 && (index < 7 || index > 12)) return;
      if (board[index] === 0) return;

      move(index);
  };

  const move = (startIndex: number) => {
      let newBoard = [...board];
      let seeds = newBoard[startIndex];
      newBoard[startIndex] = 0;
      soundService.playGameSound('RISE');

      let currentIndex = startIndex;
      while (seeds > 0) {
          currentIndex = (currentIndex + 1) % TOTAL_PITS;
          // Skip opponent's store
          if (turn === 1 && currentIndex === P2_STORE) continue;
          if (turn === 2 && currentIndex === P1_STORE) continue;

          newBoard[currentIndex]++;
          seeds--;
      }

      // Rules check
      const lastIndex = currentIndex;
      let nextTurn = turn === 1 ? 2 : 1;
      let extraTurn = false;

      // 1. Land in own store -> Free turn
      if ((turn === 1 && lastIndex === P1_STORE) || (turn === 2 && lastIndex === P2_STORE)) {
          nextTurn = turn;
          extraTurn = true;
          setMessage(turn === 1 ? "再一次！ (紅方)" : (gameMode === 'PVE' ? "電腦再一次" : "再一次！ (藍方)"));
          soundService.playGameSound('HIGH');
      } 
      // 2. Capture: Land in empty own pit across from non-empty opponent pit
      else if (
          newBoard[lastIndex] === 1 && 
          ((turn === 1 && lastIndex >= 0 && lastIndex <= 5) || (turn === 2 && lastIndex >= 7 && lastIndex <= 12))
      ) {
          const oppositeIndex = 12 - lastIndex;
          if (newBoard[oppositeIndex] > 0) {
              const captured = newBoard[oppositeIndex] + 1;
              newBoard[oppositeIndex] = 0;
              newBoard[lastIndex] = 0;
              newBoard[turn === 1 ? P1_STORE : P2_STORE] += captured;
              soundService.playGameSound('BOUNCE');
          }
      }

      setBoard(newBoard);

      if (!checkEndGame(newBoard)) {
          if (!extraTurn) {
              setTurn(nextTurn);
              setMessage(nextTurn === 1 ? (gameMode === 'PVE' ? "換你 (紅方)" : "紅方回合") : (gameMode === 'PVE' ? "電腦思考中..." : "藍方回合"));
          }
      }
  };

  // AI
  useEffect(() => {
      if (gameMode === 'PVE' && turn === 2 && !winner) {
          const timer = setTimeout(() => {
              // Heuristic:
              // 1. Prioritize free turns
              // 2. Prioritize captures
              // 3. Pick right-most pit (to clear side) or random

              const validMoves = [];
              for(let i=7; i<=12; i++) if (board[i] > 0) validMoves.push(i);

              if (validMoves.length === 0) return; // Should be handled by game over check, but safety

              let bestMove = validMoves[0];
              let bestScore = -1;

              for (const m of validMoves) {
                  let score = 0;
                  // Lookahead simulation (simple)
                  let seeds = board[m];
                  let endPos = (m + seeds) % 14; 
                  // Correction for skipping P1 Store roughly
                  // Simplification: if endPos lands on 13 (P2 Store), +50

                  // Accurate calculation for landing position needed for heuristic?
                  // Let's just do simple math
                  let steps = seeds;
                  let curr = m;
                  while(steps > 0) {
                      curr = (curr + 1) % 14;
                      if (curr !== P1_STORE) steps--;
                  }

                  if (curr === P2_STORE) score += 50; // Free turn
                  if (board[curr] === 0 && curr >= 7 && curr <= 12 && board[12-curr] > 0) score += 20 + board[12-curr]; // Capture

                  score += Math.random() * 5; // Randomness

                  if (score > bestScore) {
                      bestScore = score;
                      bestMove = m;
                  }
              }

              move(bestMove);

          }, 800);
          return () => clearTimeout(timer);
      }
  }, [turn, board, winner, gameMode]);

  const Pit: React.FC<{ idx: number; isStore?: boolean; owner?: number }> = ({ idx, isStore = false, owner = 0 }) => {
      const seeds = board[idx] || 0;
      // Visual seeds: randomly jittered dots
      return (
          <button 
            disabled={isStore || winner !== null || (gameMode === 'PVE' && owner === 2)}
            onClick={() => !isStore && handlePitClick(idx)}
            className={`
                relative flex items-center justify-center rounded-full border-4 shadow-inner
                ${isStore ? 'w-20 h-40 sm:w-28 sm:h-56 bg-amber-200 border-amber-400' : 'w-14 h-14 sm:w-20 sm:h-20 bg-amber-100 border-amber-300'}
                ${!isStore && ((owner === 1 && turn === 1) || (owner === 2 && turn === 2)) ? 'ring-4 ring-yellow-400 cursor-pointer hover:bg-amber-50' : ''}
            `}
          >
              <div className="flex flex-wrap justify-center content-center gap-1 p-2 w-full h-full overflow-hidden">
                  {Array.from({length: Math.min(seeds, 15)}).map((_, i) => (
                      <div key={i} className={`rounded-full shadow-sm ${i % 3 === 0 ? 'bg-blue-500' : i % 3 === 1 ? 'bg-red-500' : 'bg-green-500'} ${isStore ? 'w-4 h-4' : 'w-3 h-3'}`}></div>
                  ))}
                  {seeds > 15 && <span className="text-xs font-bold">+{seeds-15}</span>}
              </div>
              {/* Count Badge */}
              <div className="absolute -bottom-2 bg-white px-2 py-0.5 rounded-full text-xs font-bold border border-gray-300 shadow">
                  {seeds}
              </div>
          </button>
      )
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-cyan-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-cyan-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-cyan-50 rounded-full text-sm font-bold text-cyan-900 border border-cyan-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-cyan-800"><RefreshCw size={20} /></button>
        </div>

        {/* Message */}
        <div className="flex-none text-center py-2 bg-cyan-100 text-cyan-900 font-bold">
            {winner ? (winner === 1 ? "紅方獲勝！" : winner === 2 ? "藍方獲勝！" : "平手") : message}
        </div>

        {/* Board */}
        <div className="flex-1 flex items-center justify-center p-2 sm:p-8 bg-cyan-50 overflow-hidden">
            <div className="bg-[#DEB887] p-4 sm:p-8 rounded-[4rem] shadow-2xl border-8 border-[#8B4513] relative flex items-center gap-2 sm:gap-4">

                {/* P2 Store (Left) */}
                <Pit idx={13} isStore owner={2} />

                {/* Rows Container */}
                <div className="flex flex-col gap-4 sm:gap-8">
                    {/* Top Row (P2) - Indices 12 down to 7 */}
                    <div className="flex gap-2 sm:gap-4">
                        {[12, 11, 10, 9, 8, 7].map(i => <Pit key={i} idx={i} owner={2} />)}
                    </div>
                    {/* Bottom Row (P1) - Indices 0 to 5 */}
                    <div className="flex gap-2 sm:gap-4">
                        {[0, 1, 2, 3, 4, 5].map(i => <Pit key={i} idx={i} owner={1} />)}
                    </div>
                </div>

                {/* P1 Store (Right) */}
                <Pit idx={6} isStore owner={1} />

                {/* Labels */}
                <div className="absolute top-2 left-1/2 -translate-x-1/2 text-[#8B4513] font-bold text-xs sm:text-sm opacity-50">藍方 (電腦/P2)</div>
                <div className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[#8B4513] font-bold text-xs sm:text-sm opacity-50">紅方 (你/P1)</div>
            </div>
        </div>

        {winner && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/50">
                <div className="bg-white p-8 rounded-2xl text-center animate-bounce-short shadow-2xl border-4 border-cyan-200">
                    <Trophy className="w-16 h-16 mx-auto mb-4 text-yellow-500"/>
                    <h2 className="text-2xl font-bold mb-2">
                        {winner === 1 ? "紅方獲勝！" : winner === 2 ? "藍方獲勝！" : "平手"}
                    </h2>
                    <p className="text-gray-500 mb-6">比分 {board[6]} : {board[13]}</p>
                    <button onClick={resetGame} className="px-6 py-2 bg-cyan-600 text-white rounded-lg font-bold">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

