  const executeMove = (from: {source: 'board'|'inv', index: number}, toIdx: number) => {
      const newBoard = board.map(s => [...s]);
      let piece: Piece;

      // Remove from source
      if (from.source === 'inv') {
          if (turn === 1) {
              piece = p1Inv[from.index];
              const newInv = [...p1Inv];
              newInv.splice(from.index, 1);
              setP1Inv(newInv);
          } else {
              piece = p2Inv[from.index];
              const newInv = [...p2Inv];
              newInv.splice(from.index, 1);
              setP2Inv(newInv);
          }
