      const boardSizeClass = p.size === 0 ? 'w-[40%] h-[40%]' : p.size === 1 ? 'w-[65%] h-[65%]' : 'w-[90%] h-[90%]';

      const sizeClass = isBoard ? boardSizeClass : fixedSizeClass;
      const colorClass = p.player === 1 ? 'bg-blue-500 border-blue-700 text-white' : 'bg-orange-500 border-orange-700 text-white';

      return (
          <div className={`${sizeClass} ${colorClass} aspect-square rounded-full border-b-4 flex items-center justify-center shadow-lg font-black text-xs sm:text-base z-10 transition-all`}>
              {p.size === 0 ? 'S' : p.size === 1 ? 'M' : 'L'}
          </div>
      );
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-orange-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-orange-50 rounded-full text-sm font-bold text-orange-900 border border-orange-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><RefreshCw size={20} /></button>
        </div>

        <div className="flex-none text-center py-1 font-bold text-orange-800">
            {winner ? (winner === 1 ? "藍方獲勝！" : "橘方獲勝！") : (turn === 1 ? "藍方回合 (你)" : (gameMode==='PVE'?"電腦思考中...":"橘方回合"))}
        </div>

        {/* Game Area - Responsive Layout */}
        <div className="flex-1 flex flex-col sm:flex-row items-center justify-center p-2 gap-2 sm:gap-6 overflow-hidden w-full max-h-full">

            {/* Inventory P2 (Orange) - Top in Portrait, Right in Landscape */}
            <div className={`
                flex-none
                order-1 sm:order-3
                p-2 rounded-xl bg-orange-100/50 
                grid grid-cols-6 sm:grid-cols-2 gap-2 
                justify-center items-center overflow-y-auto
                w-full sm:w-auto h-auto sm:max-h-full
                ${turn === 2 ? 'ring-2 ring-orange-400' : 'opacity-70'}
            `}>
                {p2Inv.map((p, i) => (
                    <button 
                        key={p.id} 
                        onClick={() => handleInvClick(2, i)}
                        disabled={gameMode === 'PVE'}
                        className={`transition-transform aspect-square flex items-center justify-center ${selectedPiece?.source === 'inv' && selectedPiece.index === i && turn===2 ? 'scale-110 ring-2 ring-yellow-400 rounded-full' : ''}`}
                    >
                        <PieceRender p={p} isBoard={false} />
                    </button>
                ))}
                {/* Fillers to maintain grid shape if empty */}
                {p2Inv.length === 0 && <div className="w-10 h-10 opacity-0"></div>}
            </div>

            {/* Board - Centered & Scaled - Middle order */}
            {/* Updated width constraint to min(95vw, 60vh) to fit landscape height without cropping */}
            <div className="order-2 flex-1 flex flex-col items-center justify-center" style={{ width: 'min(95vw, 60vh)' }}>
                {/* Top Labels (A-C) */}
