                    >
                        {board.map((stack, i) => {
                            const top = stack.length > 0 ? stack[stack.length-1] : null;
                            const isTarget = selectedPiece && canPlace(i, selectedPiece.source==='inv' ? (turn===1?p1Inv:p2Inv)[selectedPiece.index] : board[selectedPiece.index][board[selectedPiece.index].length-1]);
                            const isSource = selectedPiece?.source === 'board' && selectedPiece.index === i;

                            return (
                                <button 
                                    key={i}
                                    onClick={() => handleBoardClick(i)}
                                    className={`
                                        relative bg-orange-50 rounded-lg flex items-center justify-center border-2 border-orange-100 w-full h-full aspect-square
                                        ${isTarget ? 'bg-green-100 border-green-300 animate-pulse' : ''}
                                        ${isSource ? 'ring-4 ring-yellow-400 z-20' : ''}
                                    `}
                                >
                                    {/* Using isBoard=true allows pieces to scale via % instead of fixed px */}
                                    {top && <PieceRender p={top} isBoard={true} />}
                                </button>
                            )
