                justify-center items-center overflow-y-auto
                w-full sm:w-auto h-auto sm:max-h-full
                ${turn === 1 ? 'ring-2 ring-blue-400' : 'opacity-70'}
            `}>
                {p1Inv.map((p, i) => (
                    <button 
                        key={p.id} 
                        onClick={() => handleInvClick(1, i)}
                        className={`transition-transform aspect-square flex items-center justify-center ${selectedPiece?.source === 'inv' && selectedPiece.index === i && turn===1 ? 'scale-110 ring-2 ring-yellow-400 rounded-full' : ''}`}
                    >
                        <PieceRender p={p} isBoard={false} />
                    </button>
                ))}
                {/* Fillers to maintain grid shape if empty */}
                {p1Inv.length === 0 && <div className="w-10 h-10 opacity-0"></div>}
