  const [grid, setGrid] = useState<(Piece | null)[]>(Array(32).fill(null));
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [isRedTurn, setIsRedTurn] = useState(true); 
  const [playerColor, setPlayerColor] = useState<'RED' | 'BLACK' | null>(null); 
  const [log, setLog] = useState("點擊棋子翻牌");
  const [gameOver, setGameOver] = useState(false);
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');

  useEffect(() => { initGame(); }, []);
  useEffect(() => { initGame(); }, [gameMode]);

  const initGame = () => {
    let all: Piece[] = [];
    let id = 0;
    RED_PIECES.forEach(p => all.push({id: id++, text: p, isRed: true, rank: RANKS[p], revealed: false, dead: false}));
    BLK_PIECES.forEach(p => all.push({id: id++, text: p, isRed: false, rank: RANKS[p], revealed: false, dead: false}));
    for (let i = all.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [all[i], all[j]] = [all[j], all[i]];
    }
    setGrid(all);
    setSelectedIdx(null);
    setIsRedTurn(true);
    setPlayerColor(null);
    setLog("遊戲開始！請翻牌");
    setGameOver(false);
  };

  const getAdjacents = (idx: number) => {
      const row = Math.floor(idx / COLS);
      const col = idx % COLS;
      const adjs = [];
      if (row > 0) adjs.push(idx - COLS);
      if (row < ROWS - 1) adjs.push(idx + COLS);
      if (col > 0) adjs.push(idx - 1);
      if (col < COLS - 1) adjs.push(idx + 1);
      return adjs;
  };

  const canEat = (src: Piece, dst: Piece) => {
      if (src.rank === 2) return false;
      if (src.rank === 1 && dst.rank === 7) return true;
      if (src.rank === 7 && dst.rank === 1) return false;
      if (src.rank >= dst.rank) return true;
      return false;
  };

  const canCannonEat = (srcIdx: number, dstIdx: number, board: (Piece|null)[]) => {
      const r1 = Math.floor(srcIdx / COLS), c1 = srcIdx % COLS;
      const r2 = Math.floor(dstIdx / COLS), c2 = dstIdx % COLS;
      if (r1 !== r2 && c1 !== c2) return false;
      let screens = 0;
      if (r1 === r2) {
          const start = Math.min(c1, c2) + 1;
          const end = Math.max(c1, c2);
          for (let c = start; c < end; c++) {
              const idx = r1 * COLS + c;
              if (board[idx] && !board[idx]?.dead) screens++;
          }
      } else {
          const start = Math.min(r1, r2) + 1;
          const end = Math.max(r1, r2);
          for (let r = start; r < end; r++) {
              const idx = r * COLS + c1;
              if (board[idx] && !board[idx]?.dead) screens++;
          }
      }
      return screens === 1;
  };

  const handleTileClick = (idx: number) => {
      if (gameOver) return;
      if (gameMode === 'PVE' && playerColor) {
          const isAiTurn = (playerColor === 'RED' && !isRedTurn) || (playerColor === 'BLACK' && isRedTurn);
          if (isAiTurn) return;
      }
      const target = grid[idx];

      // 1. Reveal hidden piece
      if (target && !target.revealed) {
          if (selectedIdx !== null) { setSelectedIdx(null); return; }
          const newGrid = [...grid];
          if (newGrid[idx]) newGrid[idx]!.revealed = true;
          setGrid(newGrid);
          soundService.playGameSound('BOUNCE');

          if (!playerColor) {
              const revealedIsRed = newGrid[idx]!.isRed;
              const pColor = revealedIsRed ? 'RED' : 'BLACK';
              if (gameMode === 'PVE') setPlayerColor(pColor);
              setLog(`翻開 ${newGrid[idx]!.text}`);
              // Fix: If revealed Black (isRed=false), next turn is Red (true). 
              // If revealed Red (isRed=true), next turn is Black (false).
              setIsRedTurn(!revealedIsRed);
          } else {
              setLog(`翻開了 ${newGrid[idx]!.text}`);
              endTurn();
          }
          return;
      }

      // 2. Select own piece
      if (target && target.revealed && target.isRed === isRedTurn) {
          if (selectedIdx === idx) setSelectedIdx(null);
          else { setSelectedIdx(idx); soundService.playGameSound('HIGH'); }
          return;
      }

      // 3. Move or Capture
      if (selectedIdx !== null) {
          const attacker = grid[selectedIdx]!;

          // Move to empty
          if (!target) {
              const isAdjacent = getAdjacents(selectedIdx).includes(idx);
              if (isAdjacent) { 
                  movePiece(selectedIdx, idx); 
              } else {
                  // Optional: visual feedback for invalid move
                  setSelectedIdx(null);
              }
              return;
          }

          // Capture enemy
          if (target && target.revealed && target.isRed !== attacker.isRed) {
              const isAdjacent = getAdjacents(selectedIdx).includes(idx);
              if (attacker.rank === 2) {
                  if (canCannonEat(selectedIdx, idx, grid)) capturePiece(selectedIdx, idx);
                  else setSelectedIdx(null);
              } else {
                  if (isAdjacent && canEat(attacker, target)) capturePiece(selectedIdx, idx);
                  else setSelectedIdx(null);
              }
          }
      }
  };

  const movePiece = (from: number, to: number) => {
      const newGrid = [...grid];
      newGrid[to] = newGrid[from];
      newGrid[from] = null;
      setGrid(newGrid);
      setSelectedIdx(null);
      soundService.playGameSound('FALL');
      endTurn();
  };

  const capturePiece = (from: number, to: number) => {
      const newGrid = [...grid];
      const victim = newGrid[to]!;
      victim.dead = true; 
      newGrid[to] = newGrid[from];
      newGrid[from] = null;
      setGrid(newGrid);
      setSelectedIdx(null);
      soundService.playGameSound('RISE'); 
      setLog(`吃了 ${victim.text}`);
      checkWinCondition(newGrid);
      endTurn();
  };

  const checkWinCondition = (b: (Piece|null)[]) => {
      const activeRed = b.filter(p => p && !p.dead && p.isRed).length;
      const activeBlk = b.filter(p => p && !p.dead && !p.isRed).length;
      if (activeRed === 0) { setGameOver(true); setLog("黑方獲勝！"); soundService.playWin(); }
      else if (activeBlk === 0) { setGameOver(true); setLog("紅方獲勝！"); soundService.playWin(); }
  };

  const endTurn = () => { setIsRedTurn(!isRedTurn); };

  useEffect(() => {
      if (gameMode === 'PVE' && playerColor && !gameOver) {
          const isAiTurn = (playerColor === 'RED' && !isRedTurn) || (playerColor === 'BLACK' && isRedTurn);
          if (isAiTurn) {
              const timer = setTimeout(() => { executeAiMove(); }, 1000);
              return () => clearTimeout(timer);
          }
      }
  }, [isRedTurn, playerColor, gameOver, gameMode]);

  const executeAiMove = () => {
      const aiColorRed = playerColor === 'BLACK'; 
      if (aiColorRed !== isRedTurn) return; 
      const actions: any[] = [];
      grid.forEach((p, idx) => {
          if (p && !p.revealed && !p.dead) actions.push({type: 'REVEAL', to: idx, score: 10 + Math.random() * 5});
      });
      grid.forEach((p, idx) => {
          if (p && p.revealed && !p.dead && p.isRed === aiColorRed) {
              const adjs = getAdjacents(idx);
              adjs.forEach(adj => {
                  const target = grid[adj];
                  if (!target) actions.push({type: 'MOVE', from: idx, to: adj, score: 1}); 
                  else if (target.revealed && target.isRed !== aiColorRed && p.rank !== 2) {
                      if (canEat(p, target)) actions.push({type: 'CAPTURE', from: idx, to: adj, score: 50 + target.rank * 10}); 
                  }
              });
              if (p.rank === 2) {
                  grid.forEach((t, tIdx) => {
                      if (t && t.revealed && !t.dead && t.isRed !== aiColorRed) {
                          if (canCannonEat(idx, tIdx, grid)) actions.push({type: 'CAPTURE', from: idx, to: tIdx, score: 60 + t.rank * 10});
                      }
                  });
              }
          }
      });
      if (actions.length === 0) { setIsRedTurn(!isRedTurn); return; }
      actions.sort((a, b) => b.score - a.score);
      const best = actions[0];
      if (best.type === 'REVEAL') {
          const newGrid = [...grid];
          newGrid[best.to]!.revealed = true;
          setGrid(newGrid);
          setLog(`電腦翻開 ${newGrid[best.to]!.text}`);
          soundService.playGameSound('BOUNCE');

          // AI Reveal Logic: Check color if AI triggered the first move (rare but possible if logic changes)
          // Since AI only moves after P1 flips, we usually just endTurn.
          // However, if we implement "AI goes first" later, we'd need the same logic.
          // Current logic assumes Player always flips first. 
          endTurn();

      } else if (best.type === 'MOVE') movePiece(best.from!, best.to);
      else if (best.type === 'CAPTURE') capturePiece(best.from!, best.to);
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-amber-50 overflow-hidden">
        {/* Compact Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-[#f7e7ce] shadow-sm z-10 border-b border-amber-200 h-12 sm:h-14">
            <button onClick={onBack} className="p-1.5 bg-white/50 rounded-full text-amber-900"><ArrowLeft size={18} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-3 py-1.5 bg-white/50 rounded-full text-xs sm:text-sm font-bold text-amber-900 border border-amber-300"
            >
                {gameMode === 'PVE' ? <User size={14} /> : <Users size={14} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={initGame} className="p-1.5 bg-white/50 rounded-full text-amber-900"><RefreshCw size={18} /></button>
        </div>

        {/* Log */}
        <div className="flex-none text-center py-1 bg-[#f7e7ce] text-amber-900 border-b border-amber-200">
            <div className="font-bold text-sm sm:text-base">{log}</div>
            <div className="text-xs opacity-70">
                {isRedTurn ? "紅方回合" : "黑方回合"} 
                {gameMode === 'PVE' && playerColor && <span className="ml-1">({playerColor === 'RED' ? '你:紅' : '你:黑'})</span>}
            </div>
        </div>

        {/* Board Container - Flex centered */}
        <div className="flex-1 flex flex-col items-center justify-center p-2 bg-amber-100 overflow-hidden">

            {/* 
               CRITICAL FIX: Layout Constraint for Landscape Mode.
               A 2:1 board needs to fit in the screen.
               Reduced max height to 60vh to prevent cropping at bottom in landscape.
            */}
            <div 
                className="relative flex flex-col items-center justify-center w-full"
                style={{ 
                    aspectRatio: '2/1',
                    maxHeight: '60vh', // Further reduced from 80vh to 60vh
                    maxWidth: '120vh', // Matches 2:1 of 60vh
                    width: '95vw'
                }}
            > 
                {/* Board Wrapper with Coordinates */}
                <div className="w-full h-full flex flex-col">
                    {/* Top Labels */}
                    <div className="flex pl-6 mb-0.5 w-full shrink-0">
                        {COL_LABELS.map(c => (
                            <div key={c} className="flex-1 text-center font-bold text-amber-800 text-[10px] sm:text-xs">{c}</div>
                        ))}
                    </div>

                    <div className="flex w-full flex-1 min-h-0">
                        {/* Left Labels */}
                        <div className="flex flex-col justify-between pr-1 py-1 w-6 shrink-0">
                            {ROW_LABELS.map(r => (
                                <div key={r} className="flex-1 flex items-center justify-center font-bold text-amber-800 text-[10px] sm:text-xs">{r}</div>
                            ))}
                        </div>

                        {/* The Board - Horizontal 8x4 */}
                        <div className="bg-[#DEB887] p-1.5 sm:p-2 rounded shadow-xl border-4 border-[#8B4513] w-full h-full">
                            <div 
                                className="grid gap-1 sm:gap-2 w-full h-full"
                                style={{ 
                                    gridTemplateColumns: `repeat(8, 1fr)`, 
                                    gridTemplateRows: `repeat(4, 1fr)` 
                                }}
                            >
                                {grid.map((piece, idx) => (
                                    <button
                                        key={idx}
                                        onClick={() => handleTileClick(idx)}
                                        type="button"
                                        className={`
                                            relative rounded-full border-2 sm:border-4 shadow-sm w-full h-full
                                            transition-transform active:scale-95
                                            ${!piece ? 'border-transparent bg-black/5 hover:bg-black/10' : ''}
                                            ${piece && !piece.revealed ? 'bg-[#8B4513] border-[#5C3317]' : ''}
                                            ${piece && piece.revealed ? 'bg-[#f7e7ce]' : ''}
                                            ${piece && piece.revealed && piece.isRed ? 'text-red-600 border-red-800' : ''}
                                            ${piece && piece.revealed && !piece.isRed ? 'text-black border-black' : ''}
                                            ${selectedIdx === idx ? 'ring-4 ring-yellow-400 scale-105 z-10' : ''}
                                        `}
                                    >
                                        {/* 
                                            CRITICAL FIX: Absolute positioning for content.
                                            This prevents the button size from jumping when content changes from '?' to Text.
                                            pointer-events-none ensures clicks go to the button logic.
                                        */}
                                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                            {piece && piece.revealed && (
                                                <div className="rounded-full border border-dashed border-current w-[85%] h-[85%] flex items-center justify-center text-base sm:text-xl md:text-3xl font-bold">
                                                    {piece.text}
                                                </div>
                                            )}
                                            {piece && !piece.revealed && (
                                                <div className="opacity-20 text-white text-[10px] sm:text-xs">?</div>
                                            )}
                                        </div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        {gameOver && (
            <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-50">
                <div className="bg-[#f7e7ce] p-6 rounded-xl border-4 border-[#8B4513] text-center shadow-2xl">
                    <Trophy className="w-16 h-16 mx-auto mb-2 text-amber-600"/>
                    <h2 className="text-xl font-bold text-amber-900 mb-4">{log}</h2>
                    <button onClick={initGame} className="px-6 py-2 bg-[#8B4513] text-white rounded font-bold shadow hover:bg-[#5C3317]">再來一局</button>
                </div>
            </div>
        )}
    </div>
  );
};

export default DarkChessGame;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, RefreshCw, Trophy, Users, User, Crown } from 'lucide-react';
import { Difficulty } from '../types';
import { soundService } from '../services/soundService';

interface Props {
  onBack: () => void;
  difficulty?: Difficulty;
}

// 0 = small, 1 = medium, 2 = large
type Size = 0 | 1 | 2;
interface Piece {
    player: 1 | 2;
    size: Size;
    id: string; // Unique ID to track animation or key
}

const GobbletGame: React.FC<Props> = ({ onBack, difficulty = 'NORMAL' }) => {
  // Board is 3x3 array of stacks. Each cell contains a list of pieces, last one is visible.
  const [board, setBoard] = useState<Piece[][]>(Array(9).fill([]));
  // Inventory: 2 of each size per player. [Small, Small, Medium, Medium, Large, Large]
  const [p1Inv, setP1Inv] = useState<Piece[]>([]);
  const [p2Inv, setP2Inv] = useState<Piece[]>([]);

  const [turn, setTurn] = useState<1 | 2>(1); // 1 = Blue (P1), 2 = Orange (P2/AI)
  const [selectedPiece, setSelectedPiece] = useState<{source: 'board'|'inv', index: number} | null>(null);
  const [winner, setWinner] = useState<number | null>(null);
  const [gameMode, setGameMode] = useState<'PVE' | 'PVP'>('PVE');

  useEffect(() => { resetGame(); }, [gameMode]);

  const initPieces = (p: 1 | 2) => [
      {player: p, size: 0, id: `${p}-s1`}, {player: p, size: 0, id: `${p}-s2`},
      {player: p, size: 1, id: `${p}-m1`}, {player: p, size: 1, id: `${p}-m2`},
      {player: p, size: 2, id: `${p}-l1`}, {player: p, size: 2, id: `${p}-l2`}
  ] as Piece[];

  const resetGame = () => {
      setBoard(Array(9).fill([]));
      setP1Inv(initPieces(1));
      setP2Inv(initPieces(2));
      setTurn(1);
      setWinner(null);
      setSelectedPiece(null);
  };

  const checkWin = (b: Piece[][]) => {
      const topPieces = b.map(stack => stack.length > 0 ? stack[stack.length-1] : null);
      const lines = [
          [0,1,2], [3,4,5], [6,7,8], // Rows
          [0,3,6], [1,4,7], [2,5,8], // Cols
          [0,4,8], [2,4,6] // Diagonals
      ];

      for(const line of lines) {
          const p0 = topPieces[line[0]];
          const p1 = topPieces[line[1]];
          const p2 = topPieces[line[2]];
          if (p0 && p1 && p2 && p0.player === p1.player && p1.player === p2.player) {
              return p0.player;
          }
      }
      return null;
  };

  const canPlace = (boardIdx: number, piece: Piece) => {
      const stack = board[boardIdx];
      if (stack.length === 0) return true;
      const top = stack[stack.length - 1];
      return piece.size > top.size;
  };

  const handleInvClick = (player: 1 | 2, idx: number) => {
      if (winner) return;
      if (turn !== player) return;
      if (gameMode === 'PVE' && player === 2) return;

      // Select from inventory
      if (selectedPiece?.source === 'inv' && selectedPiece.index === idx) {
          setSelectedPiece(null);
      } else {
          setSelectedPiece({ source: 'inv', index: idx });
          soundService.playGameSound('LOW');
      }
  };

  const handleBoardClick = (idx: number) => {
      if (winner) return;
      if (gameMode === 'PVE' && turn === 2) return;

      // 1. If trying to select a piece ON the board to move it
      const stack = board[idx];
      const top = stack.length > 0 ? stack[stack.length-1] : null;

      if (!selectedPiece) {
          if (top && top.player === turn) {
              setSelectedPiece({ source: 'board', index: idx });
              soundService.playGameSound('LOW');
          }
          return;
      }

      // 2. If placing a selected piece
      let pieceToMove: Piece | null = null;
      if (selectedPiece.source === 'inv') {
          const inv = turn === 1 ? p1Inv : p2Inv;
          pieceToMove = inv[selectedPiece.index];
      } else {
          // Moving from board
          // Cannot move to same spot
          if (selectedPiece.index === idx) {
              setSelectedPiece(null);
              return;
          }
          pieceToMove = board[selectedPiece.index][board[selectedPiece.index].length - 1];
      }

      if (canPlace(idx, pieceToMove)) {
          executeMove(selectedPiece, idx);
      } else {
          soundService.playWrong();
          // Invalid move feedback could go here
      }
  };

  const executeMove = (from: {source: 'board'|'inv', index: number}, toIdx: number) => {
      const newBoard = board.map(s => [...s]);
      let piece: Piece;

      // Remove from source
      if (from.source === 'inv') {
          if (turn === 1) {
              piece = p1Inv[from.index];
              const newInv = [...p1Inv];
              newInv.splice(from.index, 1);
              setP1Inv(newInv);
          } else {
              piece = p2Inv[from.index];
              const newInv = [...p2Inv];
              newInv.splice(from.index, 1);
              setP2Inv(newInv);
          }
      } else {
          piece = newBoard[from.index].pop()!;
      }

      // Add to dest
      newBoard[toIdx].push(piece);
      setBoard(newBoard);
      setSelectedPiece(null);
      soundService.playGameSound('BOUNCE');

      // Check Win
      const w = checkWin(newBoard);
      if (w) {
          setWinner(w);
          soundService.playWin();
      } else {
          setTurn(turn === 1 ? 2 : 1);
      }
  };

  // AI
  useEffect(() => {
      if (gameMode === 'PVE' && turn === 2 && !winner) {
          const timer = setTimeout(() => {
              // AI Logic:
              // 1. Can win?
              // 2. Must block?
              // 3. Random valid move

              // Get all possible moves for AI
              const moves: {source: 'inv'|'board', index: number, target: number, piece: Piece}[] = [];

              // Inventory moves
              p2Inv.forEach((p, i) => {
                  for(let b=0; b<9; b++) {
                      if (canPlace(b, p)) moves.push({source: 'inv', index: i, target: b, piece: p});
                  }
              });

              // Board moves (simplified: AI rarely moves existing pieces to avoid complexity, but allowed)
              board.forEach((stack, i) => {
                  if (stack.length > 0 && stack[stack.length-1].player === 2) {
                      const p = stack[stack.length-1];
                      for(let b=0; b<9; b++) {
                          if (b !== i && canPlace(b, p)) moves.push({source: 'board', index: i, target: b, piece: p});
                      }
                  }
              });

              // Scoring
              let bestMove = null;
              // Simple random for now, could act smarter
              if (moves.length > 0) {
                  // Filter for winning moves
                  for(const m of moves) {
                      // Simulate
                      const tempBoard = board.map(s => [...s]);
                      if (m.source==='board') tempBoard[m.index].pop();
                      tempBoard[m.target].push(m.piece);
                      if (checkWin(tempBoard) === 2) {
                          bestMove = m;
                          break;
                      }
                  }

                  if (!bestMove) {
                      // Random
                      bestMove = moves[Math.floor(Math.random() * moves.length)];
                  }

                  executeMove({source: bestMove.source, index: bestMove.index}, bestMove.target);
              }

          }, 800);
          return () => clearTimeout(timer);
      }
  }, [turn, board, winner, gameMode]);

  const PieceRender = ({ p, isBoard = false }: { p: Piece, isBoard?: boolean }) => {
      // Fixed sizes for Inventory to maintain consistent button size
      const fixedSizeClass = p.size === 0 ? 'w-6 h-6 sm:w-10 sm:h-10' : p.size === 1 ? 'w-10 h-10 sm:w-14 sm:h-14' : 'w-14 h-14 sm:w-20 sm:h-20';

      // Percentage sizes for Board to scale with the grid container
      const boardSizeClass = p.size === 0 ? 'w-[40%] h-[40%]' : p.size === 1 ? 'w-[65%] h-[65%]' : 'w-[90%] h-[90%]';

      const sizeClass = isBoard ? boardSizeClass : fixedSizeClass;
      const colorClass = p.player === 1 ? 'bg-blue-500 border-blue-700 text-white' : 'bg-orange-500 border-orange-700 text-white';

      return (
          <div className={`${sizeClass} ${colorClass} aspect-square rounded-full border-b-4 flex items-center justify-center shadow-lg font-black text-xs sm:text-base z-10 transition-all`}>
              {p.size === 0 ? 'S' : p.size === 1 ? 'M' : 'L'}
          </div>
      );
  };

  return (
    <div className="flex flex-col h-[100dvh] bg-orange-50 overflow-hidden">
        {/* Header */}
        <div className="flex-none p-2 flex justify-between items-center bg-white shadow-sm z-10 h-14">
            <button onClick={onBack} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><ArrowLeft size={20} /></button>
            <button 
                onClick={() => setGameMode(prev => prev === 'PVE' ? 'PVP' : 'PVE')}
                className="flex items-center gap-2 px-4 py-2 bg-orange-50 rounded-full text-sm font-bold text-orange-900 border border-orange-200"
            >
                {gameMode === 'PVE' ? <User size={16} /> : <Users size={16} />}
                {gameMode === 'PVE' ? '單人' : '雙人'}
            </button>
            <button onClick={resetGame} className="p-1.5 bg-gray-100 rounded-full text-orange-800"><RefreshCw size={20} /></button>
        </div>

        <div className="flex-none text-center py-1 font-bold text-orange-800">
